import{I as a,o as g,c as u,j as t,a as r,J as p,w as n,b6 as h,by as q,bz as d,bA as c,bB as b,bC as m,bD as _,bE as f,bF as P,bG as k,bH as x,bI as A,bJ as I,bK as C,bL as D,bM as S,bN as T,bO as w,bP as B,bQ as L,bR as N,bS as F}from"./chunks/framework.BUXTSoD9.js";const y={style:{margin:"50px 0"}},V=JSON.parse('{"title":"التفكير المنتجي وتصميم الحلول","description":"تعلّم كيف تنتقل من مجرد القدرة على بناء أدوات ذكاء اصطناعي إلى التفكير والتقييم وصقل تطبيق ذكاء اصطناعي ذي رؤية واضحة، وتعرّف على المفاهيم الأساسية والأساليب العملية للتفكير المنتجي.","frontmatter":{"title":"التفكير المنتجي وتصميم الحلول","description":"تعلّم كيف تنتقل من مجرد القدرة على بناء أدوات ذكاء اصطناعي إلى التفكير والتقييم وصقل تطبيق ذكاء اصطناعي ذي رؤية واضحة، وتعرّف على المفاهيم الأساسية والأساليب العملية للتفكير المنتجي."},"headers":[],"relativePath":"ar-sa/stage-1/appendix-a-product-thinking/index.md","filePath":"ar-sa/stage-1/appendix-a-product-thinking/index.md"}'),M={name:"ar-sa/stage-1/appendix-a-product-thinking/index.md"},v=Object.assign(M,{setup(R){const s="حوالي <strong>6 ساعات</strong>";return(E,o)=>{const e=a("ChapterIntroduction"),l=a("StepBar"),i=a("ClientOnly");return g(),u("div",null,[o[1]||(o[1]=t("h1",{id:"التفكير-المنتجي-وتصميم-الحلول",tabindex:"-1"},[r("التفكير المنتجي وتصميم الحلول "),t("a",{class:"header-anchor",href:"#التفكير-المنتجي-وتصميم-الحلول","aria-label":"Permalink to “التفكير المنتجي وتصميم الحلول”"},"​")],-1)),o[2]||(o[2]=t("h2",{id:"مقدمة-الفصل",tabindex:"-1"},[r("مقدمة الفصل "),t("a",{class:"header-anchor",href:"#مقدمة-الفصل","aria-label":"Permalink to “مقدمة الفصل”"},"​")],-1)),p(e,{duration:s,tags:["التفكير المنتجي","تحليل الاحتياجات","تصميم الحلول","رؤى المستخدمين"],coreOutput:"حل منتج واحد متكامل",expectedOutput:"أفكار تصميم منتج قابلة للتنفيذ"},{default:n(()=>[...o[0]||(o[0]=[t("p",null,"في الفصول السابقة، تعلمت بالفعل كيفية بناء أدوات صغيرة متنوعة في z.ai وبيئة تطوير الذكاء الاصطناعي المحلية (AI IDE)، وجربت أيضًا استخدام Trae للتعامل مع مشكلات هندسية مثل إعداد البيئة وتثبيت التبعيات، واكتسبت القدرة على نقل أفكارك من المتصفح إلى مشروع محلي.",-1),t("p",null,[r("بعد ذلك، سننقل تركيزنا من مسألة "),t("strong",null,'"هل يمكنني بناؤه؟"'),r("، إلى مسألة "),t("strong",null,'"ما الذي يجب بناؤه حقًا ليكون جديرًا بالوجود؟"'),r(".")],-1),t("p",null,"في هذا الدرس، سنناقش بشكل منهجي:",-1),t("ul",null,[t("li",null,'ما هي "الفكرة"، وما الذي يجعلها "فكرة جيدة"'),t("li",null,"كيف تحكم على ما إذا كان اتجاه منتج معين يستحق الاستثمار فيه"),t("li",null,"كيف تستخدم عملية قابلة للتكرار لتحويل الإلهام الضبابي إلى خطة تطبيق واضحة")],-1),t("p",null,[t("strong",null,"الهدف الأساسي:"),r(" الترقية من مجرد بناء الأدوات إلى القدرة على صنع تطبيقات ذكاء اصطناعي يستخدمها الناس فعليًا وتخلق قيمة حقيقية.")],-1)])]),_:1}),t("div",y,[p(i,null,{default:n(()=>[p(l,{active:0,items:[{title:"مصدر الأفكار",description:"إيجاد أفكار منتج موثوقة"},{title:"تفكيك الحل",description:"تحويل الفكرة إلى تطبيق قابل للتنفيذ"},{title:"التقييم والصقل",description:"من المقبول إلى الممتاز"},{title:"تضخيم الذكاء الاصطناعي",description:"استخدام الذكاء الاصطناعي بشكل معقول لخلق القيمة"}]})]),_:1})]),o[3]||(o[3]=h('<h2 id="ما-ستتعلمه" tabindex="-1">ما ستتعلمه <a class="header-anchor" href="#ما-ستتعلمه" aria-label="Permalink to “ما ستتعلمه”">​</a></h2><p>بشكل عام، ستتعلم الأساسيات لصنع تطبيق: من أين تأتي الأفكار ← كيف تتحول الفكرة إلى تطبيق ← كيف ينتقل التطبيق من قابل للاستخدام إلى ممتع ← كيفية استخدام الذكاء الاصطناعي في التطبيق ← كيفية إيجاد المستخدمين بعد الانتهاء.</p><ol><li>أريد بناء تطبيق، فمن أين تأتي الأفكار الموثوقة؟</li><li>بمجرد وجود الفكرة، كيف تفكيكها إلى تطبيق قابل للبناء؟</li><li>بعد بنائه، كيف تقيمه وتصقله ليصبح &quot;تطبيقًا جيدًا&quot;؟</li><li>في أي خطوة وكيف تستخدم الذكاء الاصطناعي بشكل معقل لتضخيم القيمة؟</li><li>بمجرد الانتهاء من التطبيق، كيف تجد أول مجموعة من المستخدمين الحقيقيين من الصفر؟</li></ol><h1 id="_1-أريد-بناء-تطبيق،-من-أين-تأتي-الأفكار-الموثوقة" tabindex="-1">1. أريد بناء تطبيق، من أين تأتي الأفكار الموثوقة <a class="header-anchor" href="#_1-أريد-بناء-تطبيق،-من-أين-تأتي-الأفكار-الموثوقة" aria-label="Permalink to “1. أريد بناء تطبيق، من أين تأتي الأفكار الموثوقة”">​</a></h1><p>عندما يذكر الكثير من الناس بناء التطبيقات، فإن رد فعلهم الأول هو: يجب أن أفكر أولاً في فكرة إبداعية لا تُنسى. لذلك، فهم يتصفحون القوائم ويقرؤون التقارير ويدرسون المنتجات الرائجة كل يوم، ويراقبون قصص نجاح الآخرين، على أمل أن يصادفوا يومًا ما فكرة استثنائية وفريدة من نوعها.</p><p>ولكن الحقيقة هي أن الكثير من الناس ليس لديهم أي أفكار في الواقع، وهم يشعرون بالقلق لمجرد أنهم يفتقرون إلى الأفكار؛ وهناك أيضًا أشخاص يضعون لأنفسهم معايير عالية جدًا منذ البداية: إذا لم تكن الفكرة ممتعة بما فيه الكفاية فلن أبدأ، ويعتبرون أن الفكرة العادية تعني الفشل. ولكن عندما تتقدم قليلاً في هذا الطريق، ستكتشف أن التطبيقات التي تستمر وتظل ثابتة هي في الغالب ليست نتاج خاطرة طرأت في وقت متأخر من الليل، بل نبتت تدريجيًا في سيناريوهات حياة محددة، وتمحورت حول مشاكل حقيقية.</p><p>لذلك، ما يريد هذا الفصل حله هو مسألة البداية: <strong>كيف يمكنك الحصول على فكرة؟ وهل هذه الفكرة موثوقة فعلاً؟ وهل تستحق أن تستثمر فيها وقتك وجهدك لتحويلها إلى تطبيق حقيقي؟</strong></p><h2 id="_1-1-ما-هي-الفكرة" tabindex="-1">1.1 ما هي الفكرة <a class="header-anchor" href="#_1-1-ما-هي-الفكرة" aria-label="Permalink to “1.1 ما هي الفكرة”">​</a></h2><p>لنبدأ بسؤال أساسي ولكنه غالبًا ما يُتجاهل: ما الذي يُحسب كفكرة فعلاً؟</p><p>في المحادثات اليومية، ما يسميه الناس غالبًا فكرة هو في الواقع شعور حماس ذاتي للغاية. قد تتصفح مقطع فيديو أثناء تنقلك وتشعر فجأة أن هذا الاتجاه رائع جدًا، فتتبادر إلى ذهنك عبارة: يمكنني أيضًا صنع شيء مشابه. أو أثناء التحدث في تجمع، عندما يشتكي الجميع من صعوبة استخدام منتج معين، تضيف بلا تفكير: لو كان هناك شيء ما يساعدني تلقائيًا على إنجاز كل هذا فحسب. في هذه اللحظة، يكون لديك بالفعل خاطر ضبابي، لكنه لا يزال بعيدًا جدًا عن شيء يمكن بناؤه.</p><p>هنا، سنضع لأنفسنا معيارًا أكثر دقة. فقط عندما تستوفي الفكرة الأشياء التالية على الأقل، سنطلق عليها اسم فكرة:</p><p>أولاً، <strong>يجب أن تستهدف فئة محددة من المستخدمين</strong>. ليس الحديث العام عن &quot;الجميع&quot;، بل أن تكون قادرًا على تحديد من س يستخدم هذا بشكل أساسي. هل هم طلاب الجامعات، أم الموظفون الجدد، أم الآباء الذين يربون أطفالاً، أم المطورون المستقلون، أم تجار التجزئة، أم أصحاب الأعمال الصغيرة. الأشياء التي يهتم بها أشخاص مختلفون في نفس الأمر تختلف تمامًا، وإذا لم تحدد الفئة المستهدفة، فستظل جميع أحكامك اللاحقة معلقة في الهواء.</p><p>ثانيًا، <strong>يجب أن تتجذر في سيناريو محدد</strong>. متى سيستخدم المستخدم هذا التطبيق؟ هل أثناء ركوب مترو الأنفاق في الصباح، أم في فترات الراحة بين العمل، أم قبل النوم، أم أثناء تنظيم المعلومات في عطلة نهاية الأسبوع. حتى الأدوات التي تبدو مجردة، مثل تدوين الملاحظات وإدارة المهام، طالما راقبتها بعناية، ستجد أن الجزء الذي يُستخدم بشكل متكرر مرتبط ارتباطًا وثيقًا بسيناريوهات معينة.</p><p>ثالثًا، <strong>تحتاج إلى مساعدة المستخدم في إنجاز مهمة واضحة</strong>. لا يجب أن تكون المهمة كبيرة، ولكن يجب أن تكون قابلة للوصف. على سبيل المثال، تنظيم قائمة المهام اليومية، أو تلخيص مقال طويل إلى عدة نقاط رئيسية، أو إنشاء محضر اجتماع منظم وواضح، أو إنشاء مسار عملي لنزهة نهاية الأسبوع في مدينة ما. كلما كنت أكثر دقة في وصف المهمة، أصبح من الأسهل عليك تصميم الميزات وتقييم القيمة لاحقًا.</p><p>رابعًا، <strong>تقدم طريقة أو أداة أفضل من الوضع الراهن</strong>. كيف كان المستخدم ينجز هذا الأمر في الأصل؟ هل يعتمد على الذاكرة، أو تدوين الملاحظات الورقية، أو Excel، أو لقطات الشاشة المحفوظة، أم بالتبديل ذهابًا وإيابًا بين التطبيقات المختلفة. إذا كان ما يمكنك تقديمه هو طريقة أوضح وأكثر استقرارًا ومتعة، فإن هذه الفكرة تبدأ فعلاً في اكتساب قيمة حقيقية.</p><p><img src="'+q+'" alt=""></p><p>بالنسبة للتفكير المذكور أعلاه، لا بأس إذا لم تتمكن من توضيحه، فنحن الآن في عصر الذكاء الاصطناعي. يمكنك تنظيم المحتوى أعلاه في موجه (Prompt) كامل، ثم كتابة أفكارك والمستخدمين المستهدفين وسيناريوهات الاستخدام معًا، وتسليمها إلى النموذج اللغوي الكبير لمساعدتك في الإكمال والاستخراج. تعامل مع النموذج كشريك منتج متصل على مدار الساعة، ومن خلال الحوار المتكرر والأسئلة الاستقصائية والتعديل، يمكنك تحويل مفهوم ضبابي إلى شيء محدد.</p><h2 id="_1-2-الأفكار-واحتياجات-المستخدمين-خط-الدفاع-الأول-لتجنب-الانبهار-الذاتي" tabindex="-1">1.2 الأفكار واحتياجات المستخدمين: خط الدفاع الأول لتجنب الانبهار الذاتي <a class="header-anchor" href="#_1-2-الأفكار-واحتياجات-المستخدمين-خط-الدفاع-الأول-لتجنب-الانبهار-الذاتي" aria-label="Permalink to “1.2 الأفكار واحتياجات المستخدمين: خط الدفاع الأول لتجنب الانبهار الذاتي”">​</a></h2><p>أكبر فخ يقع فيه معظم الناس عند صنع تطبيق لأول مرة هو الانبهار الذاتي. ويُقصد بذلك أن تكون متحمسًا للغاية تجاه إبداعك، وتشعر أنه اتجاه سيغير العالم، ولكن عندما تحدث عنه المستخدمين العاديين، تكون ردود فعلهم غالبًا هادئة جدًا، وحتى مرتبكة بعض الشيء، ويقتصرون على الإيماء بأدب وقول &quot;يبدو جيدًا&quot;. ومع ذلك، بعد إطلاق المنتج، لن يقوموا بتنزيله، ناهيك عن استخدامه على المدى الطويل.</p><p>لتجنب هذه الحالة، يجب فصل الأمرين: الأفكار واحتياجات المستخدمين.</p><p>دعنا أولاً نتحدث عن ما هي <strong>احتياجات المستخدمين</strong>. يمكن تلخيصها بجملة بسيطة نسبيًا: في سيناريو محدد، <strong>التكاليف المختلفة التي يرغب المستخدم في تقليلها، أو القيم المختلفة التي يرغب في زيادتها لتحقيق هدف معين.</strong> التكلفة هنا لا تقتصر على المال فحسب، بل تشمل أيضًا الوقت والجهد والعبء الذهني وخطر ارتكاب الأخطاء وحتى الضغط الاجتماعي. على سبيل المثال، قد يكون الموظف الجديد على استعداد لدفع المال لشراء مجموعة قوالب، فقط ليشعر بقليل من الراحة أثناء تقديمه الأول؛ وقد يكون الوالد الذي يربي طفلاً مستعدًا لدفع رسوم إضافية طالما أن ذلك يضمن له نصف ساعة من الوقت الخاص كل يوم.</p><p>بعد فهم هذه النقطة، ستكتشف أن <strong>البريق وحده لا يشكل حاجة.</strong> العديد من الأفكار الإبداعية جديدة بالفعل، ولكن إذا لم تجعل المستخدم يبذل جهدًا أقل، أو يشعر بمزيد من الراحة والثقة تجاه هدف محدد، فسيكون من الصعب جدًا أن تدعم تطبيقًا مستدامًا حقًا.</p><p>هناك هوة غالبًا ما يتم تجاهلها بين الأفكار والاحتياجات. <strong>تمثل الفكرة حكمك الذاتي وليس بيانات مدعومة</strong>، فتشعر بما هو ممتع ومثير ويبدو متقدمًا. بينما يمثل الاحتياجاج ما يمر به المستخدمون فعليًا وما يقلقهم. قد تعتقد أن ميزة إنشاء الشعر تلقائيًا رائعة جدًا، ولكن لمعظم المستخدمين، قد تكون الأداة التي تتيح لهم قضاء عشر دقائق أقل كل يوم في أعمال الترتيب المتكررة أكثر جاذبية. ما لم تكن مثل ستيف جوبز أو تمتلك مستوى ممتازًا من الذوق الجمالي في التصميم، مما يجعل الجميع يشعرون بأن &quot;ميزة إنشاء الشعر تلقائيًا&quot; رائعة جدًا ويرغبون في اتباعك طواعية، وهذا أمر صعب التحقيق.</p><p>عند تقييم فكرة ما، هناك طريقة تمييز بسيطة وهي معرفة ما إذا كانت تبدو أكثر كـ <strong>احتياج حقيقي أم احتياج زائف</strong>. من الخصائص الواضحة للاحتياج الحقيقي أنه حتى بدون تطبيقك في الوقت الحالي، لا يزال المستخدمون يبذلون جهدًا نشطًا لإيجاد طريقة لحل المشكلة. حتى لو كانت الطرق الحالية غير مرنة، فلا يزالون على استعداد لقضاء الوقت والجهد وحتى المال لسد هذه الفجوة. على سبيل المثال، قد يقوم شخص ما بكتابة خططه ونصوصه البرمجية بنفسه، فقط لتخفيف عبء العمل المتكرر عن نفسه قليلاً. في مثل هذه السيناريوهات، إذا كان بإمكانك تقديم حل أكثر ودية وشمولية، فغالبًا ما تكون هناك فرصة للنجاح والاستمرار. الوضع النموذجي للاحتياجات الوهمية هو عكس ذلك تمامًا. إذا لم تكن أنت من يثير الموضوع، فلن يدرك معظم الناس أن تلك مشكلة، بل ولن يشعروا بأنه لابد من حلها. السيناريوهات التي تصفها موجودة في معظمها في خيالك، وليس في الحياة اليومية للمستخدمين. بعد الاستماع إلى عرضك، سيشعرون فقط أن هذا الشيء جيد ومثير للاهتمام، لكنهم لن يدفعوا مقابله، بل قد ينسونه بمجرد أن يديروا ظهورهم. مثل هذه الأفكار، قد تصلح لكتابة قصة، لكنها خطيرة جداً إذا استخدمت لبناء منتج.</p><p><img src="'+d+'" alt=""></p><p>لذلك، <strong>خط الدفاع الأول لتجنب الانبهار الذاتي هو فهم احتياجات المستخدمين.</strong> منذ البداية، تحتاج إلى إجبار نفسك على الإجابة عن سؤال يبدو بسيطاً ولكنه حاسم جداً: بخلافي، من آخر يعاني حقاً من هذه المشكلة. يمكنك مراجعة المنتديات والمجتمعات وأقسام التعليقات، أو يمكنك سؤال بعض الأشخاص من حولك ممن قد يصبحون مستخدمين محتملين. إذا كان من الصعب جداً أن تسمع شكاوى تحمل مشاعر حقيقية مثل &quot;أنا أتعطل دائماً بسبب هذا الأمر&quot; أو &quot;الطريقة الحالية مزعجة حقاً&quot;، فهذا يعني أن هذه الفكرة لا تزال بعيدة عن الاحتياجات الحقيقية.</p><h2 id="_1-3-لماذا-تعتبر-الأفكار-الجيدة-أفكاراً-جيدة" tabindex="-1">1.3 لماذا تعتبر الأفكار الجيدة أفكاراً جيدة <a class="header-anchor" href="#_1-3-لماذا-تعتبر-الأفكار-الجيدة-أفكاراً-جيدة" aria-label="Permalink to “1.3 لماذا تعتبر الأفكار الجيدة أفكاراً جيدة”">​</a></h2><p>ليست جميع الأفكار مصيرها واحداً. بعض الأفكار، حتى لو قضيت عليها بضعة أيام فقط وصنعت نسخة خشنة لكنها قابلة للتشغيل، ستجذب بشكل طبيعي مجموعة صغيرة من المستخدمين الحقيقيين، الذين يرغبون في البقاء ويصبرون على تقديم الملاحظات لك. وهناك أفكار أخرى، حتى لو بذلت قصارى جهدك في تكديس الميزات وأنفقت المال على الإعلانات وقمت بالكثير من الترويج على مختلف المنصات، فلن تتمكن في النهاية إلا من الاعتماد على قوى خارجية لتوليد موجة قصيرة من البيانات، التي سرعان ما تعود إلى الصمت.</p><p>الفرق الجوهري وراء ذلك هو ما إذا كانت الفكرة نفسها قد أصابت نقطة مشكلة رئيسية أم لا.</p><p><strong>الفكرة الجيدة تجذب النمو بشكل طبيعي</strong>: حتى لو ظهرت بشكل بدائي جداً، أو كانت مجرد أزرار بسيطة، طالما أنها تحل مشكلة صغيرة ومحددة يواجهها المستخدم، فإنها ست حقق نمواً طبيعياً بدرجة معينة. على سبيل المثال، أداة صغيرة تساعد الأشخاص على تحويل الصوت إلى نص بسرعة، في البداية قد تكون مجرد صفحة ويب مع بضعة أزرار بسيطة، ولكن طالما أن جودة التعرف جيدة enough ووظيفة التحويل طبيعية جداً، سيكون الكثير من الناس على استعداد لمشاركة الرابط مع أصدقائهم، لأنها ببساطة توفر وقتهم.</p><p><strong>الفكرة السيئة غالباً ما تكون محكوم عليها بالاعتماد على القوى الخارجية منذ البداية</strong>. حتى لو كان مظهرها الخارجي جيداً جداً وبدت نواتها عالية المستوى، فستحتاج إلى الاستمرار في الدفع والصراخ والشرح، ولكن بمجرد أن تتباطأ جهودك لجذب المستخدمين، ستنخفض بيانات الاستخدام بشكل حاد. تستمر في ضخ الموارد وإبرام الشراكات وتنظيم الفعاليات، لكنك ستشعر دائماً أنك تسبح عكس التيار. المشكلة لا تكمن في أن تنفيذك لم يكن جيداً بما فيه الكفاية، بل في أن الفكرة نفسها لم تصب نقطة ألم حقيقية بما فيه الكفاية.</p><p>بالطبع، الحالات المذكورة أعلاه ليست مطلقة، فعلى سبيل المثال في السوق المبكر قد لا يدرك المستخدمون القيمة مما يخلق تأخيراً معيناً، وعلى سبيل المثال في حالة وجود منافسين يجب أن نأخذ في الاعتبار المظهر وصعوبة التشغيل وخصائص العلامة التجارية وما إلى ذلك، ولكن هذه كلها مواضيع أكثر عمقاً ولن نأخذها في الاعتبار حالياً.</p><p>لذلك، عندما نناقش ما إذا كان يجب الاستمرار في الاستثمار في فكرة ما، فإن ما ينبغي التركيز عليه حقاً ليس مدى روعة الفكرة نفسها، بل ما إذا كان يمكنها أن تنمو بشكل طبيعي لتشكل مساراً من المشكلة إلى الحل. نحن نصنع الأفكار ليس لإثبات مدى إبداعنا للآخرين، بل للعثور على نقطة بداية قيمة، ومن خلال هذا المسار يمكننا ببطء صقل أداة صغيرة لتصبح تطبيقاً مفيداً حقاً.</p><p>الاختيار أهم من الجهد.</p><h2 id="_1-4-من-أين-تأتي-الأفكار-الجيدة-أربعة-مصادر-وأمثلة-محددة" tabindex="-1">1.4 من أين تأتي الأفكار الجيدة: أربعة مصادر وأمثلة محددة <a class="header-anchor" href="#_1-4-من-أين-تأتي-الأفكار-الجيدة-أربعة-مصادر-وأمثلة-محددة" aria-label="Permalink to “1.4 من أين تأتي الأفكار الجيدة: أربعة مصادر وأمثلة محددة”">​</a></h2><p>عندما يذكر الكثير من الناس التفكير في أفكار، فإن الصورة التي تتبادر إلى أذهانهم هي شخص منعزل خلف مكتبه، يحدق في السقف، ويأمل أن تسقط الإلهام فجأة عليه يوماً ما. في الواقع، معظم الأفكار الجيدة لا تأتي هكذا. إنها تُستخلص أكثر من الملاحظات الصغيرة في الحياة، والأسئلة المتكررة في المجتمعات، وكومة الشكاوى على الإنترنت، ومن تلك المنتجات الموجودة بالفعل.</p><p>إذا كنت مستعداً للعمل بجدية، فمن السهل جداً العثور على اتجاهات للبدء من خلال هذه المصادر الأربعة التالية.</p><p><img src="'+c+'" alt=""></p><h3 id="أحب-حياتك" tabindex="-1">أحب حياتك <a class="header-anchor" href="#أحب-حياتك" aria-label="Permalink to “أحب حياتك”">​</a></h3><p>مبدأ بسيط جداً ولكنه فعال هو: <strong>كلما زادت مشاركتك في الحياة، زادت سهولة اكتشاف المشكلات، وزادت قدرتك على الحكم على ما يستحق حلها</strong>. المقصود بالمشاركة هو أنك لا تنظر إلى حياة الآخرين من خلال شاشة، بل تختبر وتجرب وتتعثر بنفسك. كلما تعاملت بجدية أكبر مع اهتماماتك، زادت احتمالية أن تصبح تربة خصبة لنمو الأفكار.</p><p>على سبيل المثال، إذا كنت تحب تربية القطط كثيراً، فإن يومك العيش مع قطة غالباً ما يحتوي على معلومات أكثر من تصفح مئة نصيحة لتربية القطط. ستعرف الأماكن التي تسقط فيها القطط الأشياء بسهولة، وستتذكر الوقت الذي تحب فيه القفز أكثر، والظروف التي تكون فيها عرضة للتوتر، وستختبر بنفسك تفاصيل مثل تنظيف صندوق الفضلات وتمشيط الفراء وقص الأظافر وزيارة الطبيب البيطري. <strong>كل تجربة غير سلسة قليلاً هي في الواقع مؤشر محتمل لمنتج</strong>.</p><p>خذ على سبيل المثال تصويرك لقطتك: الكثير من الناس واجهوا هذا الموقف، حيث تقف هناك حاملاً هاتفك، لكن القطة ترفض النظر إلى الكاميرا، إما أن تنظر إلى أسطواناتها أو تحدق في زاوية أخرى. فهل يمكن أن تكون هناك أداة صغيرة تجعل شاشة الهاتف أو الجهاز اللوحي تعرض رسماً متحركاً لنقطة حمراء تتحرك تلقائياً أو ريشة أو حشرة صغيرة، لجذب انتباه القطة تحديداً؟ عندما تضغط على زر التصوير، تتحرك تلقائياً بالقرب من الكاميرا الأمامية، لـ &quot;خداع&quot; نظر القطة باتجاه العدسة، والتقاط عدة صور متتالية، ومساعدتك في اختيار الصورة الواضحة والجميلة من بينها. والتفكير خطوة إلى الأمام، يمكن لهذا التطبيق أيضاً تسجيل أي لون وأي مسار حركي يثير اهتمام كل قطة، واستخدام &quot;وضع اللعب&quot; &quot;المخصص&quot; لها تلقائياً في المرة القادمة لزيادة نسبة النجاح.</p><p><img src="'+b+'" alt=""></p><p>إذا كنت تستمتع بعملية المكياج أو العناية بالبشرة، فإن كل منتج خلف تلك الزجاجات في خزانتك هو نتيجة الكثير من التجارب والخطأ واتخاذ القرارات. ربما تكون معتاداً على التقاط صور لمكياجك في كل مرة باستخدام معرض الصور بهاتفك، ولكن في كل مرة تراجع فيها، عليك أن تتذكر ببطء أي أحمر شفاه وأي لوحة ظلال عيون استخدمتها في ذلك اليوم. فهل يمكن تسجيل هذه المعلومات بشكل منهجي وصنع دليل مكياج خاص بك؟ يمكن حتى أن يساعدك التطبيق في الإحصاء، أي مكياج تستخدمه أكثر في أي مناسبة، وأي تركيبات تظهر بشكل أفضل في الصور، بحيث لا تضطر إلى البدء من الصفر في كل مرة تختار فيها مكياجك.</p><p>لنكن أكثر تحديداً، فالكثير من الناس لديهم هذا السيناريو: في الصباح عندما يكون الوقت ضيقاً، تفتح معرض الصور للبحث عن &quot;مكياج التنقل الناجح في المرة الماضية&quot;، وبعد البحث طويلاً لا تتذكر ما هي المنتجات التي استخدمتها بالضبط. فهل يمكن أن تكون هناك ميزة صغيرة تتيح لك بعد التقاط صورة المكياج، أن تقول للهاتف ببساطة: &quot;مكياج مقابلة اليوم، استخدمت لوحة ظلال العيون البرتقالية البنية رقم 01 وأحمر شفاه بلون البازلاء&quot;، فيقوم التطبيق بالتعرف تلقائياً وإنشاء &quot;وصفة مكياج&quot; مرتبطة بالصورة؟ في المرة القادمة، ما عليك سوى البحث عن &quot;مقابلة&quot; أو &quot;ظلال عيون برتقالية بنية&quot; أو &quot;لون البازلاء&quot; لرؤية جميع المكياجات ذات الصلة بنقرة واحدة، ويمكنه حتى إنشاء قائمة توصيات تلقائية مثل &quot;عرض مكياج مناسب للتنقل فقط والذي يمكن إتمامه في خمس دقائق اليوم&quot;. تلك الدقائق التي توفرها كل صباح هي في الواقع &quot;مشكلة تم حلها&quot; محددة جداً.</p><p>إذا كنت تحب city walk أو أشكال السفر البطيء المختلفة، فربما تكون قد استخدمت أدوات متنوعة لتجميع تجربتك: تطبيقات الخرائط لتسجيل المسارات، و تطبيق الملاحظات لقائمة المقاهي التي تريد زيارتها، وصور وانطباعات متناثرة في معرض الصور. فهل يمكن أن يكون هناك تطبيق يجمع المسار ونقاط التسجيل والصور والنصوص معاً في سجل مشي يحتوي على خط زمني وقصة؟ ويمكن الذهاب أبعد من ذلك لمشاركة مسارك مع الأصدقاء بنقرة واحدة، لكي يتمكنوا أيضاً من المشي في نفس المدينة بنسخة مختلفة.</p><p>يمكن أيضاً الحفر لأسفل للوصول إلى تفصيل يومي أكثر: الكثير من الناس أثناء city walk يشعرون بالإحباط من أن &quot;هذا الزاوية تبدو جميلة جداً في اللحظة، ولكن بعد العودة إلى المنزل لا يمكنني العثور على تلك النقطة على الخريطة على الإطلاق&quot;. فهل يمكن عمل ميزة فائقة الخفة: عندما تصل إلى تقاطع تشعر بأنه مميز، ما عليك سوى الضغط على زر سماعة الرأس وقول &quot;ضع علامة، هذا مكان مناسب للمشي في موعد غرامي&quot;، فيقوم التطبيق فوراً بوضع علامة صوتية في موقعك الحالي، وتسجيل الوقت والطقس ومستوى الضوضاء تلقائياً. لاحقاً أنت أو أصدقاؤك، ما عليك سوى فتح خريطة هذه المدينة لرؤية &quot;نقاط الأجواء المختبرة فعلياً من المارة&quot;: أين يناسب المشي بمفردك في شرود، أين يناسب مشاهدة المناظر الليلية، أين يناسب المشي والتحدث مع الأصدقاء. تلك الزوايا الصغيرة التي كنت &quot;تمر بها وتنساها&quot; هكذا، تنمو ببطء لتصبح قاعدة بيانات لتجربة المدينة ذات جودة عالية.</p><p>كل هذه الأمثلة تريد في الحقيقة توضيح شيء واحد فقط: <strong>تحتاج إلى أن تحب حياتك، فحياتك هي أفضل مصدر لأفكارك</strong>. الحيرة التي تواجهها كل يوم، والحلول البديلة التي تفكر فيها مؤقتاً، وتلك الأشياء التي تجدها مزعجة قليلاً ولكنك تعودت على تحملها، طالما أنك على استعداد لإلقاء نظرة إضافية وسؤال نفسك عما إذا كان من الممكن استخدام أداة صغيرة لتغييرها، فكلها يمكن أن تصبح نماذج أولية لمنتجات مستقبلية.</p><h3 id="الاستخراج-من-أصول-الجمهور-التي-تمتلكها" tabindex="-1">الاستخراج من أصول الجمهور التي تمتلكها <a class="header-anchor" href="#الاستخراج-من-أصول-الجمهور-التي-تمتلكها" aria-label="Permalink to “الاستخراج من أصول الجمهور التي تمتلكها”">​</a></h3><p>ما يسمى بأصول الجمهور، باختصار، هو مجموعة من الأشخاص يمكنك الوصول إليهم بالفعل. قد يكونون قراءك، أو المجتمع الذي تديره، أو مجموعة زملائك الداخليين في الشركة، أو حتى مجتمعاً للاهتمامات تشارك فيه لفترة طويلة. طالما لديك قناة، <strong>يمكنك سماع ما يتحدث عنه جزء من الناس يومياً وما يزعجهم وما يتوقعونه بشكل مستقر</strong>، فأنت تتمتع بميزة كبيرة مقارنة بشخص يبدأ من الصفر تماماً.</p><p>في هذه السيناريوهات، لا يجب عليك محاولة بناء منتج ضخم وشامل يستهدف الجميع منذ البداية. كل ما عليك هو الإقرار بنقطة واحدة: هذه الدائرة الصغيرة من الأشخاص الذين بين يديك هي أفضل نقطة انطلاق لك. كلما كان فهمك لهم أعمق، وكلما عرفت أكثر تلك المزعجات الصغيرة في حياتهم الحقيقية التي يمكن التعبير عنها وتلك التي لا يمكن التحدث عنها، زادت فرصتك في صنع شيء سيُستخدم فعلياً.</p><h3 id="استكشاف-الاحتياجات-من-المساحات-العامة" tabindex="-1">استكشاف الاحتياجات من المساحات العامة <a class="header-anchor" href="#استكشاف-الاحتياجات-من-المساحات-العامة" aria-label="Permalink to “استكشاف الاحتياجات من المساحات العامة”">​</a></h3><p>حتى لو لم يكن لديك حالياً أي مجتمع خاص بك أو مجموعة قراء، فلا داعي للقلق على الإطلاق. هناك أشخاص لا حصر لهم على الإنترنت يصرخون يومياً في منصات مختلفة يشرحون صعوباتهم واستياءهم. هذه الأصوات في المساحات العامة هي بحد ذاتها كنز كبير، إلا أن معظم الناس لم يستمعوا إليها بجدية أبداً.</p><p>يمكنك تحديد عدد من المنصات المتعلقة بالصناعة التي تهتم بها، والبحث بشكل دوري عن بعض الكلمات المفتاحية التي تحمل طابعاً عاطفياً. على سبيل المثال، <strong>مزعج جداً، هل من توصيات، كيف أحل هذه المشكلة، هذا أمر معقد حقاً، هل توجد طريقة أفضل.</strong> ثم تصفح هذه المنشورات والتعليقات بصبر، مع التركيز على نوعين من المعلومات.</p><p>النوع الأول هو مشكلة معينة يتم ذكرها بشكل متكرر وعلى المدى الطويل. على سبيل المثال، في قسم البحث عن عمل، بين الحين والآخر يأتي شخص يسأل عن كيفية كتابة السيرة الذاتية، وكيفية التحضير للمقابلة الشخصية، وكيفية متابعة نتائج المقابلة؛ وفي مجموعات الأمهات، تظهر دائماً بشكل متكرر حيرتهن بشأن تناسب الأطعمة التكميلية، وتعديل روتين النوم، والتواصل مع الأطفال؛ وفي مجتمعات التبادل التجاري للبائعين الصغار، قد يكون الجميع دائماً قلقين بشأن إدارة المخزون، والتدفق النقدي، وجداول عمل الموظفين. هذه المشاكل المتكررة طويلة الأمد هي نقاط ألم منهجية تكشف عنها الصناعة مراراً وتكراراً.</p><p>النوع الثاني هو في سيناريوهات معينة، حيث يكافح المستخدمون ويتحملون الأمر بطرق خرقاء للغاية. على سبيل المثال، هناك من يكتب جميع المهام التي يجب إنجازها على الورق، ثم يلتقط صورة لها ويرفعها إلى السحابة؛ وهناك من ينسخ ويلصق ذهاباً وإياباً بين تطبيقات مختلفة، فقط لتحويل جزء من المحتوى من تنسيق إلى آخر؛ وهناك من يقوم يدوياً بتجميع البيانات من قنوات مختلفة في جدول واحد. في هذه الأماكن، طالما راقبت بعناية، ستجد العديد من نقاط الدخول الصغيرة التي يمكن تحويلها إلى عمليات وأدوات.</p><p>إن البحث عن الاحتياجات في المساحات العامة هو في الواقع تدريب على قدرة: تحويل نفسك من متفرج إلى صياد. عندما تعتاد على البحث عن هذه الكلمات المفتاحية، وتعتاد على تدوين الحالات، سيتراكم عقلك ببطء بمستوى من الحساسية تجاه المشاكل الواقعية، وهذه الحساسية ستساعدك مراراً وتكراراً خلال عملية تصميم المنتج لاحقاً.</p><h3 id="الوقوف-على-أكتاف-العمالقة" tabindex="-1">الوقوف على أكتاف العمالقة <a class="header-anchor" href="#الوقوف-على-أكتاف-العمالقة" aria-label="Permalink to “الوقوف على أكتاف العمالقة”">​</a></h3><p>هناك مصدر آخر للأفكار يتم تجاهله غالباً، وهو المنتجات والمشاريع الحالية. يوجد في هذا العالم بالفعل الكثير من الأشخاص الرائعين الذين سلكوا من أجلنا العديد من مسارات الاستكشاف. لست بحاجة إلى البدء من صفحة بيضاء في كل مرة، يمكنك تماماً أن تقف حيث وصل الآخرون إلى منتصف الطريق، وتتخذ خطوة صغيرة إلى الأمام. في مناسبات مثل <strong>هاكاثون، ومسابقات ابتكار المنتجات، وأيام العرض التوضيحي (Demo Day) للشركات الناشئة</strong>، غالبًا ما تظهر الكثير من الأعمال الصغيرة المثيرة للاهتمام. معظمها يتسم بخاصيتين: الوقت ضيق، والموارد محدودة. وهذا يشبه إلى حد كبير التطبيق الصغير الذي ترغب في صناعته الآن. لذلك، عندما تنظر إلى هذه الأعمال الفائزة، لا بأس من أن تطرح على نفسك سؤالين إضافيين: إذا كان هذا الشيء يخدم فئة أكثر تحديدًا وضيقًا، فهل سيكون من الأسهل تطبيقه على أرض الواقع؟ إذا تم الاستغناء عن نصف وظائفه أو حتى ثلثيها، والاحتفاظ فقط بالحلقة الأكثر جوهرية، فهل سيكون أكثر وضوحًا؟</p><p>وبالمثل، فإن الأدوات المدرجة في <strong>قوائم المنتجات، والمشاريع مفتوحة المصدر، ومواقع تجميع الأدوات</strong> يمكن أن تكون جميعها نقطة انطلاق لتفكيرك. يمكنك اختيار بعضها الذي يثير اهتمامك وتفكيكها واحدًا تلو الآخر: من الذي تساعده هذه الأداة، وما المشكلة التي تحلها؟ ما هي الفجوات الواضحة في شكلها الحالي؟ إذا تم نقلها إلى سيناريو مختلف أو دولة أخرى، فما الاختلافات التي ستظهر؟ أنت لا تحاول الانتحال، بل من خلال هذا التمرين في التفكيك، أنت تدرب نفسك على فهم العلاقة بين المشاكل والحلول.</p><p>العالم الواقعي لا يختلف عن ذلك. في كل مرة تقف فيها في طابور لتسجيل الدخول في المستشفى، أو تنتظر دورك في مطعم، أو تملأ نفس المعلومات عدة مرات في قاعة الخدمات الحكومية، أو تكتب نفس المحتوى مرارًا وتكرارًا على نموذج ورقي، يمكنك أن تتوقف عمدًا وتسأل نفسك: هل هناك مساحة هنا لما يمكن أن يكون <strong>منهجًا، أو رقميًا، أو آليًا</strong>؟ تلك السيناريوهات التي تبدو فوضوية، ومتكررة، وغير فعالة، هي في جوهرها التربة التي ستنمو فيها بعض الأدوات مستقبلاً.</p><p>من خلال الاستمرار لفترة طويلة في حفر الأفكار من هذه المسارات الأربعة، ستكتشف أن الفكرة ليست معجزة تظهر فجأة في ذهنك، بل هي منتج ثانوي ينمو بشكل طبيعي نتيجة تفاعلك الطويل مع الحياة، ومع الآخرين، ومع عالم المعلومات.</p><h2 id="_1-5-كيف-تلخص-فكرة-جيدة-في-جملة-واحدة-فن-الأقل-هو-الأكثر" tabindex="-1">1.5 كيف تلخص فكرة جيدة في جملة واحدة: فن &quot;الأقل هو الأكثر&quot; <a class="header-anchor" href="#_1-5-كيف-تلخص-فكرة-جيدة-في-جملة-واحدة-فن-الأقل-هو-الأكثر" aria-label="Permalink to “1.5 كيف تلخص فكرة جيدة في جملة واحدة: فن &quot;الأقل هو الأكثر&quot;”">​</a></h2><p>عندما تعرف تقريبًا من أين تأتي الفكرة، يصبح التمرين المهم التالي <strong>هو محاولة شرحها في جملة واحدة.</strong> يبدو هذا التمرين بسيطًا، ولكنه في الواقع قاسٍ إلى حد ما، لأنه سيجبرك على مواجهة حقيقة واحدة: <strong>هل أمسكت فكرتك حقًا بجوهر واضح ومحدد؟</strong></p><p>نادرًا ما يتذكر الإنسان شخصًا آخر لأنه كان متوازنًا ومثاليًا في كل شيء، وفي أغلب الأحيان، يكون التذكر بسبب ميزة واضحة. ربما يرتدي دائمًا نوعًا معينًا من القبعات، أو أن أسلوبه في الحديث مستقر للغاية، أو أنه قادر دائمًا على طرح الجملة الرئيسية في كل مناقشة. المنتجات هي نفسها. <strong>بدلاً من جعل الآخرين يتذكرون بصعوبة عشرات الميزات لديك، من الأفضل أن تترك لديهم انطباعًا بسيطًا ولكن واضحًا.</strong></p><p>عند كتابة هذه الجملة، هناك مغالطة شائعة وهي الإفراط في التعميم. على سبيل المثال: &quot;هذا تطبيق يساعد المستخدمين على تحسين مستوى اللغة الإنجليزية لديهم&quot;. للوهلة الأولى، لا يبدو هناك خطأ، ولكن إذا تساءلت بشكل أعمق، ستكتشف أن هذه الجملة لا تقول شيئًا تقريبًا: تُساعد مَن؟ هل هم طلاب بدون أي أساسيات، أم أشخاص يعملون بالفعل في مجالهم؟ وبأي طريقة؟ هل هي لحفظ الكلمات، أو تدريب الاستماع، أو تصحيح النطق، أو تصحيح الكتابة؟ كم من الوقت يحتاجون للاستثمار، وما حجم التغيير الذي يمكن أن يجلبوه؟ كل المعلومات الأساسية قد تم تخفيفها وتمييعها.</p><p>ستكون الصياغة الأفضل بكثير أكثر تحديدًا. على سبيل المثال: &quot;تطبيق لحفظ الكلمات يساعدك على تذكر 100 كلمة أساسية في شهر واحد باستخدام 10 دقائق من وقت التنقل يوميًا&quot;. هنا، يتم توضيح ثلاثة أشياء على الأقل: تكلفة الاستخدام قابلة للتحكم، فهي تحتاج فقط إلى 10 دقائق يوميًا؛ النتيجة المتوقعة مرئية، فهناك 100 كلمة جديدة في الشهر؛ السيناريو واضح، ويحدث بشكل أساسي أثناء التنقل بدلاً من أوقات الفراغ الأخرى. عندما يسمع المستخدمون مثل هذا الوصف، يمكنهم بسرعة الحكم في أذهانهم على ما إذا كان هذا الشيء مفيدًا لهم أم لا.</p><p>إن عملية التدرب على كتابة هذه الجملة هي في الواقع إجبار متكرر لنفسك على الإجابة على ثلاثة أسئلة: <strong>من الذي تساعده بالضبط، في أي سيناريو تتمنى أن يتذكروك، وكم من الوقت تخطط لقضيه لمساعدتهم في تحقيق أي نتيجة.</strong> فقط عندما تكون مستعدًا لجمع هذه المعلومات معًا، حتى لو تطلب الأمر التضحية ببعض الكلمات الرنانة، ستصبح فكرتك حقًا قابلة للفهم والنشر.</p><p>يمكنك أيضًا تطبيق هذا التدريب على نفسك بشكل عكسي. حاول أن تكتب وصفًا من جملة واحدة لمستقبلك في السنوات الثلاث القادمة. على سبيل المثال، &quot;آمل أنه بعد ثلاث سنوات، يمكنني استخدام جملة أو جملتين لشرح الفئة الرئيسية من الأشخاص الذين أساعدهم، ونوع المشاكل التي أحلها لهم، والنتائج الملموسة التي حققتها بالفعل.&quot; سيجعلك هذا التدريب أكثر وضوحًا عند اتخاذ القرارات، حيث ستعرف الأشياء التي يجب عليك التمسك بها بشدة، والأشياء التي يمكنك التخلي عنها بشكل مناسب. فتعلم التخلي أصعب من تعلم الإضافة، ولكنه الخيار الصحيح.</p><p>إذا كنت لا تعرف من أين تتعلم هذا النوع من التعبير، فالأمر بسيط، فقط انظر إلى المحتوى الذي يتم صقل نصوصه يوميًا للتنافس على انتباه المستخدمين. يمكنك الرجوع إلى **المقدمة المكونة من جملة واحدة في متاجر التطبيقات، والعناوين الرئيسية المعروضة على الصفحات الرئيسية لمواقع الألعاب والمنتجات الأدوات، والنصوص الأساسية على صفحات **<strong>Landing Page** ** المختلفة.</strong> يمكنك نسخها، وتفكيكها إلى هياكل، ومحاولة استخدام الذكاء الاصطناعي (AI) لكتابة نسخة جديدة من النصوص الإعلانية لفكرتك.</p><h2 id="_1-6-استخدام-الذكاء-الاصطناعي-ai-لتوسيع-التفكير-وإيجاد-التمايز" tabindex="-1">1.6 استخدام الذكاء الاصطناعي (AI) لتوسيع التفكير وإيجاد التمايز <a class="header-anchor" href="#_1-6-استخدام-الذكاء-الاصطناعي-ai-لتوسيع-التفكير-وإيجاد-التمايز" aria-label="Permalink to “1.6 استخدام الذكاء الاصطناعي (AI) لتوسيع التفكير وإيجاد التمايز”">​</a></h2><p>في الماضي، عند التفكير في الأفكار، كان المرء يعتمد في معظم الأحيان على نفسه للتفكير ببطء. الآن مع وجود الذكاء الاصطناعي (AI)، أصبح لديك شريك في العصف الذهني يمكنك استدعاؤه في أي وقت. طالما تم استخدامه بشكل جيد، فيمكنه أن يوسع مساحة تفكيرك بشكل كبير.</p><p>عندما تشعر بالتعثر في اتجاه معين، وتجد أن الأفكار في رأسك تدور حول نفس النقاط القليلة، لا بأس من أن تصف فكرتك الحالية للذكاء الاصطناعي (AI) بأوضح طريقة ممكنة، ثم تطلب منه مساعدتك في القيام ببعض الأشياء. على سبيل المثال، <strong>بناءً على نفس المهمة الأساسية، اطلب منه سرد عشرين مجموعة مستخدمين مختلفة</strong>، أو اطلب منه إعادة وصف الطرق المحتملة لاستخدام هذه الفكرة من زوايا مختلفة مثل الطلاب، والعاملين المستقلين، والآباء الذين يربون أطفالًا، وأصحاب المتاجر الصغيرة. أو، اطلب منه اتخاذ أدوار مدير المنتج، والعمليات، والتسويق، والتقنية، لطرح النقاط التي تهم كل دور على حدة.</p><p>ستكتشف أن العديد من سيناريوهات الاستخدام التي لم تكن لتفكر فيها بنفسك سيتم طرحها عليك في هذه الخطوة. مهمتك ليست قبول هذه الاقتراحات ببساطة، بل في هذه المساحة الموسعة، <strong>اختيار القطعة الصغيرة التي تتمتع فيها بأكبر قدر من الفهم والميزة التنافسية في الموارد</strong>. على سبيل المثال، إذا اكتشفت أنه على الرغم من أن الذكاء الاصطناعي (AI) قد سرد العديد من الصناعات، إلا أنك تشعر بتعاطف خاص مع سيناريوهات التعليم وإنشاء المحتوى، فيمكنك عندئذ إعطاء الأولوية لمواصلة التفكيك في هذين الاتجاهين. في هذه العملية، هناك مبدأ مهم آخر وهو: <strong>الأفكار الشائعة لا تعني بالضرورة أفكارًا غير صالحة</strong>. رد الفعل الأول للعديد من المبتدئين هو تجنب جميع الاتجاهات التي تبدو شائعة، معتقدين أنه لا توجد فرصة في أي شيء فعله الآخرون بالفعل. لكن العالم الحقيقي ليس بهذه البساطة أبدًا. الاتجاهات التي تبدو شائعة مثل حفظ المفردات، وقوائم المهام، وتتبع النفقات، وتسجيل العادات، لا يتوقف الناس عن العمل عليها باستمرار لأن المشكلة الكامنة وراءها موجودة بالفعل على نطاق واسع. في هذه الحالة، لا يكون التنافس عادةً حول من يمتلك فكرة كبيرة جديدة كليًا، بل حول <strong>من يفهم مجموعة صغيرة معينة بشكل أفضل، ومن يمكنه جعل التفاصيل أقرب إلى حياتهم</strong>.</p><p>يمكنك أولاً سرد مجموعة من الأفكار التي يسهل على المبتدئين التفكير فيها، مثل أدوات حفظ المفردات، وتطبيقات تسجيل الدخول اليومية، ومساعدات تدوين الملاحظات القرائية، ومولدات السير الذاتية، وأدوات بناء العادات، إلخ. ثم بالنسبة لكل فكرة، قم بإجراء جولة من التفكيك خصيصًا مع الذكاء الاصطناعي، مع التركيز على طرح ثلاثة أسئلة: إذا كنت أخدم فقط مجموعة محددة جدًا من الأشخاص، مثل المصممين، أو المحامين، أو الأمهات الجدد، أو طلاب الدراسات العليا، كيف ستبدو هذه الفكرة بشكل مختلف. إذا كنت أستهدف فقط سيناريو ثابتًا، مثل وقت التنقل، أو استراحة الغداء لعشر دقائق، أو نصف ساعة قبل النوم، فهل يمكن جعل الوظائف والعرض أكثر تركيزًا. <strong>إذا قمت بتطوير عرض النتائج إلى أقصى الحدود، مثل جعلها أسهل للمشاركة، أو أسهل للطباعة، أو أسهل للاستيراد إلى أنظمة أخرى، فهل سيكون ذلك كافيًا لتشكيل اختلاف</strong>.</p><p>قيمة الذكاء الاصطناعي هنا لا تكمن في اتخاذ القرار نيابة عنك، بل في مساعدتك على تحويل طريق ضيق في الأصل إلى خريطة أكثر اكتمالًا. سترى بسرعة أكبر المناطق التي قام الآخرون بتعميقها بالفعل، والزوايا التي لا تزال فارغة نسبيًا. أما بالنسبة للمسار الذي ستسلكه حقًا، فسيعود الأمر في النهاية دائمًا إلى سؤال قديم: ما هي الأماكن التي تهتم بها حقًا، وتفهمها بعمق كافٍ، ومستعد للاستثمار فيها على المدى الطويل.</p><p>في نهاية كل هذا، دعنا نبرز تلك القاعدة السفلية مرة أخرى. أي نقاش حول الأفكار والإبداع يجب أن يعود في النهاية إلى احتياجات المستخدمين. يمكنك استخدام الذكاء الاصطناعي للمساعدة في التفكير، ويمكنك الاستفادة منه لتسريع توليد المتغيرات، ولكن بغض النظر عن عدد جولات العصف الذهني التي قمت بها، فإن معيار الحكم النهائي يبقى دائمًا هو: هل هذه الفكرة تستجيب حقًا لنقطة ألم حقيقية لمجموعة معينة من الأشخاص؟ وهل خطت خطوة صغيرة إلى الأمام في مشكلة كانوا يحاولون حلها مرارًا وتكرارًا؟</p><h2 id="الخلاصة" tabindex="-1">الخلاصة <a class="header-anchor" href="#الخلاصة" aria-label="Permalink to “الخلاصة”">​</a></h2><p>يجب أن تتعلم كيف تستخدم بضعة أبعاد بسيطة لفحص ما إذا كانت الفكرة واضحة بما فيه الكفاية؛ يجب أن تميز بين ما تراه أنت رائعًا وبين ما يحتاجه المستخدم حقًا؛ يجب أن تعرف أن الأفكار الجيدة هي جيدة لأنها تدوس على نقطة ألم معينة منذ البداية؛ يجب أن تتعلم كيف تستمر في استخراج القرائن من حياتك الشخصية، وأصول الأشخاص من حولك، والمعلومات العامة، والمنتجات الموجودة؛ يجب أن تتدرب على شرح الفكرة في جملة واحدة؛ وأن تتعلم أيضًا كيف تتخذ من الذكاء الاصطناعي شريكًا لتوسيع أفكارك، وليس أداة تحل محل حكمك.</p><p>عندما يكون لديك بالفعل من فكرة إلى ثلاث أفكار من هذا النوع، و <strong>يمكنك شرح</strong> كل منها في جملة واحدة لمن هي، وفي أي سيناريو تُستخدم، وما هي النتيجة التقريبية التي ستجلبها، يمكنك عندئذٍ كبح اندفاعك نحو الاستمرار في التفكير في أفكار جديدة، وتحويل انتباهك إلى الخطوة التالية: كيف تفكك إحداها إلى تطبيق يمكن بناؤه فعليًا ويمكن للمستخدمين الحقيقيين استخدامه. ماذا لو كانت هذه الفكرة سيئة بعض الشيء؟ لا بأس بذلك، كونها سيئة في البداية هو الشيء الصحيح، <strong>الإنجاز أهم دائمًا من الكمال</strong> ، تحتاج إلى البدء أولاً حتى يكون هناك نهاية.</p><h2 id="📚-الواجبات" tabindex="-1">📚 الواجبات <a class="header-anchor" href="#📚-الواجبات" aria-label="Permalink to “📚 الواجبات”">​</a></h2><p>يرجى إكمال الواجبات التالية بناءً على المحتوى أعلاه:</p><ol><li>بالجمع بين اهتماماتك الشخصية، استخدم الذكاء الاصطناعي لمساعدتك في توليد بعض &quot;الأفكار&quot; للتطبيقات</li><li>اطلب من الذكاء الاصطناعي تقييم ما إذا كان هذا الطلب حقيقيًا أم زائفًا بناءً على أفكارك، واطلب منه تقديم رؤى حول احتياجات المستخدمين واقتراحات</li><li>اختر مصدرًا أو اثنين من المصادر الأربعة الرئيسية للحصول على &quot;أفكار&quot;، أو دع الذكاء الاصطناعي يولد بعض &quot;الأفكار&quot; للتطبيقات</li><li>من بين جميع الأفكار المذكورة أعلاه، اختر ثلاث أفكار مفضلة، وحاول تلخيص كل فكرة في جملة واحدة غنية بالمعلومات.</li></ol><h1 id="_2-بمجرد-أن-تمتلك-الفكرة،-كيف-تفككها-إلى-تطبيق-قابل-للتنفيذ" tabindex="-1">2. بمجرد أن تمتلك الفكرة، كيف تفككها إلى تطبيق قابل للتنفيذ <a class="header-anchor" href="#_2-بمجرد-أن-تمتلك-الفكرة،-كيف-تفككها-إلى-تطبيق-قابل-للتنفيذ" aria-label="Permalink to “2. بمجرد أن تمتلك الفكرة، كيف تفككها إلى تطبيق قابل للتنفيذ”">​</a></h1><p>في الفصل السابق حللنا مشكلة البداية: ما هي الأفكار التي تستحق أن تؤخذ على محمل الجد حقًا.</p><p>التحدي الحقيقي يبدأ من هنا فقط، والكثير من الناس يسقطون في هذه الخطوة: لديهم مخطط كامل في أذهانهم، ولكن بمجرد أن يبدأوا في التنفيذ يشعرون بتعقيد الأمور لدرجة لا يعرفون من أين يبدأون. الميزات كثيرة، والصفحات كثيرة، والتقنية تبدو مخيفة، فيؤجلون باستمرار، لتتحول في النهاية إلى <strong>وهم المواساة الذاتية</strong> :</p><p>&quot; <strong>لا بأس، يمكننا القيام بهذا الشيء في المستقبل عندما تتاح الفرصة...</strong> &quot;</p><p><img src="'+m+'" alt=""></p><p>توقف عن التفكير! إما الآن أو لا! ما نريد القيام به في هذا الفصل هو مساعدتك على تعلم طريقة تفكيك من الفكرة إلى إصدار قابل للتنفيذ. ستلاحظ أن الانتقال من الصفر لا يعتمد على العبقرية، بل يعتمد على سلسلة من الإجراءات المحددة التي يمكن التدرب عليها مرارًا وتكرارًا: ** التوسع،** <strong>التحديد</strong> <strong>، التفكيك، التدقيق، الاستلهام، والأسئلة.</strong> باتباع هذا الترتيب، حتى لو لم يكن لديك فريق أو الكثير من الوقت، يمكنك تحويل فكرة إلى عرض تطبيق (Demo) يعمل بنجاح.</p><h2 id="_2-1-من-الفكرة-إلى-الحل-التوسع-والتحديد-بنموذج-الماس-المزدوج" tabindex="-1">2.1 من الفكرة إلى الحل: التوسع والتحديد بنموذج الماس المزدوج <a class="header-anchor" href="#_2-1-من-الفكرة-إلى-الحل-التوسع-والتحديد-بنموذج-الماس-المزدوج" aria-label="Permalink to “2.1 من الفكرة إلى الحل: التوسع والتحديد بنموذج الماس المزدوج”">​</a></h2><p>عندما تتعلم كيف ترسم صفحات وتطرح أفكارًا، ستواجه قريبًا مشكلة شائعة أخرى: تبدأ الأفكار في التزايد. تكتب سيناريوهات ووظائف محتملة مختلفة على السبورة، وتمتلئ الورقة بإصدارات صفحات مختلفة، ويبدو الأمر وكأنه إنجاز كبير، ولكن عندما يحين وقت التنفيذ الفعلي، يصبح من الصعب البدء أكثر. لأن كل شيء يبدو مهمًا، ويبدو وكأنه يستحق التجربة.</p><p>في هذا الوقت، ستحتاج إلى استخدام إطار تفكير كلاسيكي للغاية ولكنه سهل الفهم: نموذج الماس المزدوج. المعنى الحقيقي لهذا النموذج بسيط جدًا، وهو أنه في العديد من مراحل الحياة، تحتاج إلى التوسع أولاً، ثم التحديد، بدلاً من محاولة إنجاز كل شيء دفعة واحدة منذ البداية.</p><h3 id="ما-هو-نموذج-الماس-المزدوج" tabindex="-1">ما هو نموذج الماس المزدوج <a class="header-anchor" href="#ما-هو-نموذج-الماس-المزدوج" aria-label="Permalink to “ما هو نموذج الماس المزدوج”">​</a></h3><p>نموذج الماس المزدوج هو إطار عمل لعملية الابتكار والتصميم اقترحه مجلس التصميم البريطاني، ويشبه العملية بأكملها بماسين متتاليين (&quot;الماس المزدوج&quot;): الماس الأول يمتد من &quot;اكتشاف المشكلة&quot; إلى &quot;تحديد المشكلة بوضوح&quot;، ويؤكد على التوسع الواسع أولاً، وإجراء البحث وفهم المستخدمين بالكامل، ثم التحديد لاستخراج المشكلة الجوهرية التي يجب حلها حقًا؛ الماس الثاني يمتد من &quot;تطوير الحلول&quot; إلى &quot;تسليم الحل النهائي&quot;، من خلال التوسع بشجاعة في أفكار الحلول الممكنة، واستكشاف النماذج الأولية وتكرارها، ثم التحديد، والفرز، وصقل الحل الأمثل القابل للتنفيذ. يؤكد نموذج الماس المزدوج على ضرورة المرور بعملية &quot;التوسع - التحديد&quot; في كل من مرحلتي المشكلة والحل، لتجنب القفز مباشرة إلى الحلول منذ البداية، مما يرفع من جودة الابتكار ومعدلات النجاح.</p><p><img src="'+_+'" alt=""></p><p><img src="'+f+'" alt=""></p><h3 id="الماس-الأول-فهم-المشكلة،-التوسع-والتحديد-من-نقطة-واحدة-إلى-الصورة-الشاملة" tabindex="-1">الماس الأول: فهم المشكلة، التوسع والتحديد من نقطة واحدة إلى الصورة الشاملة <a class="header-anchor" href="#الماس-الأول-فهم-المشكلة،-التوسع-والتحديد-من-نقطة-واحدة-إلى-الصورة-الشاملة" aria-label="Permalink to “الماس الأول: فهم المشكلة، التوسع والتحديد من نقطة واحدة إلى الصورة الشاملة”">​</a></h3><p><strong>في نموذج الماس المزدوج، الماس الأول يدور حول المشكلة نفسها</strong> . أنت تبدأ من إدراك غامض، وتتوسع تدريجيًا لتشمل المزيد من الحالات والاحتمالات ذات الصلة، ثم تقوم بعملية تحديد للعثور على نقطة المشكلة التي تستحق الحل حقًا.</p><p>بتطبيق ذلك على تطبيقك، فإنه يتلخص في عدة أشياء.</p><p><strong>في مرحلة التوسع، تقوم بإدراج أكبر قدر ممكن من سيناريوهات الاستخدام المحتملة للمستخدم،</strong> والعقبات التي قد يواجهونها، والنتائج التي يأملون في الحصول عليها. أنت لا تستعجل في إصدار الأحكام، بل تخرج فقط كل الأشياء ذات الصلة من رأسك وتنثرها. على سبيل المثال، بالنسبة لتطبيق معالجة المستندات، يمكنك إدراج المستخدمين الذين قد يستخدمونه أثناء التنقل، أو قبل الاجتماعات، أو قبل كتابة التقارير، أو عند إجراء المراجعات؛ يمكنك إدراج مخاوفهم من عدم دقة الملخص، أو تشوه التنسيق، أو تفويت النقاط الرئيسية؛ يمكنك أيضًا إدراج رغبتهم في الفهم بشكل أسرع لما يريد مقال ما التعبير عنه، والعثور بشكل أسرع على الأجزاء المتعلقة بهم.</p><p><strong>في مرحلة التحديد</strong> <strong>، يجب أن تجبر نفسك على اختيار سيناريو أو سيناريوهين فقط من أكثر السيناريوهات شيوعًا وإيلامًا</strong> . على سبيل المثال، إذا اكتشفت من بين مجموعة السيناريوهات أن ما يذكره معظم الأشخاص هو رغبتهم في معرفة ما يحاول المستند الطويل في العمل قوله بالضبط، وما هي استنتاجاته الرئيسية عند استلامه. حينها يمكنك تحديد هدف التطبيق في إصداره الأول على أنه: مساعدة المستخدم على فهم المعنى الأساسي لمقال طويل في غضون خمس دقائق، بدلاً من محاولة حل جميع المشاكل المتعلقة بمعالجة المستندات في وقت واحد.</p><p>بنهاية الماس الأول، يجب أن تكون أكثر وضوحًا مما كنت عليه في البداية: <strong>ما هي المشكلة التي تريد حلها حقًا، ولماذا هي أولوية أعلى مقارنة بالمشاكل المحيطة الأخرى.</strong></p><h3 id="الماس-الثاني-تصميم-الحل،-من-الفكرة-الخشنة-إلى-الخطة-القابلة-للتنفيذ" tabindex="-1">الماس الثاني: تصميم الحل، من الفكرة الخشنة إلى الخطة القابلة للتنفيذ <a class="header-anchor" href="#الماس-الثاني-تصميم-الحل،-من-الفكرة-الخشنة-إلى-الخطة-القابلة-للتنفيذ" aria-label="Permalink to “الماس الثاني: تصميم الحل، من الفكرة الخشنة إلى الخطة القابلة للتنفيذ”">​</a></h3><p><strong>الجزء الثاني من الماس المزدوج يتعلق بولادة الحل</strong> . أنت تعرف بالفعل المشكلة التي تريد حلها تقريبًا، والخطوة التالية هي محاولة ابتكار أكبر عدد ممكن من الحلول لهذه المشكلة، ثم الفرز للعثور على الحل الأنسب للإصدار الأول. مرحلة التوسع هنا تعني الاستمرار في إضافة الأفكار. يمكنك العصف الذهني لمختلف الميزات، والسيناريوهات الأكثر تفصيلاً، والاستخدامات المحتملة. على سبيل المثال، بالنسبة لملخصات المقالات الطويلة، يمكنك تخيل مستويات مختلفة من التلخيص، وأشكال مختلفة لعرض النتائج، وما إذا كان سيتم دعم القراءة الصوتية، وما إذا كان يُسمح للمستخدمين بتمييز النقاط الرئيسية، وما إذا كان سيتم توفير إصدارات ملخصة بأساليب متعددة، وما إلى ذلك. لا تحتاج في هذه الخطوة إلى اتخاذ قرار فوري، بل فقط حاول إدراج جميع الاحتمالات قدر الإمكان.</p><p>في مرحلة التحديد، يجب إخراج أداة تقييم بسيطة ولكنها عملية للغاية: قيمة المستخدم × الجدوى × التكلفة الزمنية. يمكنك إعطاء درجة تقريبية لكل فكرة في هذه الأبعاد الثلاثة، على سبيل المثال من 1 إلى 5، ثم إعطاء الأولوية للأفكار ذات الدرجة الشاملة العالية والتكلفة الزمنية الخاضعة للرقابة كـ MVP (المنتج الأدنى القابل للتطبيق)، أي كجزء من الحد الأدنى من الإصدار القابل للتطبيق.</p><p>على سبيل المثال، قد تكون ميزة القراءة الصوتية ذات قيمة جيدة للمستخدم، ولكن التكلفة الزمنية لدمجها في الواجهة الأمامية والتقنية عالية جدًا؛ في حين أن استخراج الملخصات النصية البسيطة والنقاط الرئيسية له قيمة واضحة للمستخدم أيضًا، وجدواه عالية، وتكلفته الزمنية أقل، مما يجعله أكثر ملاءمة كوظيفة يجب إنجازها في الإصدار الأول.</p><p>في هذه العملية، يجب أن تذكر نفسك باستمرار بأمر واحد: <strong>الهدف من الإصدار الأول ليس إنشاء تطبيق مثالي، بل إنشاء إصدار موجود حقًا ويمكن للأشخاص استخدامه فعليًا</strong> . لا يحتاج إلى أن يكون شاملاً لكل شيء، بل يحتاج فقط إلى أن يؤدي أداءً لائقًا بما فيه الكفاية في مهمة محددة.</p><p>يمكنك رسم حد زمني بسيط للماس الثاني، على سبيل المثال يجب تسليم إصدار قابل للاستخدام في غضون شهر، لذلك من بين جميع الأفكار الموسعة، يمكن وضع جميع الميزات التي تستغرق أكثر من شهر أو حتى عدة أشهر لتطبيقها في قائمة &quot;للمراجعة لاحقًا&quot; بشكل مؤقت. بهذه الطريقة لن يتم سحبك للخلف في البداية لأنك تريد القيام بالكثير.</p><p>عندما تعتاد على استخدام نموذج الماس المزدوج لترتيب أفكارك، ستصبح العديد من المواقف التي كانت معقدة ومربكة واضحة ومباشرة. ستعرف في أي مرحلة يجب عليك التفكير بأكبر قدر ممكن، وفي أي مرحلة يجب عليك قطع بعض الاحتمالات بحزم. لن تأمل بعد الآن في حل جميع المشاكل دفعة واحدة، بل ستتعلم التبديل ذهابًا وإيابًا بين التوسع والتحديد.</p><h2 id="_2-2-الحصول-على-خطوات-قابلة-للتنفيذ-تعلم-كيف-تنتقل-من-التجريد-إلى-الواقع" tabindex="-1">2.2 الحصول على خطوات قابلة للتنفيذ: تعلم كيف تنتقل من التجريد إلى الواقع <a class="header-anchor" href="#_2-2-الحصول-على-خطوات-قابلة-للتنفيذ-تعلم-كيف-تنتقل-من-التجريد-إلى-الواقع" aria-label="Permalink to “2.2 الحصول على خطوات قابلة للتنفيذ: تعلم كيف تنتقل من التجريد إلى الواقع”">​</a></h2><p>بعد توسيع الأفكار، الحصول على الفكرة بحد ذاته بسيط جداً، لكن الحصول على خطوات قابلة للتنفيذ أمر صعب للغاية. القول بأنني أريد إنشاء أداة لتحسين الكفاءة، أو أريد إنشاء تطبيق لمساعدة المبدعين، يبدو ضخمًا وملحميًا. عندما يحين وقت التنفيذ الفعلي، فإن التجريد لا يساعد تقريبًا. ما تواجهه يوميًا هو مشاكل محددة للغاية: <strong>ما هو الجزء الصغير الذي يجب إنجازه في الإصدار الأول بالضبط، وما هي الصفحات المطلوبة</strong> ، هل يجب دعم التسجيل وتسجيل الدخول، وهل يجب ربط الدفع.</p><p>هنا هناك قدرة مطلوبة تسمى <strong>التفكيك والتدقيق، القدرة على تحويل التجريد إلى واقع ملموس</strong> . وهي تفكيك هدف كبير وعام، وتدقيق محتواه خطوة بخطوة إلى عناصر عمل دنيا يمكن البدء بها فورًا. هذه القدرة ليست مهمة فقط عند صنع المنتجات، بل هي حاسمة جدًا في الحياة أيضًا.</p><p><img src="'+P+'" alt=""></p><h3 id="لنبدأ-بمثال-من-الحياة-ماذا-يعني-حقًا-أنني-أريد-تناول-البرجر" tabindex="-1">لنبدأ بمثال من الحياة: ماذا يعني حقًا أنني أريد تناول البرجر <a class="header-anchor" href="#لنبدأ-بمثال-من-الحياة-ماذا-يعني-حقًا-أنني-أريد-تناول-البرجر" aria-label="Permalink to “لنبدأ بمثال من الحياة: ماذا يعني حقًا أنني أريد تناول البرجر”">​</a></h3><p>دعنا لا نتحدث عن التطبيقات الآن، ولنعد إلى مثال بسيط جدًا في الحياة: أريد تناول برجر. للوهلة الأولى، هذه الجملة ليست معقدة على الإطلاق، ولكن إذا قمت بتفكيكها بجدية، ستجد أنها تخفي العديد من الفروع المحددة.</p><p>أولاً <strong>الدافع والحاجة الجوهرية</strong> . هل تريد حقًا أكل برجر؟ هل أنت فقط تتوق إلى الطعم، أم تريد حل وجبة بسرعة، أم تريد التجمع مع الأصدقاء، أم فقط لأنك شاهدت صورة جميلة. يبدو هذا غير مهم، ولكنه سيؤثر بشكل مباشر على خياراتك اللاحقة. إذا كان الهدف هو التجمع مع الأصدقاء، فمن المرجح أن تكون هناك متطلبات للبيئة والتجربة؛ وإذا كنت تستعجل الوقت فقط، فقد تكون السرعة أهم من الطعم. ثانياً <strong>نطاق الإجراء</strong> . ما نوع البرغر الذي تريد أكله؟ في أي توقيت تريد تناول البرغر؟ هل تريد البرغر فقط، أم ترغب في وجبة كاملة مع مشروبات وبطاطس مقلية وحلويات؟ إذا كان لديك أشغال لاحقاً ولا تريد أن تأكل كثيراً، فقد يختلف اختيارك. يمكنك حتى أن تسأل نفسك بشكل أعمق: هل أريد حل مشكلة إفطار الغدى أيضاً، بأن آخذ معي برغر بسيط إضافي؟</p><p>ثم ننتقل إلى <strong>كيفية تحقيق هذا الأمر</strong> ؟ هل يجب عليك الذهاب إلى المتجر لتناول البرغر، أم يمكن توصيله لك، أو حتى هل أنت مستعد لتحضيره بنفسك في المنزل؟ كل خيار يقابله مسار عمل مختلف تماماً. اختيار الذهاب إلى المتجر يعني البحث عن الموقع، ومشاهدة أوقات العمل، وتخطيط المسار؛ اختيار التوصيل يعني الاطلاع على المنصات، ومقارنة الأسعار والوقت؛ اختيار التحضير بنفسك يعني تجهيز المكونات والأدوات والبحث عن وصفات.</p><p>عندما تقوم بتفكيك كل هذا بوضوح، فإن عبارة &quot;أريد أن آكل برغر&quot; التي كانت غامضة، ستصبح سلسلة من الخطوات الملموسة. مثلاً: فتح تطبيق التوصيل، البحث عن متجر جربته سابقاً وأعجبك، اختيار وجبة، إزالة المشروب والاكتفاء بالبرغر والبطاطس، كتابة ملاحظة بعدم وضع الصلصات، وأخيراً تأكيد الطلب. كل هذه الإجراءات صغيرة جداً، لكنها قابلة للتنفيذ الفوري، ويمكن برمجتها كخطة قابلة للتنفيذ آلياً بواسطة الذكاء الاصطناعي.</p><p><strong>أهمية التفكيك والتفصيل تكمن هنا: فهي تساعدك على الانتقال من رغبة تبدو كبيرة ومجردة، إلى قائمة يمكن تنفيذها عملياً.</strong></p><h3 id="مثال-تطبيقي-من-أين-تبدأ-بالضبط-لتحسين-كفاءة-معالجة-المستندات" tabindex="-1">مثال تطبيقي: من أين تبدأ بالضبط لتحسين كفاءة معالجة المستندات <a class="header-anchor" href="#مثال-تطبيقي-من-أين-تبدأ-بالضبط-لتحسين-كفاءة-معالجة-المستندات" aria-label="Permalink to “مثال تطبيقي: من أين تبدأ بالضبط لتحسين كفاءة معالجة المستندات”">​</a></h3><p>دعونا نلقي نظرة على مثال أكثر تعقيداً وتدرجاً. لنفترض أن لديك رغبة تبدو مشروعة: &quot;أريد إنشاء تطبيق يحسن كفاءة معالجة المستندات.&quot; هذا الاتجاه صحيح، لكن إذا توقفت عند هذه الجملة فقط، فلن تعرف من أين تبدأ تقريباً. لا تعرف ما هي الصفحة التي يجب تصميمها أولاً، ولا المدى الذي يجب أن يصل إليه الإصدار الأول، ناهيك عن كيفية شرح فكرتك للآخرين.</p><p>في هذا الوقت، يمكنك استخدام طريقة التفكيك والتفصيل المذكورة أعلاه، لتدقيقها خطوة بخطوة؛ وبسبب ضيق الوقت، سنعرض هنا مستويين فقط من طريقة التفكيك.</p><h4 id="التفكيك-والتفصيل-من-المستوى-الأول" tabindex="-1">التفكيك والتفصيل من المستوى الأول <a class="header-anchor" href="#التفكيك-والتفصيل-من-المستوى-الأول" aria-label="Permalink to “التفكيك والتفصيل من المستوى الأول”">​</a></h4><p><strong>أولاً، عليك أن تحدد ما هو &quot;المستند&quot;</strong> . المستند بحد ذاته مفهوم واسع، يمكن أن يكون جدولاً بيانات، أو تقريراً بصيغة Word، أو ملف PDF، أو نصاً بصيغة Markdown يسجل تعليقات الكود، أو ملاحظات بصيغة TXT، أو حتى مستنداً صورياً ناتجاً عن المسح، أو ورقة بحثية أكاديمية تتضمن رسوماً بيانية ومعادلات. الأنواع المختلفة من المستندات لها اختلافات في التنفيذ، ولكن وظائف &quot;المعالجة&quot; المصممة لاحقاً يجب أن تتطابق مع النوع المحدد للمستند، لذا من الضروري تفصيل تعريف المستند. إذا كان مستنداً صورياً، قد تحتاج إلى إضافة وظيفة التعرف البصري على الحروف (OCR) أولاً؛ وإذا كان مستنداً جدولياً، فإن الاحتياج الأساسي هو على الأرجح استخراج البيانات وتحليلها، وليس مجرد اختصار النصوص.</p><p><strong>ثانياً، تحتاج أيضاً إلى تحديد ما تعنيه &quot;المعالجة&quot;. إلى ماذا يتم تحويله، حتى يُعتبر &quot;مُعالجاً&quot;؟</strong> وما هي طريقة المعالجة؟ بعض الناس يقصدون بالمعالجة تلخيص تقرير من 50 صفحة إلى 5 صفحات مقروءة؛ وبعضهم يقصد تحويل مجموعة من ملفات Word و PDF و Markdown ذات التنسيقات الفوضوية إلى قالب موحد؛ وهناك من يهتم بالترجمة وإعادة الكتابة والتحسين، لتحويل مسودة مقبولة إلى نسخة رسمية قابلة للنشر. في هذه الخطوة يمكنك أن تسأل نفسك مباشرة: هل ما أقصده بـ &quot;المعالجة&quot; هو &quot;القراءة بشكل أسرع&quot;، أم &quot;التحسين بشكل أفضل&quot;، أم &quot;تسهيل نقلها للآخرين&quot;؟ الإجابات المختلفة تحدد بشكل مباشر أن صفحة الدخول وصفحة التشغيل التي ستصممها لاحقاً ستكون مختلفة تماماً.</p><p><strong>بالنسبة لـ &quot;التطبيق&quot; يحتاج أيضاً إلى تعريف. ما الذي يُسمى تطبيقاً</strong> ؟ هل هو أداة صغيرة لاستخدامك الشخصي فقط، أم تأمل أن يكون هناك مجموعة من المستخدمين في المستقبل؟ هل هو برنامج ويب، أم تطبيق هاتف، أم مجرد ميزة صغيرة مدمجة في نظام موجود؟ إذا كنت ترغب فقط في استخدامه على الكمبيوتر بنفسك، فإن تكلفة إنشاء صفحة ويب بسيطة أو نص برمجي لسطر الأوامر ستكون أقل بكثير؛ وإذا كنت تخطط لاستخدامه مع زملائك في الفريق، فقد تحتاج إلى التفكير في نظام الحسابات والصلاحيات ومنافذ التعاون. تبدو هذه وكأنها مشاكل اختيار تقني، ولكن في مرحلة التفكيك، تحتاج فقط للإجابة على جملة بسيطة جداً: على أي جهاز، وفي أي سيناريو، أخطط لاستخدام هذا الشيء.</p><p>بعد ذلك، <strong>دعنا نعود للجملة نفسها: &quot;تحسين كفاءة معالجة المستندات&quot;.</strong> تحتاج أيضاً إلى تفكيك عدة كلمات مفتاحية بوضوح. مثلاً <strong>&quot;تحسينها بمساعدة ماذا&quot;</strong> ؟ هل يجب استخدام الذكاء الاصطناعي بالضرورة؟ أم أنه ليس ضرورياً؟ يمكن حل بعض تحسينات الكفاءة تماماً باستخدام القوالب والاختصارات، مثل إنشاء غلاف تقرير بتنسيق ثابت بنقرة واحدة، أو إدراج إقرار تنصل قانوني قياسي بنقرة واحدة. هذه الاحتياجات قد لا تتطلب تدخل النموذج على الإطلاق. على العكس، إذا كنت تواجه كميات كبيرة من النصوص الطويلة غير المهيكلة وتحتاج إلى فهمها وتلخيصها وإعادة كتابتها، فإن الذكاء الاصطناعي سيكون حلقة طبيعية جداً.</p><p>كلمة &quot;الكفاءة&quot; تستحق أيضاً أن يتم تفكيكها بشكل منفصل. <strong>ماذا تعني الكفاءة بالضبط؟ هل تعني السرعة فقط، أم تشمل السرعة والجودة معاً، بالإضافة إلى معدل الخطأ وصعوبة الفهم؟</strong> مثلاً، تقليل وقت قراءة مستند من 20 صفحة من 30 دقيقة إلى 5 دقائق لمسح النقاط الرئيسية، هذه هي السرعة؛ السماح للمستخدم باكتشاف الأخطاء المنطقية والتناقضات في البيانات بسرعة داخل الملخص، هذه هي الجودة؛ جعل شخص غير مطلع على المصطلحات المهنية قادراً على فهم التقرير من خلال الشروحات والتعليقات التوضيحية، هذا هو خفض الحاجز المعرفي. يمكنك أن تسأل نفسك بصراحة: إذا نجح هذا التطبيق نجاحاً باهراً، فما هو أكبر تغيير سيحدث للمستخدم؟ هل هو &quot;أن الوقت الذي يقضيه في المستندات انخفض للنصف&quot;، أم &quot;أن القيام بالمهام المتعلقة بالمستندات لم يعد مرهقاً ذهنياً&quot;؟ بالإجابة بوضوح على هذا، سيكون لديك أساس لتحديد أولويات وظائفك.</p><p><img src="'+k+'" alt=""></p><h4 id="التفكيك-والتفصيل-من-المستوى-الثاني" tabindex="-1">التفكيك والتفصيل من المستوى الثاني <a class="header-anchor" href="#التفكيك-والتفصيل-من-المستوى-الثاني" aria-label="Permalink to “التفكيك والتفصيل من المستوى الثاني”">​</a></h4><p>ما سبق كان تفكيكاً من المستوى الأول. لنفترض أنه في هذه المرحلة، النتيجة الأولية للتفكيك والتفصيل التي يمكننا الحصول عليها هي: &quot;أريد إنشاء برنامج ويب يستخدم الذكاء الاصطناعي لتحسين سرعة وجودة تحويل مستندات PDF إلى نصوص&quot;. هذه الجملة أكثر تحديداً بكثير من &quot;تحسين كفاءة معالجة المستندات&quot; الأصلية: فهي تحدد نوع المستند (PDF)، وطريقة المعالجة (التحويل إلى نص)، واتجاه التحسين (السرعة والجودة)، والمسار التقني (الذكاء الاصطناعي)، والشكل الحامل (برنامج ويب). من منظور التعبير عن المتطلبات، انتقلت من رغبة مجردة إلى فكرة وظيفية واضحة نسبياً.</p><p>ولكن تجدر الإشارة إلى أن هذا الوصف لا يزال مجرد &quot;هدف وسيط&quot;، ولا يمكن اعتباره خطة منتج قابلة للتنفيذ حقاً. والسبب هو: <strong>لا تزال العديد من المعلومات الرئيسية فيه عامة، مثل &quot;أي ذكاء اصطناعي سيتم استخدامه&quot; و &quot;إلى أي مدى سيتم التحسين&quot; و &quot;ما هي سيناريوهات الاستخدام المتوافقة&quot; و &quot;ما هي الفئة المستهدفة من المستخدمين&quot;.</strong> لذلك، يمكننا، بل ومن الضروري، <strong>الاستمرار في التفكيك للأسفل، لتحويل هذه الجملة إلى مجموعة من القرارات التصميمية والحلول التقنية بتفاصيل دقيقة</strong> .</p><p>دعنا ننظر أولاً إلى &quot;الذكاء الاصطناعي&quot; المذكور. هل &quot;الذكاء الاصطناعي&quot; هنا يشير إلى نموذج OCR خفيف مسؤول فقط عن التعرف على النصوص، أم أن هناك حاجة لإدخال نموذج لغوي كبير، أو حتى نموذج متعدد الوسائط، للقيام بتصحيح الأخطاء اللاحق، وإعادة ترتيب الصفحات، وإعادة ترتيب المحتوى، وفهم الهيكل؟ الخيارات المختلفة ستجلب عواقب مختلفة تماماً في ثلاثة أبعاد:</p><ul><li>استهلاك التكلفة: بما في ذلك تكلفة قوة الحوسبة، ورسوم الاستدعاء، وزمن الاستدعاء، إلخ. هل هي تكلفة لمرة واحدة بشكل أساسي، أم نفقات مستمرة؟</li><li>صعوبة التطوير: هل يكفي دمج واجهة OCR الحالية ببساطة، أم أن هناك حاجة لتصميم Prompts معقدة، وإدارة السياق، وحتى بناء نظام تدريب وتقييم ذاتي؟</li><li>شكل المنتج واستراتيجية الإطلاق: هل سيتم إنشاء &quot;أداة صغيرة لاستخراج النصوص بسرعة&quot;، أم &quot;منصة ذكية لمعالجة المستندات&quot; قادرة على استعادة الهيكل العام، والجداول، ومستويات العناوين، ومناسبة للقراءة المتعمقة وإعادة استخدام المحتوى؟</li></ul><p>ثم <strong>التفكيك الإضافي لـ &quot;مستند PDF&quot;. ما هو نوع PDF الذي تريد دعمه بالضبط؟</strong> إذا تم قصر النطاق على &quot;ملفات PDF نصية يمكن نسخها&quot;، فلا داعي للتعامل مع الملفات الممسوحة ضوئياً، والرسوم البيانية المعقدة، وتنسيقات المعادلات منذ البداية، ولا داعي للتحمل من أجل المستندات ذات الأعمدة المتعددة أو التنسيقات الباهظة. من ناحية أخرى، إذا كنت تأمل في تحقيق &quot;إمكانية إلقاء أي PDF فيها&quot;، فهذا يعني أنه يجب عليك حل سلسلة من المشاكل عالية الصعوبة مثل التعرف الضوئي على الحروف (OCR) لملفات PDF المصورة، وإعادة بناء التخطيط، والخلط بين الصور والنصوص، واستخراج الجداول في وقت واحد، مما سيضاعف تعقيد المشروع.</p><p>في هذا المستوى، يمكنك عمداً القيام بعملية &quot;تضييق&quot;، وكتابة التنازلات بوضوح. على سبيل المثال: الإصدار الحالي يخدم بشكل أساسي &quot;تقارير ومستندات PDF النصية ذات الهيكل الواضح نسبياً&quot;، ولا يوجد ضمان لنتائج المستندات الممسوحة ضوئياً أو المستندات التي تحتوي على خلط كبير بين الصور والنصوص. بهذه الطريقة، تصبح جميع الأهداف اللاحقة المتعلقة بـ &quot;السرعة&quot; و&quot;الجودة&quot; مبنية على فرضية يمكن التحكم فيها ويمكن تفسيرها نسبياً، كما يسهل توضيح الحدود في وصف المنتج وإدارة توقعات المستخدمين.</p><p>التالي هو &quot;التحويل إلى نصوص بجودة عالية&quot;. يمكن تفكيك &quot;الجودة&quot; هنا إلى ثلاثة أبعاد قابلة للنقاش وقابلة للموازنة على الأقل:</p><ol><li><strong>هل التعرف صحيح بشكل عام</strong> : ما مدى دقة التعرف على الأخطاء المطبعية، وعلامات الترقيم، والرموز الخاصة، وهل ستظهر فقرات كاملة من نصوص غير مفهومة.</li><li><strong>هل يتم الحفاظ على هيكل الفقرات والعناوين</strong> : هل يمكن استعادة مستويات الفصول، وفواصل الفقرات، وهيكل القوائم، وكتل الاقتباس في النص الأصلي قدر الإمكان بعد التحويل إلى نص عادي.</li><li><strong>هل هو مناسب للتحرير الثانوي وإعادة الاستخدام</strong> : هل النص المُنشأ نظيف بما فيه الكفاية، وهل التنسيق منظم، وعندما يقوم المستخدم بنسخه لاحقاً إلى Word أو Notion أو محرر أكواد، هل سيحتاج إلى تنظيف يدوي واسع النطاق.</li></ol><p><strong>يمكنك أولاً اختيار أهم بند أو بندين بالنسبة لك، كاتجاه رئيسي لـ &quot;الجودة&quot;</strong> . على سبيل المثال: إعطاء الأولوية لـ &quot;هيكل فقرات واضح&quot; و&quot;الحفاظ على مستويات العناوين بشكل أساسي&quot;، والاكتفاء في الأخطاء المطبعية بمستوى &quot;يمكن للمستخدم إصلاحها يدوياً بسرعة في غضون دقائق&quot;. بهذه الطريقة، لم تعد &quot;الجودة العالية&quot; صفة فارغة، بل يمكن تحويلها إلى معيار منتج قابل للكتابة والقياس: يُسمح بأخطاء التعرف العرضية، ولكن لا يمكن قطع المستند إلى أجزاء مبعثرة بفقرات فوضوية، ناهيك عن جعل المستخدم يبذل جهداً أكبر في ترتيب الهيكل مقارنة بالنسخ اليدوي.</p><p>دعنا ننظر إلى &quot;السرعة&quot;. بما أنك كتبت في الهدف &quot;تحسين... السرعة والجودة&quot;، فيجب أن يتم تحديد &quot;السرعة&quot; بشكل ملموس إلى <strong>مستوى معين يمكن الشعور به،</strong> بدلاً من البقاء عند &quot;يبدو أسرع نسبياً&quot;. في الواقع، هناك مفاضلة مهمة مخفية هنا:</p><ul><li>هل تأمل في دعم المستندات الطويلة جداً (عشرات الصفحات أو مئات الصفحات)، حتى لو كان المستخدم يحتاج إلى الانتظار لفترة أطول؟</li><li>أم أنّه يستهدف فقط المستندات المتوسطة والقصيرة، وفي ظل وجود حد أقصى لعدد الصفحات، تحقيق تجربة &quot;الحصول على النتيجة خلال بضع ثوانٍ إلى عشر ثوانٍ&quot;؟</li></ul><p>إذا كان سيناريو الاستخدام النموذجي لديك هو: قبل الاجتماع، تقوم بتحويل تقرير أو خطة أو ملخص بحث من عشرات الصفحات بسرعة إلى نص قابل للتعديل من أجل التعليق والتعديل والاقتباس، فإن الخيار الأكثر طبيعية هو:</p><ul><li>وضع حد أقصى معقول لعدد صفحات المستند الواحد، مثل &quot;ملف PDF نصي لا يتجاوز 20 صفحة&quot;؛</li><li>في الوقت نفسه، تقديم مؤشر تقريبي لوقت المعالجة، مثل &quot;عادةً ما تتم المعالجة في غضون 10 ثوانٍ تقريبًا&quot;.</li></ul><p>بمجرد كتابة هذين الأمرين بوضوح، يمكن عندها بناء الحلول التقنية اللاحقة (هل هناك حاجة إلى معالجة متوازية، هل يجب إنشاء قائمة انتظار غير متزامنة)، ونصوص الواجهة (الوقت المقدر المعروض على الصفحة، ومطالبات انتهاء المهلة)، وإدارة توقعات المستخدم، حول التجربة الأساسية المتمثلة في &quot;المستندات المتوسطة والقصيرة + استجابة سريعة&quot;.</p><p><strong>أخيرًا، &quot;برنامج الويب&quot; بحد ذاته. يبدو هذا العنصر مجرد اختيار للوسيط، ولكنه في الواقع يحتاج أيضًا إلى تقييد معقول،</strong> لتجنب الانجرار المبكر نحو شكل منتج معقد للغاية. يمكنك أن تسأل نفسك أولاً سؤالاً محورياً:</p><ul><li>هل يشبه هذا أكثر &quot;أداة مؤقتة لي ولاستخدام داخلي محدود&quot;؟</li><li>أم أنه مخطط له منذ البداية ليكون &quot;خدمة عبر الإنترنت لمجموعة من المستخدمين الحقيقيين لاستخدامها على المدى الطويل&quot;؟</li></ul><p>إذا كان يميل أكثر إلى الخيار الأول، يمكنك عندها التخلص بجرأة من الكثير من التعقيدات: لا حاجة لبناء نظام حسابات كامل وإدارة صلاحيات، ولا حاجة لتنفيذ ميزات مثل سجل المهام، وإدارة المشاريع، والعمل الجماعي في الإصدار الأول، بل التركيز على مسار مبسط للغاية: <strong>فتح صفحة الويب ← تحميل ملف PDF ← انتظار المعالجة ← عرض النص القابل للتعديل ← نسخ أو تنزيل بنقرة واحدة</strong>. على العكس من ذلك، إذا كان الهدف هو تقديم خدمة مستقرة رسميًا للجمهور، فستحتاج في الإصدارات اللاحقة إلى النظر تدريجيًا في قدرات التزامن، وجدولة قوائم الانتظار، وحصص المستخدمين، والاستعادة بعد الأعطال، والسجلات والمراقبة، والأمان وإدارة الصلاحيات، وغيرها. ولكن في مرحلة التفكيك الحالية، يمكنك تمامًا تعريفه أولاً على أنه &quot;أداة صغيرة قائمة على المتصفح، يمكن استخدامها دون تسجيل الدخول&quot;، والتركيز كل التفاعلات على أبسط المسار وأكثرها جوهرية.</p><p>تحتاج إلى أخذ <strong>المفاضلات الكامنة وراء الكلمات المفتاحية</strong> مثل &quot;الذكاء الاصطناعي&quot;، &quot;مستند PDF&quot;، &quot;التحويل عالي الجودة إلى نص&quot;، &quot;متطلبات السرعة&quot;، &quot;برنامج الويب&quot;، <strong>التعبير عنها بوضوح بكلمات أكثر تحديدًا</strong>. عندها يمكن إعادة صياغة تلك الجملة الأولى &quot;أريد إنشاء برنامج ويب يعتمد على الذكاء الاصطناعي لتحسين سرعة وجودة تحويل مستندات PDF إلى نص&quot; لتصبح أكثر إحكامًا ووضوحًا وقابلية للتنفيذ. على سبيل المثال:</p><blockquote><p>تزويد المستخدمين بأداة صغيرة قائمة على المتصفح، تُعطي الأولوية لدعم تقارير PDF الواضحة الهيكل والنصية في الغالب، ومن خلال عملية تحليل متكيفة وتنظيف خفيف بواسطة الذكاء الاصطناعي، يتم إخراج نص قابل للتعديل بهيكل فقرات واضح، ومستويات عناوين محفوظة بشكل أساسي، ومعدل أخطاء تعرف مقبول، في غضون 10 ثوانٍ تقريبًا، مع إمكانية استخدامه دون الحاجة إلى تسجيل الدخول.</p></blockquote><p>عند هذه النقطة، تكون قد أكملت انتقالًا مهمًا من الهدف المجرد إلى خطة قابلة للتنفيذ، وبعد بعض التنقيح يمكنك الحصول على وصف في جملة واحدة:</p><blockquote><p>تزويد المستخدم بأداة ويب تمكنه من رفع ملف PDF نصي لا يتجاوز 20 صفحة، والحصول على نص قابل للتعديل بهيكل فقرات واضح ومستويات عناوين محفوظة في غضون 10 ثوانٍ تقريبًا، مع دعم النسخ بنقرة واحدة والتنزيل كملف <code>.txt</code>.</p></blockquote><p>هذا النوع من الوصف لم يعد شعارًا فارغًا، بل يمكن أن يتحول مباشرة إلى مطالبة (Prompt)، أو مجموعة من التعليمات التي يمكن للذكاء الاصطناعي تنفيذها كخطة (Plan). على سبيل المثال، يمكنك ببساطة إلقاء هذا النص على ذكاء اصطناعي يمتلك قدرات تطوير، وجعله يُنشئ خطة تطوير بناءً عليه أو يُنشئ مباشرة الحد الأدنى من الإصدار القابل للاستخدام من تطبيق الويب؛ يمكنك أيضًا تسليمه لمصمم ليقوم برسم نموذج أولي ملموس للواجهة بناءً عليه؛ أو إرساله إلى زميل مهندس ليقوم بتقييم تكلفة التنفيذ والحل التقني بسرعة.</p><p><img src="'+x+'" alt=""></p><p>عندما تصل إلى هذه المرحلة، ستلاحظ تغييرين واقعيين للغاية. أولاً، لن تشعر بثقل عبارة &quot;أريد إنشاء تطبيق يزيد من الكفاءة&quot;، بل ستمتلك خطوات يمكنك البدء بها فورًا. ثانيًا، ستنخفض تكلفة التواصل مع الآخرين بشكل كبير، لأنك ستقدم مجموعة أولى من الخطة التي تم تفكيكها بما يكفي من التفاصيل.</p><p>الانتقال من المجرد إلى الملموس هو في الواقع أخذ أمنية كبيرة مثل &quot;أريد إنشاء تطبيق يحسن كفاءة معالجة المستندات&quot; وتفكيكها إلى قائمة مهام يمكن لأي شخص أو حتى أي ذكاء اصطناعي فهمها والبدء في تنفيذها على الفور. من خلال هذه الطريقة، لن تكون هناك مشاكل يصعب حلها، فجميع المشاكل عند تفكيكها إلى مستوى ذري لا يكون أمامها سوى خيارين، وطالما يمكن تفكيكها إلى مستوى ذري، يمكن تنفيذها:</p><ol><li>سأقوم أنا بحل وتنفيذ هذه المشكلة الفرعية.</li><li>الذكاء الاصطناعي أو خبير آخر سيقوم بحل وتنفيذ هذه المشكلة الفرعية.</li></ol><h2 id="_2-3-تصور-تطبيقك-على-السبورة-ارسم-تطبيقك-الأول" tabindex="-1">2.3 تصور تطبيقك على السبورة: ارسم تطبيقك الأول <a class="header-anchor" href="#_2-3-تصور-تطبيقك-على-السبورة-ارسم-تطبيقك-الأول" aria-label="Permalink to “2.3 تصور تطبيقك على السبورة: ارسم تطبيقك الأول”">​</a></h2><p>كثير من الناس عندما يفكرون في البدء بإنشاء تطبيق، فإن أول ما يتبادر إلى ذهنهم هو الكود، والخلفية (Backend)، وقواعد البيانات، والواجهات (APIs)، والأطر (Frameworks). هذا ليس غريباً، لأن الفكرة التي غُرست في عقولنا لفترة طويلة هي: إنشاء تطبيق هو في المقام الأول مشكلة تقنية. ولكن إذا ركزت كل انتباهك على التكنولوجيا منذ البداية، فمن السهل أن تتجاهل الشيء الأكثر أهمية: <strong>ما الذي سيفعله المستخدم بالضبط هنا</strong>.</p><p>في هذه النقطة، فإن أحد أبسط الأساليب - والذي غالبًا ما يتم تجاهله - هو الرسم أولاً. لست بحاجة إلى أي برنامج احترافي، فالسبورة، أو ورقة بيضاء، أو دفتر ملاحظات، كلها تفي بالغرض. المهم أن تقوم برسم مسار المستخدم بالكامل من دخوله حتى خروجه باستخدام بضع رسومات بسيطة للصفحات (Sketches)، بدلاً من التوجه مباشرة لفتح محرر الكود لكتابة البرمجيات.</p><p>يمكنك تقسيم التطبيق بأكمله أولاً إلى ثلاث فئات من الصفحات: صفحة الدخول، وصفحة العمليات، وصفحة النتائج.</p><p><img src="'+A+'" alt=""></p><h3 id="صفحة-الدخول-من-أين-يدخل-المستخدم،-وماذا-يرى-للوهلة-الأولى" tabindex="-1">صفحة الدخول: من أين يدخل المستخدم، وماذا يرى للوهلة الأولى <a class="header-anchor" href="#صفحة-الدخول-من-أين-يدخل-المستخدم،-وماذا-يرى-للوهلة-الأولى" aria-label="Permalink to “صفحة الدخول: من أين يدخل المستخدم، وماذا يرى للوهلة الأولى”">​</a></h3><p>صفحة الدخول هي المكان الذي يرى فيه المستخدم تطبيقك لأول مرة. الكثير من الناس عند تصميم صفحة الدخول في البداية، لا يفكرون إلا في إنشاء صفحة رئيسية عامة، مليئة بأزرار الوظائف، ومداخل الوحدات، ومساحات الإعلانات، وكأن هذا هو الطريقة الوحيدة لإظهار أن المنتج مليء بالميزات ورائع. ولكن إذا قمت برسم هذه الصفحة على الورق، وعلقتها على الجدار، ثم تخيلت أنك شخص يزورها لأول مرة، ستدرك فجأة مشكلة واقعية للغاية: <strong>أين يجب أن أنقر أولاً؟</strong></p><p>عند رسم صفحة الدخول، يمكنك أن تعتبر نفسك مرشدًا سياحيًا. اطرح بعض الأسئلة المحددة للغاية: كيف يدخل المستخدم، هل عبر النقر على رابط مشاركة، أم بالبحث في متجر التطبيقات، أم عن طريق مسح رمز QR على صفحة ويب؟ المصادر المختلفة تعني توقعات مختلفة تمامًا للمستخدم تجاهك. على سبيل المثال، المستخدم الذي يدخل عبر رابط أعاده توجيهه صديق يعرف بالفعل تقريبًا ما يمكنك فعله، وفي هذه الحالة يمكن أن تكون صفحة الدخول أكثر مباشرة، ليتجرب الوظيفة الأساسية على الفور؛ بينما الشخص الذي عثر عليك عبر متجر التطبيقات قد لا يعرف عنك شيئًا، وفي هذه الحالة <strong>ستحتاج صفحة الدخول إلى مساعدته في فهم ما تفعله في جملة واحدة، أو أن يكون شكلها يوحي بالاستخدام بمجرد النظر</strong>.</p><p>أثناء الرسم، يمكنك اتباع هذه المعالجة البسيطة: ارسم إطار شاشة هاتف على الورق، واكتب عنوان هذه الصفحة في الأعلى، وارسم المنطقة الرئيسية في المنتصف. وقم بتدوين الملاحظات بوضوح: ماذا أريد أن أخبر المستخدم في هذه الصفحة، وما هو الاختيار الذي أتمنى أن يتخذه هنا. على سبيل المثال، هل تريد منه النقر على زر &quot;ابدأ&quot; كبير، أم تجعله يرى أولاً نتيجة مثال قصيرة، أو يملأ بعض المعلومات الأساسية البسيطة. كلما كانت صفحة البدء أبسط وأكثر تحديدًا، زادت فرصك في جعل المستخدم الجديد لا يضيع ويبدأ الاستخدام بسرعة.</p><h3 id="صفحة-العمليات-ماذا-يحتاج-المستخدم-لإدخاله،-والنقر-عليه،-واختياره" tabindex="-1">صفحة العمليات: ماذا يحتاج المستخدم لإدخاله، والنقر عليه، واختياره <a class="header-anchor" href="#صفحة-العمليات-ماذا-يحتاج-المستخدم-لإدخاله،-والنقر-عليه،-واختياره" aria-label="Permalink to “صفحة العمليات: ماذا يحتاج المستخدم لإدخاله، والنقر عليه، واختياره”">​</a></h3><p>بمجرد أن يقرر المستخدم المضي قدمًا، ستكون الخطوة التالية في صفحة العمليات، وهي منطقة العمل الخاصة بالتطبيق بأكمله. هذا هو المكان الذي يتفاعل فيه المستخدم معك بشكل حقيقي، وهو أيضًا المكان الذي يبالغ الكثيرون في تصميمه بتعقيد.</p><p>عند رسم صفحة العمليات، فإن تمرينًا فعالًا للغاية هو: <strong>السماح للمستخدم بفعل شيء واحد فقط</strong>. يمكنك كتابة أبسط تعبير لهذا الشيء على الورق، مثل &quot;إرسال نص&quot;، &quot;تسجيل فكرة صوتيًا&quot;، &quot;اختيار قالب&quot;، &quot;تكوين معلمة&quot;. ثم التركيز حول هذا الشيء، ومحاولة تقليل العناصر قدر الإمكان، لترى ما هي المدخلات والأزرار الضرورية فقط.</p><p>خذ تطبيق التلخيص التلقائي للمقالات الطويلة كمثال. صفحة العمليات الأكثر خشونة ولكنها قادرة على إتمام المسار قد تحتاج فقط إلى بضعة أشياء: مربع إدخال يمكن لصق النص فيه، وخيار لاختيار طول الملخص، وزر لإنشاء الملخص. يمكنك بكل بساطة ألا تأخذ في الاعتبار حجم الخط، والألوان، والأيقونات، وتلك التفاصيل البصرية الدقيقة، بل ركز على هذه الأسئلة: <strong>هل يعرف المستخدم بمجرد دخوله إلى هذه الصفحة ما الذي يجب عليه فعله، وما هي الأشياء التي يحتاج إلى تحضيرها، وهل سيشعر بالحيرة في منتصف الطريق ولا يعرف الخطوة التالية؟</strong></p><p>فائدة التفكير في صفحة العمليات على الورق هي أنه يمكنك تجربة إصدارات مختلفة بتكلفة منخفضة للغاية. يمكنك أولاً رسم إصدار تكون فيه جميع المدخلات في نفس الصفحة، ثم رسم إصدار آخر مقسم إلى خطوتين كمعالج صغير، ثم تقوم بتمثيل سيناريو الاستخدام في ذهنك عدة مرات: أي إصدار أقل عرضة لأن يعلق فيه المستخدم. مقارنة بتغيير المسار في كود مكتوب بالفعل، فإن هذا التعديل على الورق يكاد يكون بدون تكلفة.</p><h3 id="صفحة-النتائج-ماذا-حصل-المستخدم،-وكيف-يتم-عرضه" tabindex="-1">صفحة النتائج: ماذا حصل المستخدم، وكيف يتم عرضه <a class="header-anchor" href="#صفحة-النتائج-ماذا-حصل-المستخدم،-وكيف-يتم-عرضه" aria-label="Permalink to “صفحة النتائج: ماذا حصل المستخدم، وكيف يتم عرضه”">​</a></h3><p>العديد من التطبيقات تتسرع في خطوة النتيجة هذه. غالبًا ما يعتقد المطورون أن النتيجة ليست سوى نص، أو صورة، أو سلسلة بيانات، ويكفي عرضها فحسب. ولكن بالنسبة للمستخدم، غالبًا ما يكون العكس هو الصحيح: فالسبب الأساسي الذي جعله على استعداد للإدخال، والانتظار، والتجربة في الخطوات السابقة، هو أنه يتوقع رؤية شيء واضح ومفيد بما فيه الكفاية في صفحة النتائج.</p><p>عند رسم صفحة النتائج، يمكنك التفكير من عدة زوايا: <strong>ما هي المعلومات الأساسية التي يهتم بها المستخدم أكثر، وأين يجب وضعها في أكثر الأماكن بروزًا</strong>. ما هي النتائج التي تحتاج إلى تصدير، أو حفظ، أو مشاركة، وأين يقع مدخلها. هل من الضروري إضافة بعض الشروحات البسيطة للنتائج، لإعلام المستخدم بما تمثله.</p><p>بالعودة إلى مثال تلخيص المقالات الطويلة، فإن تصميم صفحة نتائج ودية نسبيًا هو: سرد الاستنتاجات الأساسية في الأعلى باستخدام بضع نقاط موجزة، وتحت ذلك وضع ملخص أكثر تفصيلاً، مع الاحتفاظ برابط النص الأصلي في الأسفل. وضع زرين بارزين على الجانب: أحدهما لنسخ النقاط الرئيسية، والآخر للتصدير كملف. يمكنك محاولة رسم تخطيط هذه المناطق على الورق، وتدوين الإجراء المتوقع لكل زر.</p><p>عند الانتهاء من رسم صفحة الدخول، وصفحة العمليات، وصفحة النتائج، قم بربطها بأسهم، <strong>بدءًا من دخول المستخدم لأول مرة، وصولاً خطوة بخطوة إلى النهاية. ستكشف هذه العملية عن العديد من المشاكل التي لم تكن تدركها من قبل:</strong> على سبيل المثال، إذا أراد المستخدم تعديل تفصيلة في صفحة النتائج، فكيف يعود إلى صفحة العمليات؛ أو في صفحة العمليات، إذا كان غير متأكد من ما إذا كان يريد الاستمرار أم لا في الوقت الحالي، فهل توجد طريقة واضحة للخروج أو حفظ المسودة. الجوهر الأساسي لهذا الفصل بأكمله يمكن تلخيصه في جملة واحدة: ارسم عملية تفاعل المستخدم أولاً، ثم فكر في التنفيذ التقني. يمكنك ألا تعرف كتابة الأكواد على الإطلاق، ومع ذلك لا يزال بإمكانك <strong>من خلال بضع رسومات بسيطة، تحويل فكرة إلى نموذج أولي مرئي للتطبيق</strong>. كلما كانت هذه الخطوة أوضح، سيصبح الأمر أسهل بكثير لاحقًا، سواء قمت بالتنفيذ بنفسك أو بالتعاون مع الآخرين.</p><h2 id="_2-4-الإشارة-إلى-تطبيقات-الآخرين-نقل-الأفكار-بذكاء" tabindex="-1">2.4 الإشارة إلى تطبيقات الآخرين: &quot;نقل الأفكار بذكاء&quot; <a class="header-anchor" href="#_2-4-الإشارة-إلى-تطبيقات-الآخرين-نقل-الأفكار-بذكاء" aria-label="Permalink to “2.4 الإشارة إلى تطبيقات الآخرين: &quot;نقل الأفكار بذكاء&quot;”">​</a></h2><p>الكثير من الأشخاص عند بناء تطبيقهم الأول، يشعرون بحمل نفسي: يعتقدون أنه يجب عليهم البدء من الصفر، وأن يكون هيكل الصفحة، وطريقة التفاعل، والتصميم المرئي أصلية بالكامل، وكأن هذا هو الشرط الوحيد لصنع منتج حقيقي. الواقع هو أنك إذا تمسكت بهذا المبدأ، فستستنزف الكثير من طاقتك في تفاصيل غير مهمة.</p><p>في مجال تصميم التطبيقات، هناك موقف أكثر كفاءة ونضجاً يُسمى <strong>نقل الأفكار بذكاء</strong>. لا يتعلق الأمر بالنسخ البسيط، بل بالاقتراض الانتقائي للحلول الجيدة التي أثبتت جدواها من قبل الآخرين، مع ترك طاقتك لأكثر الأماكن التي يجب أن تُستثمر فيها قيمتك الفريدة.</p><p>هناك العديد من المواقع على الإنترنت التي تجمع لقطات شاشة لواجهات التطبيقات، وهناك أيضًا صفحات تفصيلية في متاجر التطبيقات، وهذه الأماكن بحد ذاتها تشبه كتاب مرجعية ضخمًا. يمكنك اختيار بعض التطبيقات القريبة من اتجاهك، مثل الأدوات المماثلة، أو المنتجات الموجهة لنفس الفئة، ثم دراستها صفحة بصفحة كما لو كنت تدرس عينات.</p><p>النقطة المهمة التي يجب مراقبتها ليست مدى جمال الألوان، بل كيف يتعاملون مع عدة مناطق رئيسية:</p><ul><li>كيف تم تصميم شريط التنقل، هل هو في الأسفل أم الأعلى، وهل هناك بضع نقاط دخول رئيسية ثابتة أم زر رئيسي واحد فقط</li><li>كيف يتم تنظيم النماذج (Forms)، هل يتم ملؤها دفعة واحدة في نفس الصفحة، أم يتم تقسيمها إلى خطوات صغيرة متعددة</li><li>عند عرض النتائج، هل تم وضع المعلومات الأهم في أكثر الأماكن وضوحًا، وكيف تم ترتيب المعلومات الثانوية</li><li>عندما يدخل المستخدم الجديد لأول مرة، هل هناك عملية إرشاد قصيرة تخبره بكيفية الاستخدام</li></ul><p><img src="'+I+'" alt=""></p><p><img src="'+C+'" alt=""></p><p>تحديداً، يمكنك الرجوع إلى مواقع جمع لقطات الشاشة التالية:</p><ul><li><a href="https://www.uisources.com/" target="_blank" rel="noreferrer">https://www.uisources.com/</a></li><li><a href="https://screenlane.com/" target="_blank" rel="noreferrer">https://screenlane.com/</a></li><li><a href="https://pagecollective.com/" target="_blank" rel="noreferrer">https://pagecollective.com/</a></li><li><a href="https://patttterns.net/" target="_blank" rel="noreferrer">https://patttterns.net/</a></li><li><a href="https://mobbin.com/" target="_blank" rel="noreferrer">https://mobbin.com/</a></li><li><a href="https://refero.design/" target="_blank" rel="noreferrer">https://refero.design/</a></li><li><a href="https://scrnshts.club/" target="_blank" rel="noreferrer">https://scrnshts.club/</a></li><li><a href="https://godly.website" target="_blank" rel="noreferrer">https://godly.website</a></li></ul><p>بالإضافة إلى الإشارة المباشرة إلى تطبيقات الآخرين، يمكننا أيضاً الحصول على الإلهام من بعض المسابقات، مثل الأعمال الفائزة في الهاكاثون (Hackathon) (وهو نشاط تطوير تعاوني جماعي مكثف ومحدد بوقت، يتطلب إكمال نموذج أولي للمنتج أو حلاً في وقت قصير) وبعض مواقع العروض التوضيحية (Demo) العامة. في جوهرها، هذه هي الحلول التي قدمها مجموعة من الممارسين في وقت قصير جداً. ورغم أنها بدائية، إلا أنها تظهر بالضبط كيفية إكمال العملية المضغوطة من الفكرة إلى المنتج القابل للتشغيل في وقت محدود. يمكنك الرجوع إلى أعمالهم للتفكير في ما يسمى النموذج الأولي الأدنى للمنتج؛ ولكن نظراً لأن الهاكاثون هو دائماً مسابقة قصيرة المدى، فمن المحتمل أن تكون الإبداعية أكبر من التطبيق العملي، وأعمالها الفائزة ليست بالضرورة مناسبة كمنتج طويل الأمد للرجوع إليه والتطوير، وتحتاج إلى الحكم بناءً على الموقف الفعلي.</p><p>بالإضافة إلى ذلك، يمكنك أيضاً الإشارة إلى بعض مواقع الأدوات للعمل، ويمكن فهم مواقع الأدوات هذه على أنها مواقع مشابهة لموقع استعلام الطقس، ومواقع الترجمة متعددة اللغات، ومواقع تجميع دليل البوكيمون، ومواقع أدلة الألعاب، ومواقع ترتيب السيارات الشائعة، ومواقع أدوات AI. ورغم أن هذه المواقع الأدواتية بسيطة جداً في وظائفها، إلا أنها قد تكون &quot;تطبيقاً&quot; ممتازاً يلبي احتياجات بعض الأشخاص. الفكرة لا تكمن في التعقيد بل في الفائدة، ومن خلال الإشارة إلى التطبيقات المختلفة، يمكنك حقاً معرفة ما هو الطلب في السوق.</p><h2 id="_2-5-لا-تنتظر-حتى-يكون-كل-شيء-جاهزاً-لبحث-احتياجات-المستخدم" tabindex="-1">2.5 لا تنتظر حتى يكون كل شيء جاهزاً لبحث احتياجات المستخدم <a class="header-anchor" href="#_2-5-لا-تنتظر-حتى-يكون-كل-شيء-جاهزاً-لبحث-احتياجات-المستخدم" aria-label="Permalink to “2.5 لا تنتظر حتى يكون كل شيء جاهزاً لبحث احتياجات المستخدم”">​</a></h2><p>الكثير من الأشخاص يقولون بأفواههم إنهم يريدون صنع منتج يحركه المستخدم، ولكن عند التنفيذ الفعلي، يميلون إلى الانغلاق أولاً لصنع نسخة كاملة في أذهانهم، ثم يجمعون الشجاعة لإظهارها للآخرين. <strong>يبدو هذا أكثر احترامية، على الأقل لن تعرض منتجك غير المكتمل للآخرين. ولكن من منظور المنتج، هذه عادة خطيرة جداً.</strong></p><p>السبب بسيط: كلما تأخرت في التواصل مع المستخدمين، زاد استثمارك في التفاصيل في المراحل السابقة، وبمجرد أن يكون الاتجاه خاطئاً، ستكون الخسائر أكبر. ربما تكون قد كتبت الكثير من الأكواد لميزة غير مهمة، وصممت الكثير من الرسومات لتفصيل لا يهتم به الكثيرون، لتكتشف في النهاية أن المكان الذي عجز فيه المستخدم حقاً ليس الجزء الذي قضيت فيه معظم وقتك.</p><p>لتجنب هذا الموقف، هناك مبدأ موجز ولكنه فعال يمكنك تذكير نفسك به دائماً: اسأل وأنت ترسم، <strong>اسأل وأنت تفعل، لا تسأل بعد أن تنتهي.</strong></p><h3 id="اسأل-وأنت-ترسم-ابدأ-في-جمع-التعليقات-في-مرحلة-الورقة-والقلم" tabindex="-1">اسأل وأنت ترسم: ابدأ في جمع التعليقات في مرحلة الورقة والقلم <a class="header-anchor" href="#اسأل-وأنت-ترسم-ابدأ-في-جمع-التعليقات-في-مرحلة-الورقة-والقلم" aria-label="Permalink to “اسأل وأنت ترسم: ابدأ في جمع التعليقات في مرحلة الورقة والقلم”">​</a></h3><p>عندما ترسم للتو صفحة الدخول، وصفحة التشغيل، وصفحة النتائج على السبورة أو الورقة، فقد امتلكت بالفعل الأساس للحوار مع المستخدم. يمكنك تماماً في هذه المرحلة، البحث عن شخصين أو ثلاثة قد يصبحون مستخدمين مستهدفين، والسماح لهم بإلقاء نظرة، والاستماع إلى ردود أفعالهم الأولى.</p><p>لا تحتاج إلى إجراء مقابلات معقدة، فقط راقب بعض التفاصيل: عندما يرون صفحة الدخول، هل سيقولون تلقائياً الجملة التي تريد منهم قولها، مثل &quot;يبدو أن هذا لعمل ملخصات للنصوص الطويلة&quot;؛ عندما يكونون في صفحة التشغيل، هل سيتبعون بشكل طبيعي التسلسل الذي توقعته، مثل لصق النص أولاً، ثم اختيار طول الملخص؛ عندما يكونون في صفحة النتائج، هل تنجذب أعينهم فوراً إلى الجزء الذي تأمل أن يروه، بدلاً من التردد في الزوايا غير المهمة.</p><p>يمكن لهذه الملاحظات أن تساعدك، قبل كتابة أول سطر من الكود، في الكشف عن مشاكل التصميم الأكثر وضوحاً. يمكنك تعديل النموذج الأولي على الورق بناءً على هذه التعليقات، ثم الاستمرار في العمل، بدلاً من الانتظار حتى يتم بناء التطبيق بالكامل ثم إجراء تغييرات كبيرة على الهيكل.</p><h3 id="اسأل-وأنت-تفعل-ادعُ-الأشخاص-لتجربة-المنتج-في-مرحلة-النصف-مصنع" tabindex="-1">اسأل وأنت تفعل: ادعُ الأشخاص لتجربة المنتج في مرحلة النصف مصنع <a class="header-anchor" href="#اسأل-وأنت-تفعل-ادعُ-الأشخاص-لتجربة-المنتج-في-مرحلة-النصف-مصنع" aria-label="Permalink to “اسأل وأنت تفعل: ادعُ الأشخاص لتجربة المنتج في مرحلة النصف مصنع”">​</a></h3><p>عندما يكون لديك نسخة نصف مصنعة يمكنها تشغيل العملية الأساسية، فلا يوجد سبب إضافي لاستخدامها بمفردك في الخفاء. حتى لو كانت الواجهة بدائية جداً، وحتى لو لم تتم إضافة العديد من الميزات بعد، <strong>طالما أنها قادرة على إكمال الحد الأدنى من المهام التي حددتها، فقد امتلكت بالفعل الشروط لدعوة المستخدمين الحقيقيين لتجربتها.</strong></p><p>يمكنك البدء من الأشخاص من حولك، ويمكنك أيضاً اختيار بعض الأشخاص الأكثر استعداداً لتجربة أدوات جديدة من المستخدمين الذين تواصلت معهم من خلال أصول الجمهور والمناطق العامة المذكورة في الفصل السابق. أرسل لهم رابطاً، واشرح باختصار ما يمكن فعله الآن، ثم اطلب منهم، دون تقديم الكثير من الشروحات، الانتقال من الدخول إلى النتيجة.</p><p><strong>في هذه العملية، ما يجب عليك فعله ليس الدفاع، بل المراقبة.</strong> أين سيترددون، في أي خطوة سيتوقفون، وأي زر سينظرون إليه لفترة طويلة دون أن يجرؤوا على النقر عليه. يمكنك أيضاً طرح بعض الأسئلة المحددة لاحقاً: أي خطوة بدت الأكثر صعوبة بالنسبة لك، وأي نتيجة كانت الأكثر إرضاءً لك، وما هو الشيء الذي توقعته ولكنك لم تره في النهاية.</p><p>القيام بهذه الأشياء في مرحلة النصف مصنع له فائدة كبيرة: لم تستثمر اعتماداً عاطفياً مفرطاً في أي حل بعد، وسيكون من الأسهل عليك قبول التخلي عن بعض الميزات التي تبدو رائعة ولكن المستخدمين لا يهتمون بها على الإطلاق، وستكون أكثر استعداداً لقضاء الوقت في تحسين التفاصيل الصغيرة التي تبدو غير ملفتة ولكنها تظهر بشكل متكرر أثناء الاستخدام الفعلي.</p><h3 id="لا-تخف-من-إظهار-عدم-الاحترافية" tabindex="-1">لا تخف من إظهار عدم الاحترافية <a class="header-anchor" href="#لا-تخف-من-إظهار-عدم-الاحترافية" aria-label="Permalink to “لا تخف من إظهار عدم الاحترافية”">​</a></h3><p>السبب الذي يجعل الكثير من الناس لا يرغبون في إظهار عملهم للآخرين في مرحلة مبكرة هو الخوف من إظهار ضعفهم، معتقدين أن هذا سيجعلهم يبدون غير محترفين. ولكن على العكس من ذلك، فإن صانعي المنتجات الناضجين حقاً نادراً ما يشعرون بهذا الخجل تجاه الإصدارات المبكرة. لأنهم يعرفون أن الكشف المبكر عن المشاكل هو الأقل تكلفة.</p><p>يمكنك تبني منظور مختلف في عقلك بشأن هذا الأمر: أنت لا تعرض منتجاً غير مكتمل، بل تدعو الطرف الآخر للمشاركة في الصقل معاً. طالما توضح مسبقاً أن هذا إصدار مبكر جداً، وأنك تأمل ألا يعطي الطرف الآخر إشادة، بل مشاعر استخدام مباشرة قدر الإمكان، فإن معظم الناس سيكونون مستعدين لتقديم المساعدة، وخاصة أولئك الذين يعانون بالفعل من المشكلة التي تحاول حلها.</p><p>لقد تعلمت الآن استخدام السبورة والورق لتحويل فكرة مجردة إلى مسار مستخدم ملموس؛ وتعرف على كيفية التفكيك، لتقسيم الرغبات الكبيرة والعريضة إلى عناصر أدنى قابلة للتنفيذ يمكنك البدء بها غداً؛ وتعرف أيضاً أنه لا يجب عليك أن تكون طماعاً، وتحزم كل أفكارك في الإصدار الأول دفعة واحدة، بل تستخدم نموذج الماس المزدوج للتبديل ذهاباً وإياباً بين التباعد والتقارب، لاختيار MVP الأكثر جدارة بالبدء به أولاً؛ وتعلمت الإشارة بذكاء إلى التطبيقات الحالية، والوقوف على أكتاف الآخرين للتقدم إلى الأمام في الهياكل الأساسية مثل التنقل والنماذج وعرض النتائج؛ والأهم من ذلك، أنك تعرف عدم انتظار كل شيء حتى يكون جاهزاً للبحث عن المستخدمين، بل دعهم يدخلون بدءاً من الـ demo، واستخدام تجربتهم لمساعدتك في تصحيح الاتجاه معاً.</p><p>من خلال هذه الأدوات والخطوات، لديك الآن القدرة على تفكيك فكرة إلى تطبيق قابل للاستخدام مبدئياً. ولكنك ستلاحظ أيضاً أن هناك حجاباً يفصل بين التطبيق القابل للاستخدام، والتطبيق الجيد حقاً.</p><p>بعد ذلك، سنتحدث تحديداً عن: ما هو التطبيق الذي يمكن اعتباره تطبيقاً جيداً؛ لنجعلك تعرف، بعد الحصول على أول إصدار قابل للاستخدام، كيف تجعل تطبيقك يذهاب إلى أبعد من ذلك في الخطوة التالية.</p><h2 id="📚-assignments" tabindex="-1">📚 Assignments <a class="header-anchor" href="#📚-assignments" aria-label="Permalink to “📚 Assignments”">​</a></h2><p>يرجى إكمال الواجب التالي بناءً على المحتوى أعلاه:</p><ol><li>يرجى استخدام أي نموذج لغوي كبير (LLM)، وبالنسبة للفكرة السابقة، اطلب من AI الرجوع إلى نموذج الماس المزدوج (Double Diamond) لإعطاء نتائج متباينة، وستحتاج إلى اختيار مجموعة من الحلول الممكنة بناءً على نتائج التباين.</li><li>بناءً على الفكرة التي توصلت إليها سابقاً، استخدم طريقة التفكيك والتحديد للحصول على محتوى قابل للتنفيذ بشكل أكثر تحديداً. مشابه لـ: &quot;توفير أداة ويب للمستخدم، تتيح له رفع ملف PDF نصي لا يتجاوز 20 صفحة، والحصول في غضون 10 ثوانٍ على نص قابل للتعديل ببنية فقرات واضحة ومستويات عناوين محفوظة، مع دعم النسخ بنقرة واحدة والتنزيل كملف .txt.&quot;</li><li>بناءً على الفكرة المُفصّلة، حاول رسم تطبيقك على السبورة البيضاء. يحتاج التطبيق إلى التركيز على جزأين: كيف يجب أن يكون تصميم واجهة المستخدم (UI)، وما هي الميزات التي يجب أن تكون موجودة، وأين توجد كل ميزة.</li></ol><h1 id="_3-بعد-بنائه،-كيف-تحكم-عليه-وتصقله-ليصبح-تطبيقاً-جيداً" tabindex="-1">3. بعد بنائه، كيف تحكم عليه وتصقله ليصبح تطبيقاً جيداً <a class="header-anchor" href="#_3-بعد-بنائه،-كيف-تحكم-عليه-وتصقله-ليصبح-تطبيقاً-جيداً" aria-label="Permalink to “3. بعد بنائه، كيف تحكم عليه وتصقله ليصبح تطبيقاً جيداً”">​</a></h1><p>عندما تُنجز أخيراً النسخة الأولى وتضعها في العالم الحقيقي ليستخدمها الناس، ستدخل مرحلة مختلفة تماماً. كل النقاشات السابقة كانت لا تزال في مستوى الأفكار والتصميم، والآن، سيخضع المنتج لأول مرة لاختبار سيناريوهات الاستخدام الحقيقية. سترى الأماكن التي ينقر فيها المستخدمون بشكل خاطئ، والأماكن التي يترددون فيها، والأماكن التي يتوقفون فيها عن الحركة، وسترى أيضاً في أي الخطوات يسير الأمور بسلاسة مذهلة، وحتى يقضون بضع ثوانٍ إضافية بشكل غير متوقع في زاوية ما. هذه التفاصيل أكثر صدقاً بكثير من كل ما تتخيله في ذهنك حول المنتج.</p><p>ما تسعى هذه المقالة لحله هو مشكلة جوهرية: عندما يتم بناء التطبيق بالفعل، وحتى عندما يكون هناك مجموعة من المستخدمين الأوائل يستخدمونه، كيف تحكم إلى أي مدى يبعد عن كونه تطبيقاً جيداً، وكيف تستفيد من هذه المعلومات من عملية الاستخدام الحقيقية لتحسينه وصقله خطوة بخطوة.</p><h2 id="_3-1-ما-هو-التطبيق-الجيد-4-خصائص-أساسية" tabindex="-1">3.1 ما هو التطبيق الجيد: 4 خصائص أساسية <a class="header-anchor" href="#_3-1-ما-هو-التطبيق-الجيد-4-خصائص-أساسية" aria-label="Permalink to “3.1 ما هو التطبيق الجيد: 4 خصائص أساسية”">​</a></h2><p>للحكم على ما إذا كان التطبيق جيداً أم لا، لا يمكنك الاعتماد فقط على مدى حبك له، ولا على عدد التنزيلات أو أيام الاستخدام القليلة، بل يجب أن تنظر إلى ما إذا كان يمتلك بعض الخصائص الأساسية والثابتة. ببساطة، يمكنك الرجوع إلى الخصائص التالية:</p><h3 id="التطبيق-الجيد-يقدم-قيمة-ملموسة" tabindex="-1">التطبيق الجيد يقدم قيمة ملموسة <a class="header-anchor" href="#التطبيق-الجيد-يقدم-قيمة-ملموسة" aria-label="Permalink to “التطبيق الجيد يقدم قيمة ملموسة”">​</a></h3><p>الخاصية الأكثر مباشرة للتطبيق الجيد هي أنه يمكنه أن يمنح الناس فائدة حقيقية في سيناريو معين. لا يجب أن تكون هذه الفائدة عظيمة، ولا تحتاج إلى أن تغلف بلغة معقدة، ولكن يجب أن تكون محددة لدرجة يمكنك شرحها بوضوح: <strong>ما الذي ساعد المستخدم بالتخلي عن فعله، وكم من الوقت وفّره، أو ما الذي جعله أقل عرضة للأخطاء.</strong></p><p><img src="'+D+'" alt=""></p><p>على سبيل المثال، أداة بسيطة لمحاضر الاجتماعات، إذا كان بإمكانها بمجرد رفع تسجيل صوتي أو التسجيل المباشر أثناء الاجتماع، أن تقوم تلقائياً بإنشاء محضر اجتماع منظم، وتوضيح المهام والأشخاص المسؤولين والمواعيد النهائية في قائمة، فإن ما توفره للمستخدم ليس مجرد وقت الكتابة، بل الجهد المبذول في العملية بأكملها من التسجيل، والتنظيم، والفرز، إلى التنسيق والإخراج. يمكنك القول بوضوح أن هذه الأداة توفر حوالي عشرين دقيقة لكل شخص في كل اجتماع. وإذا كان الفريق بأكمله لديه عشرة من هذه الاجتماعات أسبوعياً، فإن إجمالي الوقت الموفر سيكون كبيراً جداً.</p><p>خذ مثالاً آخر، أداة ضغط صور تبدو غير ملفتة للانتباه، إذا كان بإمكانها، مع الحفاظ على جودة لا تكاد تُلاحظ بالعين المجردة، ضغط حجم مجموعة من الصور إلى ثلث الحجم الأصلي، مع ضمان التصدير بنقرة واحدة، وعدم الفوضى في بنية المجلدات، وتوحيد قواعد التسمية، فإن القيمة التي تجلبها ليست فقط توفير مساحة على القرص الصلب، بل أيضاً النقل الأسرع، والرفع الأسلس، وعدد أقل من الأخطاء عند الربط مع الأنظمة الأخرى. هذه القيمة الملموسة التي تبدو عادية غالباً ما تكون أكثر موثوقية من عبارة غامضة مثل &quot;تحسين الكفاءة&quot;.</p><p>لذلك، عندما تقول إن تطبيقك ذو قيمة، من الأفضل أن تقسم هذه القيمة إلى سيناريو أو سيناريوهين محددين، وتشرح بلغة يفهمها الشخص العادي: تطبيقك يجعل الأمر الذي كان المستخدم يحتاج إلى قضاء وقت طويل فيه، والقيام بالكثير من العمل اليدوي، وتحمل مخاطر كبيرة، أمراً أسهل وأقل جهدًا.</p><h3 id="سهولة-الاستخدام،-يمكن-فهمه-تقريباً-دون-النظر-إلى-التعليمات" tabindex="-1">سهولة الاستخدام، يمكن فهمه تقريباً دون النظر إلى التعليمات <a class="header-anchor" href="#سهولة-الاستخدام،-يمكن-فهمه-تقريباً-دون-النظر-إلى-التعليمات" aria-label="Permalink to “سهولة الاستخدام، يمكن فهمه تقريباً دون النظر إلى التعليمات”">​</a></h3><p>خاصية أخرى يسهل التقليل من شأنها لكنها مهمة للغاية، وهي أن <strong>التطبيق الجيد عادة لا يحتاج إلى الكثير من الشرح</strong>. عندما يفتح المستخدم التطبيق لأول مرة، يمكنه الاعتماد على الحدس لمعرفة من أين يبدأ تقريباً، وماذا سيحدث عند النقر على شيء ما، فالزر الأكبر عادة ما يقوم بالأمر الأكثر أهمية، وأهم المداخل توضع في مواقع مهمة حقاً، بدلاً من إخفائها في الطبقة الثالثة من القائمة.</p><p><img src="'+S+'" alt=""></p><p>يمكنك تخيل مستخدم جديد قام للتو بتنزيل تطبيقك، ربما فتحه عشوائياً أثناء الوقوف في طابور، أو في السيارة، أو في مقهى. قد لا تكون إشارة الشبكة جيدة جداً في ذلك الوقت، وليس لديه الصبر لقراءة أي تعليمات طويلة. غالباً ما يكون الوقت الذي يتحمله في حالة الارتباك بضع ثوانٍ فقط. إذا لم يرَ أي إرشادات واضحة خلال هذه الثوانِ، ولم يعرف ماذا يفعل في الخطوة التالية، فمن السهل عليه الإغلاق مباشرة وعدم العودة أبداً.</p><p>لذلك، عندما تشعر بأن منطق المنتج سلس جداً، من الأفضل أن تجد شخصاً لم يرَ تطبيقك من قبل، واطلب منه استكشافه من الصفر دون أن تتحدث. راقب فقط أين سيتوقف، وأين سيتردد، ومتى سيظهر على وجهه تعبير &quot;ما هذا؟&quot;. إذا تم إعاقة المستخدم بمجرد دخوله بواسطة نوافذ منبثقة مفتوحة، وخيارات معقدة، وربط حسابات، فمن الصعب عليه أن يختبر حقاً القيمة التي تسعى لتقديمها.</p><p><strong>سهولة الاستخدام، في جوهرها، هي نوع من احترام التكلفة المفروضة على المستخدم.</strong> أنت تعترف بأمر واحد: لا أحد ملزم بقضاء الوقت في دراسة تطبيقك.</p><h3 id="في-السيناريوهات-عالية-التكرار-أو-الحرجة،-سيتذكرونك-بشكل-طبيعي" tabindex="-1">في السيناريوهات عالية التكرار أو الحرجة، سيتذكرونك بشكل طبيعي <a class="header-anchor" href="#في-السيناريوهات-عالية-التكرار-أو-الحرجة،-سيتذكرونك-بشكل-طبيعي" aria-label="Permalink to “في السيناريوهات عالية التكرار أو الحرجة، سيتذكرونك بشكل طبيعي”">​</a></h3><p>غالباً ما يمتلك التطبيق الجيد إيقاع استخدام مستقر، إما عالي التكرار أو حاسم. <strong>المقصود بالتكرار العالي هو أنه أصبح جزءاً من روتين المستخدم اليومي، مثل تطبيق المراسلة الذي يُفتح عدة مرات يومياً</strong>، أو أداة التنقل التي تُستخدم يومياً عند الذهاب والعودة من العمل، أو تطبيق تسجيل الحضور الذي يُسجل يومياً. أما الحاسم فيعني أنه حتى لو لم يُستخدم يومياً، فإن المستخدم سيتذكرك فوراً بمجرد مواجهة نوع معين من السيناريوهات، مثل أداة الإقرارات الضريبية، أو حاسبة ميزانية الديكور، أو أداة إدارة أسئلة المقابلات، أو مساعد قائمة مستندات التأشيرة.</p><p>يمكنك أن تسأل نفسك بعض الأسئلة: متى وفي أي ظروف سيستخدم المستخدم تطبيقك حقاً؛ إذا فاته تطبيقك، هل سيشعر حقاً بعدم الراحة؛ في نفس السيناريو، كيف يدير الأمر حالياً. إذا كان هناك بديل، حتى لو كان مزعجاً، لكنه اعتاد عليه، فإن ما عليك فعله ليس فقط مساواة الميزات، بل جعله يشعر أن الانتقال إلى تطبيقك يستحق العناء حقاً.</p><p>من المفاهيم الخاطئة الشائعة ربط تكرار الاستخدام مباشرة بجودة التطبيق. في الواقع، ليس ضرورياً. على سبيل المثال، إعداد تقرير نهاية العام، أو استخراج نوع معين من الشهادات، أو إجراء تحويل مالي كبير، هذه الأشياء في حد ذاتها ليست متكررة، ولكن بمجرد حدوثها، فهي من أهم الأشياء للمستخدم في تلك اللحظة. <strong>إذا كان تطبيقك يمكنه التعامل مع هذا النوع من السيناريوهات الحرجة بشكل مستقر وسريع ويمنح المستخدم شعوراً بالثقة، فإنه يمكن أيضاً أن يُسمى تطبيقاً جيداً.</strong></p><p><strong>ما يجب التحذير منه حقاً هو التطبيق الذي لا يستخدمه المستخدم بشكل متكرر، ولن يتذكرك طوعياً في أي لحظة حرجة</strong>، وحتى إذا اختفى تطبيقك من هاتفه، فلن يتذكره بشكل غامض إلا بعد بضعة أشهر عند تنظيف الذاكرة. هذا الموقف غالباً ما يشير إلى أن تطبيقك لم يرتبط بأي سيناريو حقيقي بعمق، بل مجرد تراكم لبعض الأشياء ضعيفة التأثير على مستوى الميزات.</p><h3 id="روح-الإيثار-التفاني-في-خدمة-الغير" tabindex="-1">روح الإيثار (التفاني في خدمة الغير) <a class="header-anchor" href="#روح-الإيثار-التفاني-في-خدمة-الغير" aria-label="Permalink to “روح الإيثار (التفاني في خدمة الغير)”">​</a></h3><p>عندما يبدأ الكثير من الناس في صنع المنتجات، فإنهم يفكرون في عدة أشياء في نفس الوقت: كيفية فرض الرسوم بعد الإطلاق، وكيفية رفع الأسعار، وكيفية جعل المستخدم يدفع بمجرد استخدامه أكثر قليلاً، وكيفية قفل البيانات لمنع المستخدم من المغادرة. الحسابات التجارية في حد ذاتها ليست مشكلة، ولكن إذا كان التفكير من البداية يدور بالكامل حول هذه الأمور، فمن السهل أن تصنع تطبيقاً يثير حذر المستخدم بمجرد النظر إليه: يطلب جميع أنواع الأذونات بمجرد فتحه، ونقاط الدفع في كل مكان، وتصميم الميزات ليس لجعل المستخدم ينجز المهمة بسلاسة، بل للتفكير في كيفية توجيه المستخدم إلى زر الدفع.</p><p>في المقابل، التطبيقات الجيدة حقاً تحمل نوعاً من روح الإيثار البسيطة. إنها بالتأكيد ستوضح كيف ستبقى على قيد الحياة، وستقوم بإعداد طرق دفع معقولة، ولكن عند تصميم المسارات والتجربة، فإن الأولوية تكون دائماً: <strong>كيف تجعل من الأسهل على المستخدم إكمال هذا الأمر بسلاسة، بدلاً من كيفية إضافة خطوة أخرى لخلق عقبات إضافية.</strong> سترى أنها تستخدم طرقاً أكثر ملاءمة للمستخدم في العديد من الأماكن، مثل تقديم مطالبات واضحة في الخطوات الرئيسية، وعدم تعيين حواجز مفرطة عند التصدير والترحيل، والسماح لك بتجربة جزء من القيمة الحقيقية قبل الدفع.</p><p>غالباً ما تتجلى روح الإيثار هذه في بعض تفاصيل التصميم الدقيقة. على سبيل المثال، حقول النموذج لن تطلب الكثير من البيانات غير ذات الصلة بالمهمة فقط لجمع معلومات أكثر، وتسلسل البرامج التعليمية مصمم حول الأهداف التي يريد المستخدم إنجازها، بدلاً من الشرح حول وحدات الميزات نفسها. يمكنك أن تشعر أن هذا التطبيق يساعدك بجدية في إنجاز أمر ما، بدلاً من معاملتك ككائن يتم استغلاله.</p><p>هناك نقطة مهمة أخرى: <strong>التطبيق الجيد ليس بالضرورة تطبيقاً كبيراً. يمكن أن يكون صغيراً جداً، يخدم فقط فئة معينة من الناس، أو سيناريو معيناً، أو مهمة معينة</strong>، ولكنه يقدم أداءً رائعاً في تلك المساحة الصغيرة. مثل التطبيق المخصص لمساعدة المصممين على تصدير مسوداتهم إلى التنسيقات التي تتطلبها المطابع، أو التطبيق المخصص لمساعدة العاملين المستقلين على تنظيم معرض حالات مشاريعهم الشخصية، كل هذه النطاقات ليست كبيرة، ولكن القيمة الموجودة بداخلها ليست صغيرة على الإطلاق.</p><h2 id="_3-2-البصيرة-في-الاحتياجات-نظرية-هرم-الاحتياجات-لماسلو" tabindex="-1">3.2 البصيرة في الاحتياجات: <strong>نظرية هرم الاحتياجات لماسلو</strong> <a class="header-anchor" href="#_3-2-البصيرة-في-الاحتياجات-نظرية-هرم-الاحتياجات-لماسلو" aria-label="Permalink to “3.2 البصيرة في الاحتياجات: نظرية هرم الاحتياجات لماسلو”">​</a></h2><p><img src="'+T+'" alt=""></p><p>قبل صنع التطبيق، يقفز الكثير من الناس مباشرة إلى التفكير على مستوى الميزات: هل يمكننا إضافة شيء هنا، وهل نضيف زراً هناك. لكن ما يحدد حقاً ما إذا كان التطبيق يمكنه البقاء على قيد الحياة هو مستوى الاحتياجات البشرية الذي تلامسه، ومدى دقته في ذلك.</p><p>السبب الذي يجعل نظرية هرم الاحتياجات لماسلو تُذكر مراراً وتكراراً في العديد من المجالات ليس لأنها صارمة للغاية، بل لأنها توفر إطار عمل عملياً بما فيه الكفاية. لا تحتاج إلى معاملتها كاستنتاج نفسي صارم، فقط استخدمها كإطار عمل بسيط: يساعدك في تعليق دوافع المستخدمين المختلفة على عدة مستويات واضحة نسبياً، مما يسهل عليك الحكم على الاحتياجات التي يلبيها تطبيقك، وكلما لبيت احتياجات أكثر، كان تطبيقك أفضل.</p><p>تنقسم نظرية هرم الاحتياجات لماسلو عادة إلى خمس طبقات، من الأسفل إلى الأعلى وهي: الاحتياجات الفسيولوجية، واحتياجات الأمان، والانتماء والحب، واحتياجات التقدير، وتحقيق الذات.</p><h3 id="الاحتياجات-المتعلقة-بالفسيولوجيا-والبقاء" tabindex="-1">الاحتياجات المتعلقة بالفسيولوجيا والبقاء <a class="header-anchor" href="#الاحتياجات-المتعلقة-بالفسيولوجيا-والبقاء" aria-label="Permalink to “الاحتياجات المتعلقة بالفسيولوجيا والبقاء”">​</a></h3><p>هذه الطبقة هي الأكثر أساسية، وتتعلق مباشرة بالأكل، والنوم، وحالة البقاء نفسها. يبدو الأمر وكأنه بعيد بعض الشيء عن منتجات الإنترنت، ولكن في الواقع العديد من التطبيقات تلعب دوراً على هذا المستوى.</p><p>على سبيل المثال، طلب الطعام، وشراء البقالة، وخدمات التوصيل، وحجز الغرف، وطلب سيارات الأجرة، هذه الخدمات المنزلية والتنقل النموذجية هي في جوهرها تساعد المستخدمين على حل المشاكل الأساسية مثل الأكل، والخروج، والراحة بتكلفة زمنية أقل. ومثال آخر، سجلات اللياقة البدنية، ومراقبة النوم، وتسجيل النظام الغذائي، على الرغم من أنها تبدو أقرب إلى إدارة الصحة، إلا أنه بالنسبة للكثير من الناس، فهي محاولة للحفاظ على حالة جسدية لا تخرج عن السيطرة، ويمكن أيضاً اعتبار هذا امتداداً للمستوى الفسيولوجي والبقاء.</p><p>إذا كان تطبيقك يعمل على هذا المستوى، فهناك خاصية واحدة وهي: <strong>سيكون المستخدمون حساسين جداً للاستقرار، والموثوقية، والقدرة على التنبؤ</strong>. عدم التمكن من توصيل الطعام المطلوب، أو عدم القدرة على طلب سيارة أجرة، أو خطأ في معلومات حجز الغرفة، ستجلب ردود فعل عاطفية قوية جداً، لأن هذه المشاكل تعطل الإيقاع الأساسي للحياة مباشرة.</p><h3 id="احتياجات-الأمان-واليقين" tabindex="-1">احتياجات الأمان واليقين <a class="header-anchor" href="#احتياجات-الأمان-واليقين" aria-label="Permalink to “احتياجات الأمان واليقين”">​</a></h3><p>تشمل احتياجات الأمان السلامة على المستوى المادي، وتشمل أيضاً الأمان الاقتصادي، والمعلوماتي، والنفسي. العديد من التطبيقات ذات الطابع الأدواتي تعمل في الواقع بشكل أساسي على مستوى الأمان هذا. على سبيل المثال: محاسبة الأموال، إدارة الأصول، مساعدو التأمين، أدوات قوالب العقود، مديرو كلمات المرور، أدوات النسخ الاحتياطي، أدوات حماية الخصوصية، مزامنة التخزين السحابي، واستعادة البيانات. الوعد الأساسي لهذه التطبيقات غالبًا ما يكون: مساعدتك في تقليل احتمالية الخطأ، وتوفير خطة بديلة عندما تسوء الأمور، أو على الأقل منحك شعورًا بالاطمئنان.</p><p>فئة نموذجية من هذه التطبيات هي الأدوات الصغيرة المختلفة لمنع الفقدان، ومنع النسيان، ومنع الخطأ: تذكيرات الجدول الزمني، تذكيرات تناول الأدوية، تذكيرات انتهاء صلاحية المستندات الهامة، والملاحظات في النقاط الحرجة. حتى لو ذكرتك هذه التطبيقات بضع مرات فقط في اليوم، طالما أنقذتك مرة أو مرتين في اللحظات الحاسمة، فستصنفها بسرعة كأدوات يجب الاحتفاظ بها.</p><p>عند تصميم هذا النوع من المنتجات، يمكنك أن تسأل نفسك سؤالًا إضافيًا: <strong>ما هو نوع المخاطر الذي تساعد المستخدمين بالفعل على تقليله؟ هل هي مخاطر مالية، أو متعلقة بالوقت، أو بالعلاقات،</strong> أم متعلقة بالامتثال والقانون. إذا لم تتمكن حتى أنت من توضيح ذلك، فسيجد المستخدمون صعوبة بالغة في الوثوق بك حقًا.</p><h3 id="الشعور-بالانتماء،-والتواصل،-والرؤية" tabindex="-1">الشعور بالانتماء، والتواصل، والرؤية <a class="header-anchor" href="#الشعور-بالانتماء،-والتواصل،-والرؤية" aria-label="Permalink to “الشعور بالانتماء، والتواصل، والرؤية”">​</a></h3><p>عند الصعود مستوى واحد أعلى، نصل إلى احتياجات الانتماء والحب. ببساطة، إنها الرغبة في ألا أكون وحيدًا، وأريد أن أرتبط بأشخاص معينين. هذا المستوى هو المعقل الرئيسي للتطبيقات الاجتماعية، وتطبيقات المجتمعات، ومجموعات الاهتمامات المشتركة.</p><p>دائرة الأصدقاء، الدردشات الجماعية، منتديات الاهتمامات، مجتمعات الهواة، نوادي القراءة عبر الإنترنت، النقابات في الألعاب، وحتى بعض الأدوات المبنية حول هويات محددة، مثل مجموعات الآباء الجدد، التعاون المتبادل بين الطلاب الدوليين، ومنصات الشكوى المجهولة داخل الصناعة، كلها توفر في جوهرها نوعًا من الشعور بالانتماء: هناك مجموعة من الأشخاص مشابهين لي، نناقش مواضيع مشابهة، ونشكو من صعوبات مشابهة، ونشارك تجارب مشابهة.</p><p>بعض الأدوات تبدو ظاهريًا كتطبيقات وظيفية، لكن ما يحافظ على المستخدمين حقًا هو غالبًا هذا المستوى من الاحتياجات. على سبيل المثال، مشاركة الجميع لتقدم ادخارهم في تطبيقات المحاسبة، لوحات المتصدرين ودوائر تسجيل الحضور في تطبيقات الجري، ومجموعات الإشراف المتبادل في تطبيقات التعلم. هذه الوحدات الاجتماعية التي تبدو كقيمة مضافة، تربط في الواقع المستخدم بتطبيقك من خلال هويتك كجزء من مجموعة معينة.</p><p>إذا كان تطبيقك يحاول الوقوف على هذا المستوى، فلن يكون المحتوى وحده كافيًا، بل يجب أن تفكر في: <strong>لماذا يجب أن يشعر المستخدم أن الأشخاص هنا هم من نوعه، وهل هو مستعد لترك أثر هنا، والتفاعل بشكل طفيف ولكن حقيقي مع الآخرين</strong>. بخلاف ذلك، فإن ما تبنيه هو مجرد أداة بث أحادية الاتجاه.</p><h3 id="الاحترام،-وتقدير-الذات،-والشعور-بالإنجاز" tabindex="-1">الاحترام، وتقدير الذات، والشعور بالإنجاز <a class="header-anchor" href="#الاحترام،-وتقدير-الذات،-والشعور-بالإنجاز" aria-label="Permalink to “الاحترام، وتقدير الذات، والشعور بالإنجاز”">​</a></h3><p>عند الصعود مستوى واحد أعلى، نصل إلى احتياجات الاحترام وتقدير الذات. فالإنسان لا يريد فقط أن يُقبل، بل يبدأ في مرحلة ما بالاهتمام بما إذا كان يُعتبر شخصًا جيدًا هنا، وهل تمت رؤيته وتقديره، وهل هناك من يعرف ما أنجزه.</p><p>كمية كبيرة من ميزات تسجيل الحضور، والشارات، ولوحات المتصدرين، والألقاب، وأنظمة الإنجاز، تعمل في الواقع على هذا المستوى. في تطبيقات التعلم، إكمال عدد معين من الدورات يمنحك لقبًا، وفي تطبيقات الرياضة، تحقيق الهدف يمنحك شهادة، وتمنح منصات الإبداع مؤلفيها هويات بمستويات مختلفة، ويكون هناك تمييز واضح للمؤلفين ذوي المحتوى عالي الجودة في المجتمعات.</p><p>هنا من السهل الوقوع في سوء فهم: الاعتقاد بأن إضافة مجموعة من الشارات والنقاط والألقاب ستشجع المستخدمين. ما يريده المستخدمون ليس زخرفات مبالغًا فيها، بل أن يتم تسجيل جهودهم الحقيقية وأخذها على محمل الجد. إذا كان نظام الإنجاز الذي صممته منفصلاً تمامًا عن الاستثمار الحقيقي للمستخدم، مثل الحصول على لقب &quot;خبير&quot; بمجرد النقر بضع مرات، فإن هذا التحفيز سيفشل بسرعة، وقد يجعله يبدو رخيصًا.</p><p>لذلك على هذا المستوى، المفتاح ليس ما إذا كنت قد بنيت نظام تحفيز أم لا، بل يكمن في: <strong>هل وفر تطبيقك للمستخدم منصة يمكنه التراكم عليها، بحيث يمكنه أن يرى بوضوح تطوره من مبتدئ إلى مستخدم ماهر</strong>، وفي النقاط الحاسمة، منحه شعورًا طقوسيًا بأن هذه الخطوة تستحق أن تُسجل.</p><h3 id="تحقيق-الذات-وتجاوزها" tabindex="-1">تحقيق الذات وتجاوزها <a class="header-anchor" href="#تحقيق-الذات-وتجاوزها" aria-label="Permalink to “تحقيق الذات وتجاوزها”">​</a></h3><p>المستوى الأعلى من الهرم يشير إلى الشخص الذي أريد أن أكونه، وكيف أريد المساهمة بجزء من ذاتي. يبدو هذا مجردًا، لكن في السيناريوهات المحددة، غالبًا ما يكون له تعبيرات عملية للغاية.</p><p>على سبيل المثال، أدوات الإبداع: الكتابة، الرسم، إنتاج الموسيقى، تحرير الفيديو، وإدارة مشاريع البرمجة، تبدو ظاهريًا أنها توفر قدرات تقنية، لكنها تلبي في الخلفية رغبة المستخدم في خلق شيء ينتمي إليه. ومثال آخر، منصات التعلم طويلة المدى، وأدوات التخطيط المهني، وأدوات بناء العادات، فهي لا تخدم مهارة واحدة فحسب، بل تخدم هدفًا أطول أمدًا للنمو الذاتي.</p><p>هناك أيضًا رغبة في جعل الآخرين أفضل. الكثير من الأشخاص يستخدمون منصات مشاركة المعرفة، ومجتمعات الأسئلة والأجوبة، وتطبيقات العمل الخيري، وأدوات الإبداع التعاوني، ليس فقط لكسب بعض النقاط أو الزيارات، بل لأن مساعدة الآخرين ودفع مشروع إلى الأمام يمنحهم شعورًا بأنهم يفعلون شيئًا ذا معنى، وهذا أيضًا جزء من تحقيق الذات.</p><p>عندما يلمس تطبيقك هذا المستوى حقًا، فغالبًا ما سيتمتع بدرجة عالية جدًا من الاحتفاظ بالمستخدمين: حتى لو لم تكن واجهته الأجمل، ووظائفه ليست الأكثر اكتمالًا، سيبقى المستخدمون هنا، لأن <strong>هذا التطبيق قد أسس اتصالاً أعمق مع من أكون، وماذا أفعل</strong>.</p><p>أحد فوائد استخدام هرم ماسلو كمنظور للمنتج هو أنه يساعدك على تجنب انحيازين شائعين.</p><p><strong>الانحياز الأول، هو التركيز فقط على مستوى خاطئ.</strong> على سبيل المثال، إذا كنت تبني أداة لمساعدة المستخدمين على تخزين الملفات بأمان، فأنت تقف في جوهرك على مستوى الأمان، لكنك تقلد بلا هوادة المنتجات الاجتماعية، وتكدس واجهتك بميزات الإعجاب والتعليقات ولوحات المتصدرين، والنتيجة هي أنك لن تستحوذ على عقول المستخدمين من المنتجات الاجتماعية، بل ستجعل من يريدون ببساطة أداة تخزين موثوقة يشعرون بأنك لا تؤدي دورك كما ينبغي.</p><p><strong>الانحياز الثاني، هو تجاهل العلاقة التسلسلية بين المستويات.</strong> عندما لا يحصل الشخص حتى على تجربة استخدام مستقرة كأساس، فمن الصعب عليه أن يسعى لتحقيق ذاته لديك بجدية. على سبيل المثال، إذا كان التطبيق يتعطل بشكل متكرر، وتضيع البيانات بين الحين والآخر، فحتى لو منحته الكثير من الشارات ومنحنى النمو، فلن يستثمر المستخدم بصدق. على العكس من ذلك، إذا كنت متقنًا في المستويات الأساسية، ثم تضيف تدريجيًا قيم المستويات الأعلى، سيجد المستخدمون أنه من الأسهل تسلق السلم معك.</p><p>في التصميم العملي، يمكنك التحقق الذاتي على النحو التالي:</p><ul><li>اسأل نفسك أولاً: ما هو المستوى الأهم والأكثر جوهرية من الاحتياجات الذي يلبيه تطبيقي، يُسمح باختيار مستوى واحد فقط</li><li>ثم اسأل: فوق هذا المستوى الأساسي، هل لدي فرصة للامتداد بشكل طبيعي إلى المستوى الأعلى، بدلاً من إلصاق مفهوم بشكل مصطنع</li><li>أخيرًا، انظر: في المستويات الأدنى من مستواك المستهدف، هل لديك نقاط ضعف واضحة، أو حتى تعيق المستخدمين</li></ul><p>عندما تتمكن من الإجابة بوضوح على هذه الأسئلة، فإن فهمك لما يريده المستخدمون حقًا لن يقتصر فقط على الشعور الضبابي بأنهم قد يعجبون به، مما يساعدك على بناء تطبيقات أفضل.</p><h2 id="_3-3-التصنيف-حسب-نوع-المستخدم-الفروق-بين-تطبيقات-c-end-وتطبيقات-b-end" tabindex="-1">3.3 التصنيف حسب نوع المستخدم: الفروق بين تطبيقات C-end وتطبيقات B-end <a class="header-anchor" href="#_3-3-التصنيف-حسب-نوع-المستخدم-الفروق-بين-تطبيقات-c-end-وتطبيقات-b-end" aria-label="Permalink to “3.3 التصنيف حسب نوع المستخدم: الفروق بين تطبيقات C-end وتطبيقات B-end”">​</a></h2><p>بعد إطلاق التطبيق، ستكتشف بسرعة أمرًا مهمًا آخر: التعامل مع المستخدمين الأفراد العاديين يختلف تمامًا عن التعامل مع المستخدمين من الشركات أو المؤسسات، فهما قواعد لعبة مختلفة تمامًا. يبدو كلاهما أنهما يُسميان &quot;مستخدمين&quot;، لكن اهتماماتهما الرئيسية مختلفة تمامًا.</p><ul><li>C-end (Consumer End): يشير إلى &quot;جهة المستهلك&quot;، وجوهره هو المستخدم الفردي العادي. على سبيل المثال، التطبيقات التي نستخدمها يوميًا مثل WeChat، وDouyin، وMeituan Waimai، مستخدمو هذه التطبيقات هم أفراد مستقلون، وهذا النوع من السيناريوهات التي تقدم خدمات للأفراد يُسمى أعمال C-end.</li><li>B-end (Business End): يشير إلى &quot;جهة المؤسسة&quot;، وجوهره هو المستخدمون من الشركات أو المؤسسات أو المنظمات. على سبيل المثال، تطبيقات مثل DingTalk (أدوات التعاون المؤسسي) المستخدمة في الشركات، وبرامج المالية (مثل Yonyou، وKingdee)، وأنظمة نقاط البيع في متاجر التجزئة، مستخدمو هذه المنتجات هم موظفو الشركات أو الفرق أو المؤسسة بأكملها، وتخدم احتياجات التشغيل والإدارة والإنتاج الخاصة بالشركات، وهذا النوع من السيناريوهات التي تقدم خدمات للمنظمات يُسمى أعمال B-end.</li></ul><h3 id="تطبيقات-c-end-موجهة-لحياة-الأفراد-العاديين،-ومشاعرهم،-وعاداتهم" tabindex="-1">تطبيقات C-end: موجهة لحياة الأفراد العاديين، ومشاعرهم، وعاداتهم <a class="header-anchor" href="#تطبيقات-c-end-موجهة-لحياة-الأفراد-العاديين،-ومشاعرهم،-وعاداتهم" aria-label="Permalink to “تطبيقات C-end: موجهة لحياة الأفراد العاديين، ومشاعرهم، وعاداتهم”">​</a></h3><p>تطبيقات C-end موجهة للمستخدمين الأفراد، وهي مدمجة في الحياة اليومية لكل شخص. تشمل الأنواع الشائعة تطبيقات المحتوى، والأدوات، والترفيه، والتواصل الاجتماعي، والتعلم، وغيرها.</p><p><img src="'+w+'" alt=""></p><p>تطبيقات المحتوى، مثل قراءة الأخبار، ومنصات الفيديو القصير، وأدوات البودكاست. مهمتها الأساسية عادةً هي السماح للمستخدمين بتصفية المعلومات التي تهمهم من بين كميات هائلة في وقت محدود. وفي الوقت نفسه، يجب ضمان وجود أشياء جديدة باستمرار لجذب المستخدمين للعودة.</p><p>تطبيقات الأدوات، مثل المحاسبة، وقوائم المهام، وإدارة الملفات، والجدولة. غالبًا ما توفر هذه التطبيقات حلاً أسهل استخدامًا من الطرق التقليدية في مهمة محددة، وتعتبر جزءًا من البنية التحتية التي يستخدمها المستخدمون يوميًا.</p><p>تطبيقات الترفيه، بما في ذلك الألعاب، والتفاعلات الخفيفة، والأدوات الممتعة. ما توفره للمستخدمين هو الاسترخاء والبهجة العاطفية، ومعيار قياس مدى جودة استخدامها يعتمد بشكل أكبر على ما إذا كان المستخدمون على استعداد لقضاء الوقت فيها باستمرار.</p><p>تطبيقات التواصل الاجتماعي تدور حول التواصل والتفاعل بين الأشخاص، بينما تركز تطبيقات التعلم على تحسين قدرات معينة، مثل حفظ الكلمات، وحل الأسئلة، وتسجيل الحضور للقراءة، وإدارة الدورات.</p><p>على الرغم من أن هذه التطبيقات تختلف في أنواعها، إلا أنها تشترك في عدة نقاط تركيز مشتركة.</p><p><strong>أولاً، نمو المستخدمين.</strong> وهو كيفية جعل المزيد من الأشخاص يجربون تطبيقك لأول مرة. يتضمن ذلك القنوات، ونصوص الترويج، وتحفيز المستخدمين، ولكن الشرط المسبق هو دائمًا: يجب أن يكون لديك أولاً سيناريو استخدام واضح بما فيه الكفاية. بخلاف ذلك، فإن أساليب النمو الأقوى لن تجلب سوى موجة قصيرة الأجل من الفضول.</p><p><strong>ثانيًا، الاحتفاظ والعودة.</strong> ليس الأمر يتعلق فقط بزيارة شخص ما، بل بمدى استعداده للبقاء والعودة. تطبيق المحتوى، إذا لم يتمكن من ضمان إنتاج محتوى يهم المستخدمين باستمرار، سيتم استبداله بسرعة؛ وتطبيق الأدوات، إذا لم يساعد المستخدمين حقًا في إكمال مهامهم في الاستخدامات الحرجة القليلة، سيجد صعوبة في بناء عادات استخدام طويلة الأمد. يمكنك مراقبة معدلات الاحتفاظ في اليوم الأول، واليوم السابع، واليوم الثلاثين لتحديد عدد الأشخاص الذين أدخلوك حقًا في روتين حياتهم.</p><p><strong>ثالثًا، التحويل والدفع.</strong> لماذا يرغب المستخدمون في الدفع، لا يكون ذلك عادةً لأنك جعلت النسخة المجانية سيئة، بل لأنهم بعد الحصول على جزء من القيمة منك، يرون أن الميزات المدفوعة يمكن أن تجلب مستوى أعلى من الراحة. مثل حصص استخدام أعلى، وقدرات تعاون أقوى، وقوالب أكثر احترافية، وأداء أكثر استقرارًا.</p><p><strong>رابعًا، قابلية المشاركة والانتشار.</strong> العديد من منتجات C-end قادرة على الانتشار بسرعة لأنها تحمل بطبيعتها خصائص المشاركة أثناء الاستخدام. على سبيل المثال، إنشاء صورة، أو مقطع فيديو، أو نص، فمن أجل تحقيق هدفه، يحتاج المستخدم في حد ذاته إلى إرسال النتيجة إلى الآخرين. في هذه العملية، طالما قمت بجعل العلامة التجارية تظهر بشكل طبيعي وغير مزعج، يمكنك الحصول على نوع من التسويق الشفهي. إحدى الطرق البسيطة للحكم على ما إذا كان الطلب الحقيقي في تطبيقات C-end (المستهلك) موجودًا، هي معرفة ما إذا كان المستخدمون على استعداد لتطوير عادات صغيرة حوله. على سبيل المثال، الاستعداد لفتحه وإلقاء نظرة عليه يوميًا، وربطه بإيقاع حياتهم، والسماح له بالمشاركة في توثيق بعض اللحظات المهمة. على العكس من ذلك، إذا كان المستخدمون يدخلون فقط بسبب حدث أو إعلان، ويغادرون بعد الاستخدام لمرة واحدة، ولا يعودون تقريبًا، فيمكن الحكم بشكل أساسي أن ما حللته ربما كان مجرد فضولهم المؤقت، وليس احتياجًا طويل الأمد.</p><h3 id="تطبيقات-b-end-الكفاءة-والتكلفة-والتحكم-في-المخاطر-الموجهة-للمؤسسات" tabindex="-1">تطبيقات B-end: الكفاءة والتكلفة والتحكم في المخاطر الموجهة للمؤسسات <a class="header-anchor" href="#تطبيقات-b-end-الكفاءة-والتكلفة-والتحكم-في-المخاطر-الموجهة-للمؤسسات" aria-label="Permalink to “تطبيقات B-end: الكفاءة والتكلفة والتحكم في المخاطر الموجهة للمؤسسات”">​</a></h3><p>تطبيقات B-end موجهة للشركات والفرق والمؤسسات أو الأقسام. تشمل الأنواع الشائعة ERP (نظام إدارة الموارد)، وCRM (إدارة علاقات العملاء)، وأدوات العمل التعاوني، ومختلف أدوات SaaS، وأنظمة الإدارة الداخلية للقطاعات، وغيرها.</p><p><img src="'+B+'" alt=""></p><p>يكمن الاختلاف الأكبر بين هذه التطبيقات وتطبيقات C-end في أنها تحتاج إلى تلبية احتياجات أدوار متعددة في نفس الوقت. قد يكون المستخدمون هم الموظفين في الخطوط الأمامية، بينما صانعو القرار هم المديرون أو الرؤساء، وقد يكون مالكو البيانات هم المؤسسة نفسها، وقد تتضمن عمليات الموافقة أقسامًا متعددة. يجب عليك جعل التطبيق سهل الاستخدام للمستخدمين، <strong>وجعل صانعي القرار يرون</strong> <strong>عائد الاستثمار</strong>، <strong>وكذلك منح المؤسسة بأكملها شعورًا بالأمان من حيث المخاطر والامتثال.</strong></p><p>هناك العديد من نقاط التركيز الأساسية لتطبيقات B-end.</p><p><strong>أولاً، تحسين الكفاءة.</strong> لا يشير هذا فقط إلى توفير وقت شخص واحد، بل يعني تقليل الوقت المستغرق في العملية بأكملها، وخفض تكاليف التعاون، وتقليل حلقات التواصل. على سبيل المثال، كان الطلب في الماضي يمر عبر خمسة أنظمة من الإنشاء إلى الشحن، والآن يمكن أن يتدفق بالكامل من خلال مدخل موحد، وهذا النوع من التحسين ملموس جداً للشركات.</p><p><strong>ثانياً،</strong> <strong>خفض التكاليف</strong> <strong>.</strong> يشمل ذلك تكاليف العمالة، وتكاليف التدريب، وتكاليف صيانة النظام، وما إلى ذلك. إذا كان النظام يبدو قويًا جدًا من حيث الوظائف، لكنه يتطلب استثمارًا كبيرًا في التدريب وموارد الصيانة ليعمل بصعوبة، فستبدو نسبة تكلفته إلى فائدته منخفضة بالنسبة للعديد من الشركات الصغيرة والمتوسطة. بدلاً من ذلك، فإن أدوات SaaS التي تبدو أخف، ولكن يمكن البدء في استخدامها بسرعة ورؤية عوائدها بسرعة، هي التي تميل إلى البقاء في العالم الحقيقي.</p><p><strong>ثالثاً، التحكم في المخاطر وضمان الامتثال.</strong> في العديد من سيناريوهات B-end، هناك متطلبات عالية جدًا للامتثال وإمكانية التتبع، كما هو الحال في قطاعات التمويل، والرعاية الصحية، والتصنيع، والحكومة، وغيرها. غالبًا ما يضحي تطبيق B-end الجيد بقليل من حرية الاستخدام في مقابل إدارة أذونات أكثر وضوحًا، وتسجيل أكثر دقة للسجلات، وسلسلة موافقات أكثر وضوحًا. بالنسبة للمستخدمين كأفراد، قد يكون هناك مساحة أقل للتصرف بشكل عفوي، ولكن للمؤسسة ككل، هذا هو المكان الذي تكمن فيه القيمة.</p><p><strong>رابعاً، إدارة الأذونات وحدود المسؤولية.</strong> من يستطيع رؤية ماذا، ومن يستطيع تغيير ماذا، ومن المسؤول عن أي نتيجة، هذه الأسئلة غالبًا ما تكون محورية في تصميم أنظمة B-end. بمجرد الفشل في هذا الجانب، سيسبب ذلك متاعب كبيرة للمراجعات والنزاعات والمساءلة اللاحقة. لذلك، للحكم على ما إذا كان تطبيق B-end تطبيقًا جيدًا، لا يمكنك الاعتماد فقط على ما إذا كانت واجهته مريحة للعين، بل يجب عليك أيضًا التحقق مما إذا كان نموذج الصلاحيات الخاص به دقيقًا، وسهل الفهم والصيانة.</p><p>من الصناعة إلى التطبيق، يمكنك التفكير بهذه الطريقة: <strong>اختر صناعة لديك بعض المعرفة بها، مثل التعليم والتدريب، أو التجارة الإلكترونية، أو التصنيع، أو التمويل، أو الرعاية الصحية</strong>، ثم انظر في التشغيل اليومي لهذه الصناعة، ما هي العمليات التي تعتمد بشكل خاص على العمالة اليدوية، وما هي المعلومات التي غالبًا ما تكون مبعثرة عبر أنظمة متعددة أو محادثات خاصة متعددة، وما هي الروابط التي يكون فيها معدل الخطأ مرتفعًا جدًا ولكن يصعب اكتشافه على الفور. من خلال التركيز على هذه الجوانب، يمكنك غالبًا تصميم بعض الأدوات الصغيرة والمركزة للغاية.</p><p>على سبيل المثال، في صناعة التعليم والتدريب، نقطة دخول تطبيق محددة جدًا هي إنشاء أداة لجدولة الدورات التدريبية وتحسين استخدام الفصول الدراسية. لا تحتاج إلى استبدال النظام الأكاديمي بالكامل، فقط ركز على تسهيل قيام المعلمين الإداريين بترتيب المعلمين والفصول الدراسية وأوقات الدورات، وتجنب التعارضات تلقائيًا، وتقديم أفضل مجموعة، وتصدير جدول زمني يمكن للجميع فهمه. هذا البند وحده كافٍ لتوفير الكثير من الوقت المستغرق في التواصل المتكرر والتعديل.</p><p>في صناعة التجارة الإلكترونية، هناك طلب شائع وهو إدارة الطلبات متعددة القنوات. قد يكون لدى التجار متاجر على منصات مختلفة في نفس الوقت، وتكون معلومات الطلبات مبعثرة في كل مكان. إذا كان بإمكانك توفير أداة صغيرة تجمع طلبات المنصات المختلفة وتعالج معلومات ما بعد البيع والخدمات اللوجستية بشكل موحد، فستكون قد حللت بالفعل نقطة ألم كبيرة في عملياتهم اليومية المتكررة.</p><p>في قطاع التصنيع، لا تزال العديد من الشركات تعتمد على السجلات الورقية أو Excel لتتبع تقدم الإنتاج. يمكنك البدء بأداة بسيطة لتتبع أوامر العمل لمساعدة مديري المواقع على رؤية حالة كل عملية بشكل أكثر حدسية، بدلاً من الاعتماد على طرح الأسئلة وإجراء المكالمات الهاتفية طوال اليوم.</p><p>في قطاع التمويل أو الرعاية الصحية، قد لا تكون نقطة دخولك هي الأعمال الأمامية، بل يمكن أن تكون أداة مساعدة لفحص الامتثال، أو إنشاء قوالب المستندات، أو إدارة قوائم مواد الموافقة. طالما يمكنك توضيح كيفية جعل مهمة معينة لمنصب معين أكثر قابلية للتحكم في عملية معينة، فهذا يعتار اتجاهًا يستحق المحاولة.</p><p>غالبًا ما يكون لدى التطبيقات في الصناعات المذكورة أعلاه منتجات لشركات ناضجة يتم الترويج لها، وهذا في الواقع يوفر لك مسار مرجعي جيد: يمكنك البحث بنشاط على الإنترنت باستخدام الكلمات الرئيسية &quot;الصناعة المقابلة + الطلب الأساسي + المنتج&quot; (مثل &quot;نظام الجدولة الأكاديمية لصناعة التعليم والتدريب&quot;، &quot;أداة إدارة الطلبات متعددة القنوات للتجارة الإلكترونية&quot;). لن تجد مواقع الويب الرسمية للمنتجات ومقدمات الوظائف فحسب، بل يمكنك أيضًا رؤية تقييمات المستخدمين وحالات الصناعة وحتى مقاطع عرض المنتج. يمكن لهذه المعلومات مساعدتك في الفهم البديهي لكيفية حل المنتجات الناضجة لنفس المشكلات، وتجنب تكلفة التجربة والخطأ للبدء من الصفر.</p><h2 id="_3-4-التحسين-بناءً-على-بيانات-المستخدم-من-أعتقد-أنه-جيد-إلى-المستخدم-يعتقد-أنه-جيد" tabindex="-1">3.4 التحسين بناءً على بيانات المستخدم: من &quot;أعتقد أنه جيد&quot; إلى &quot;المستخدم يعتقد أنه جيد&quot; <a class="header-anchor" href="#_3-4-التحسين-بناءً-على-بيانات-المستخدم-من-أعتقد-أنه-جيد-إلى-المستخدم-يعتقد-أنه-جيد" aria-label="Permalink to “3.4 التحسين بناءً على بيانات المستخدم: من &quot;أعتقد أنه جيد&quot; إلى &quot;المستخدم يعتقد أنه جيد&quot;”">​</a></h2><p>بعد إنشاء التطبيق، من أكثر الأوهام شيوعًا التي يمكن أن تقع فيها: كلما استخدمته أكثر، أصبح أكثر سهولة بالنسبة لك، وتشعر أن كل شيء معقول، وتفترض أن المستخدمين سيشعرون بنفس الشيء. في الواقع، كلما كان المنتج من كتابتك، زادت سهولة تجاهل مشاكل الآخرين. لكي ينمو التطبيق تدريجيًا من عمل &quot;يشعر بالرضا عن الذات&quot; إلى تطبيق جيد حقًا، يجب أن تتعلم إدخال ملاحظات المستخدمين الحقيقية في الحلول.</p><h3 id="تصميم-آلية-بسيطة-للملاحظات،-لإعطاء-المستخدمين-منفذًا-للتعبير" tabindex="-1">تصميم آلية بسيطة للملاحظات، لإعطاء المستخدمين منفذًا للتعبير <a class="header-anchor" href="#تصميم-آلية-بسيطة-للملاحظات،-لإعطاء-المستخدمين-منفذًا-للتعبير" aria-label="Permalink to “تصميم آلية بسيطة للملاحظات، لإعطاء المستخدمين منفذًا للتعبير”">​</a></h3><p>لا تحتاج إلى البدء بإنشاء أنظمة خدمة عملاء ومنصات بيانات معقدة، يمكنك البدء ببعض الطرق البسيطة جدًا.</p><p><strong>مجموعات الدردشة هي الوسيلة الأكثر مباشرة.</strong> إذا كان لديك بالفعل مجموعة صغيرة من المستخدمين، يمكنك دعوة الجميع لنشر المشاكل والأفكار التي يواجهونها أثناء الاستخدام في المجموعة. ما يجب عليك فعله هو الرد بجدية، والتسجيل، والتلخيص بشكل دوري، بدلاً من الدفاع أو الجدال في المجموعة. كلما تمكنت من خلق جو من الصراحة في هذه المجموعة الصغيرة، أصبحت الملاحظات التي تجمعها لاحقًا أكثر قيمة.</p><p>الاستبيانات مناسبة للاستخدام عندما تحتاج إلى <strong>جمع كمية كبيرة من المعلومات المهيكلة لمرة واحدة</strong>، مثل بعد تحديث إصدار معين، عندما ترغب في معرفة شعور الجميع تجاه بعض الوظائف المحددة. إذا كنت ترغب في أن يكون معدل الملء مرتفعًا، فمن الأفضل ألا يكون الاستبيان طويلاً، ويجب أن تكون الأسئلة محددة قدر الإمكان، مثل ما هي الوظيفة التي تستخدمها أكثر خلال هذه الفترة، وفي أي خطوة واجهت أكبر عدد من المشاكل، بدلاً من السؤال بشكل عام عن شعورك تجاه هذا التطبيق بشكل عام.</p><p>النوافذ المنبثقة بعد الاستخدام هي طريقة شائعة أخرى، على سبيل المثال، بعد أن يكمل المستخدم مهمة، استخدم مربعًا قصيرًا جدًا للتقييم والاقتراح، وسؤاله عما إذا كانت هذه التجربة سلسة. في بعض الأحيان، يكون التقييم الرقمي البسيط كافيًا لمساعدتك في الحكم على ما إذا كانت هناك مشكلة واضحة في عملية معينة.</p><p>المقابلات الفردية تكلفتها عالية، ولكن العائد غالبًا ما يكون أكبر. يمكنك <strong>اختيار عدد قليل من المستخدمين من أنواع مختلفة، وطلب قضاء عشرين إلى أربعين دقيقة معهم</strong>، والتحدث بالتفصيل عن عاداتهم في الاستخدام اليومية، والسماح لهم بالشرح أثناء التشغيل لماذا رأوه وما شعروا به. كان هناك مؤسس شركة يعقد أكثر من عشر اجتماعات يوميًا للتحدث مع المستخدمين لجمع اقتراحاتهم، وقضاء الوقت في فهم احتياجات المستخدمين لن يكون أبدًا أمرًا سيئًا.</p><h3 id="تعلم-كيفية-استخراج-ثلاثة-أنواع-من-المعلومات-من-الملاحظات-الفوضوية" tabindex="-1">تعلم كيفية استخراج ثلاثة أنواع من المعلومات من الملاحظات الفوضوية <a class="header-anchor" href="#تعلم-كيفية-استخراج-ثلاثة-أنواع-من-المعلومات-من-الملاحظات-الفوضوية" aria-label="Permalink to “تعلم كيفية استخراج ثلاثة أنواع من المعلومات من الملاحظات الفوضوية”">​</a></h3><p>عادة ما تكون ملاحظات المستخدمين مختلطة، ومن الصعب رؤيتها بوضوح في لمحة. يمكنك محاولة تقسيمها إلى ثلاث فئات: <strong>الأخطاء البرمجية (bugs)، مشاكل تجربة المستخدم، الاحتياجات الجديدة.</strong></p><p><strong>الأخطاء البرمجية (bugs) تعني أنك قلت إن سلوكًا معينًا سيحدث، ولكن في ظل ظروف معينة لم يحدث على الإطلاق، أو حدث سلوك خاطئ.</strong> على سبيل المثال، فشل التحميل، أو التوقف المفاجئ، أو عدم استجابة الزر، أو النتيجة غير الصحيحة بوضوح. بالنسبة لهذه المشاكل، ما يجب عليك فعله هو إعادة إنتاج الخطأ وإصلاحه في أسرع وقت ممكن، وإبلاغ المستخدمين المتأثرين بشكل استباقي بعد الإصلاح، لإعلامهم بأنك تأخذ هذه المشاكل على محمل الجد.</p><p><strong>مشاكل تجربة المستخدم تكمن في عدم اختيار المسار الأكثر سلاسة في طول العملية، أو موقع التشغيل، أو التعبير النصي.</strong> على سبيل المثال، يتردد المستخدم دائمًا عند زر معين، ولا يعرف ما إذا كان النقر عليه سيؤدي إلى نتائج لا رجعة فيها؛ وظيفة معينة مهمة جدًا، لكنها توضع في ركن غير واضح؛ بعض الإعدادات الافتراضية تعاكس عادات معظم الناس، مما يجبرهم على القيام بخطوة إضافية في كل مرة. يتطلب هذا النوع من الملاحظات منك الجمع بين البيانات والملاحظة لتحديد ما إذا كنت ستقوم بإجراء تغيير، وإلى أي مدى يجب أن يكون التغيير مناسبًا.</p><p><strong>الاحتياجات الجديدة تعني أن المستخدمين يبدأون في اقتراح بعض الوظائف والسيناريوهات التي لم تفكر فيها في الأصل.</strong> بعض الاحتياجات الجديدة تستحق النظر فيها بجدية، مثل تنسيقات التصدير المتعددة، وقدرات العمل الجماعي، والتكامل مع الأدوات الشائعة الأخرى. ولكن يجب أيضًا الانتباه إلى أنه ليس كل ما يقترحه المستخدمون يجب عليك فعله. ما يجب عليك فعله حقًا هو التمييز، وما إذا كانت هناك مشاكل مشتركة وراء هذه الاحتياجات الجديدة، وما إذا كانت تتوافق مع المجموعة التي كنت ترغب في خدمتها في الأصل وتلك المهمة الأساسية. خلاف ذلك، سيكون من السهل عليك أن يتم سحبك في اتجاهات مختلفة بواسطة مجموعة من الاحتياجات المبعثرة، وفي النهاية تتحول إلى منتج يريد القيام بكل شيء، ولكنه لا يتقن أي شيء.</p><p>يمكنك تطوير عادة: وضع علامة على كل ملاحظة، توضح ما إذا كانت تنتمي إلى خطأ برمجي (bug)، أو مشكلة تجربة مستخدم، أو حاجة جديدة. قم بتلخيص هذه العلامات بشكل دوري لمعرفة نوع المشاكل التي تتركز في أي وظائف أو عمليات. بهذه الطريقة، لن تقوم فقط بالإصلاح بشكل سلبي، بل ستكون قادرًا على التكرار بشكل واعٍ حول المشاكل عالية التكرار.</p><h3 id="استخدم-ثلاثة-مؤشرات-بسيطة-لتحديد-ما-إذا-كنت-ستستثمر-أم-لا" tabindex="-1">استخدم ثلاثة مؤشرات بسيطة لتحديد ما إذا كنت ستستثمر أم لا <a class="header-anchor" href="#استخدم-ثلاثة-مؤشرات-بسيطة-لتحديد-ما-إذا-كنت-ستستثمر-أم-لا" aria-label="Permalink to “استخدم ثلاثة مؤشرات بسيطة لتحديد ما إذا كنت ستستثمر أم لا”">​</a></h3><p>في ظل الموارد المحدودة، تحتاج أيضًا إلى بعض المؤشرات البسيطة والفعالة لتحديد ما إذا كان هذا التطبيق يستحق استثمارك طويل الأمد.</p><p><strong>أولها هو الاحتفاظ (Retention).</strong> الاحتفاظ لا يعني النظر إلى عدد الأشخاص الذين فتحوا التطبيق في يوم معين، بل يعني النظر إلى <strong>عدد المستخدمين الذين لا يزالون يستخدمون التطبيق باستمرار خلال فترة زمنية</strong>. يمكنك إجراء إحصاء تقريبي جدًا، مثل عدد الأشخاص الذين استخدموا التطبيق مرة واحدة على الأقل خلال أسبوع بعد التنزيل، وعدد الأشخاص الذين عادوا خلال شهر. إذا كان معظم المستخدمين قد استخدموه مرة أو مرتين فقط ولم يعودوا أبدًا، فهذا يشير إلى أن تطبيقك لم يُظهر لهم قيمة كافية في المرحلة المبكرة، أو أن حاجز الاستخدام مرتفع جدًا. <strong>الثاني هو تكرار الزيارات العائدة.</strong> بالنسبة لأولئك الذين لم يقوموا بإلغاء تثبيت تطبيقك، كم مرة سيعودون بالضبط. الأداة التي يمكن استخدامها يوميًا والتطبيق الذي لا يُذكر إلا مرة واحدة كل ربع سنة، لهما مواقع منتجات مختلفة، وعليك استخدام معايير مختلفة لقياسهما. ولكن في كلتا الحالتين، يجب أن تكون قادرًا على تقديم توقع معقول لإيقاع الاستخدام، ثم مقارنته بالبيانات الفعلية لمعرفة ما إذا كان هناك انحراف كبير. إذا كانت الترددات أعلى من توقعاتك، فهذا يشير إلى أن القيمة قد تتجاوز التوقعات؛ وإذا كانت الترددات أقل بكثير من المتوقع، فيجب أن تعيد التفكير فيما إذا كنت لم تلتقط السيناريو بدقة، أو أن تجربة الاستخدام في مكان ما تجعل المستخدم يشعر بالتعب.</p><p><strong>الثالث هو الرغبة في التوصية.</strong> هل هناك من يرغب في التوصية بتطبيقك للآخرين بشكل استباقي. يمكن ملاحظة هذا الأمر بعدة طرق: على سبيل المثال، بعد أن يكمل المستخدم مهمة بسلاسة خاصة، قدم نقطة دخول طبيعية للمشاركة، وشاهد كم شخصًا يستخدمها فعليًا؛ أو انظر في المجموعات ما إذا كان هناك من يروج لمنتجك تلقائيًا؛ أو اسأل سؤالًا واحدًا أثناء مقابلات المستخدمين على نطاق صغير: &quot;إذا واجه شخص تعرفه مشكلة مماثلة، هل ستوصي بأداتي له؟&quot;. عادةً ما تكون الرغبة في التوصية أكثر دلالة من مجرد درجة رضا بسيطة، لأن التوصية هي سلوك يحمل ضمانًا شخصيًا بسمعة الموصِي، ولن يرغب المستخدم في تقديم تطبيقك لأصدقائه إلا إذا شعر أنك ساعدته حقًا بشكل كبير.</p><p>عندما تنظر إلى هذه المؤشرات الثلاثة معًا مع تعليقات المستخدمين التي تمت مناقشتها سابقًا، يمكنك بشكل عام الحكم على الحالة التي يمر بها تطبيقك حاليًا. ربما تكون الوظائف غير مكتملة بعد، ولكن هناك مجموعة من الأشخاص الذين بقوا بالفعل، وسيستخدمونك بشكل متكرر في سيناريوهات محددة، ومثل هذا التطبيق يستحق الاستمرار في الاستثمار والصقل. على العكس من ذلك، إذا قمت بإصلاح العديد من الأخطاء، وتراكمت العديد من الوظائف الجديدة، لكن معدل الاحتفاظ وتكرار الزيارات العائدة لا يرتفعان، ويكاد لا يكون هناك من يوصي بشكل استباقي، ففي هذا الوقت يجب أن تفكر بهدوء، هل يجب تقليص النطاق، والعودة إلى سيناريو النواة الأولي، أو حتى النظر في تغيير الاتجاه.</p><h1 id="_4-في-أي-خطوة،-وكيف-تستخدم-ai-بشكل-معقول-لتضخيم-القيمة؟" tabindex="-1">4. في أي خطوة، وكيف تستخدم AI بشكل معقول لتضخيم القيمة؟ <a class="header-anchor" href="#_4-في-أي-خطوة،-وكيف-تستخدم-ai-بشكل-معقول-لتضخيم-القيمة؟" aria-label="Permalink to “4. في أي خطوة، وكيف تستخدم AI بشكل معقول لتضخيم القيمة؟”">​</a></h1><p>بمجرد أن تبدأ في العمل الجاد على تطبيق ما، ستواجه قريبًا إغراءً شائعًا: هل يمكنني إضافة المزيد من AI إليه؟ يكمن سبب قوة هذا الإغراء في أنك ترى كل يوم أنواعًا مختلفة من الدعاية: AI يمكّن صناعة معينة، AI يعيد هيكلة عملية معينة بالكامل، AI يساعدك على حل كل شيء بنقرة واحدة. بمرور الوقت، من السهل جدًا أن تحول مشكلة بسيطة الأصل إلى شعار مليء بالدعاية، ثم تكدس بعض استدعاءات النماذج في حزمة التقنيات، وتشاهد أموال حسابك تنفد تدريجيًا.</p><p>على الرغم من أن هذا البرنامج التعليمي يعلم كيفية تطوير تطبيقات AI الأصلية، فإن الحديث عن هذا الموضوع يبدو وكأنه يضر بمصدر رزقي؛ ولكن بالنسبة لتطبيق صغير أو منتج في بداياته، <strong>أخطر شيء ليس عدم استخدام AI، بل استخدام AI من أجل AI</strong>. يمكنك في الأصل صنع أداة بسيطة ولكن موثوقة، لكنك تنجذب بواسطة قدرات جديدة متنوعة، وتضيف باستمرار وظائف تبدو ذكية، وفي النهاية تجعل اتجاهًا كان يمكن تطبيقه فعليًا مكلفًا ومعقدًا، دون أي تحسن واضح في القيمة. المشكلة الأساسية التي ستحلها هذه الفصل هي التوضيح بوضوح: في أي مرحلة، وفي أي روابط، وبأي طريقة يمكن لـ AI أن يساعدك حقًا في تضخيم قيمة تطبيقك.</p><h2 id="_4-1-لا-تستخدم-ai-من-أجل-ai" tabindex="-1">4.1 لا تستخدم AI من أجل AI <a class="header-anchor" href="#_4-1-لا-تستخدم-ai-من-أجل-ai" aria-label="Permalink to “4.1 لا تستخدم AI من أجل AI”">​</a></h2><p>للحكم على ما إذا كنت تستخدم AI من أجل AI دون أن تدرك ذلك، طريقة عملية جدًا هي أن تجبر نفسك على الإجابة بجدية على سؤالين قبل كل مرة تفكر فيها في إضافة وظيفة AI معينة.</p><p><strong>السؤال الأول هو: بدون AI، هل هذا التطبيق قائم أيضًا.</strong> أي، إذا قمت بإزالة جميع قدرات AI مؤقتًا، هل الشيء الذي تفعله في حد ذاته هو شيء ذو قيمة، وهل لدى المستخدمين احتياجات فعلية، وهل هم على استعداد لاستثمار وقت حقيقي في هذا الأمر يوميًا وأسبوعيًا وشهريًا.</p><p>قد يبدو هذا الكلام عكس التيار إلى حد ما، لأنه في الوقت الحالي تقريبًا جميع أوصاف المنتجات تضع AI في مكان بارز جدًا، وكأنه بدون AI لا يمكن اعتباره أداة حديثة. ولكن إذا كان تطبيقك لا يستطيع الصمود على الإطلاق في غياب AI، فهذا في كثير من الأحيان لا يشير إلى أن تقنيتك ليست متقدمة بما فيه الكفاية، بل إلى مشكلة أعمق: الاحتياج الذي التقطته قد لا يكون مؤلمًا أو ملحًا، أو ربما لا وجود حقيقي له على الإطلاق.</p><p>تخيل أنك تريد صنع أداة لمساعدة الأشخاص على تنظيم قائمة المهام. إذا كانت نقطة التمييز الرئيسية لديك هي: إضافة بعض المطالبات التي أنشأها النموذج إلى قائمة المهام، مثل إنشاء عناوين تلقائيًا، وتصنيف تلقائي، وإكمال الوصف تلقائيًا. ولكن المستخدمين عند كتابة المهام في الأصل لا يشعرون بأي ألم في كتابة عنوان، بل يرغبون فقط في إنهاء الكتابة بسرعة، فمهما كانت هذه القدرات الذكية مبهرة، فمن الصعب جدًا أن تشكل قيمة مستمرة. على العكس من ذلك، إذا تراجعت خطوة إلى الوراء وسألت بوضوح عن القيمة الأكثر بساطة لهذا التطبيق عند عدم استخدام AI، فقد تكتشف اتجاهًا أكثر صلابة: مساعدة المستخدمين على جمع المهام المبعثرة في قنوات مختلفة بشكل موحد، ومساعدته على رؤية عدد الأشياء التي يمكنه إنجازها فقط كل يوم، ومساعدته على رؤية المخاطر قبل انتهاء جدول الأعمال، وبالتالي القيام بالتخفيض والاختيار. إن إتقان هذه القدرات الأساسية غالبًا ما يكون أكثر أهمية من إضافة أنواع مختلفة من العلامات الذكية إلى قائمة المهام من البداية.</p><p><strong>السؤال الثاني هو: بعد استخدام AI، ما الذي تم تحسينه تحديدًا.</strong> هنا لا يتم قبول تلك الملخصات واسعة جدًا، مثل تحسين الكفاءة، أو إعادة هيكلة التجربة، أو الترقية الذكية، بل يجب أن تنزل إلى بُعد واحد أو اثنين يمكن للمستخدم نفسه إدراكه بوضوح.</p><p>يمكنك أن تسأل نفسك بهذا الشكل:</p><ul><li>هل هناك تحسن كبير في سرعة إتمام المهمة، مثل تحويل صفحة نصية كان يجب عليك كتابتها من الصفر بنفسك، إلى مجرد الحاجة لقضاء خمس دقائق في المراجعة وإعادة الكتابة</li><li>هل هناك تحسن واضح في جودة النتيجة، مثل السماح للمستخدم بإنتاج محتوى أكثر تنظيمًا، وأكثر احترافية، وأكثر توافقًا مع الجمهور المستهدف في نفس الوقت</li><li>هل جعل عملية الاستخدام أكثر سلاسة أو سهولة، مثل تحويل عملية نموذج مملة جدًا، إلى أسئلة وأجوبة تشبه الدردشة أكثر</li><li>هل جلب انخفاضًا في التكلفة الفعلية، مثل تقليل عدد مرات الت outsourcing، وتقليل مدة خدمة العملاء اليدوية، وتقصير دورة التدريب، وتقصير وقت اتخاذ القرار</li></ul><p>إذا كانت الإجابات التي تعطيها في ذهنك لا تزال عالقة عند <strong>الشعور بأنها</strong> ستكون أكثر راحة قليلاً، أو تبدو أكثر برودة قليلاً، فهذا في تسعة من أصل عشر حالات يشير إلى أن وظيفة AI هذه لم تجد بعد نقطة الارتكاز الأكثر أهمية.</p><p>هذان السؤالان لهما في الواقع ترتيب واضح جدًا. أولاً تأكد من أنه حتى بدون AI، هذا التطبيق منطقي، ثم على هذا الأساس اسأل، بعد إضافة AI، ما الذي تحسن تحديدًا.</p><h2 id="_4-2-التفكير-في-الدور-الذي-تلعبه-ai" tabindex="-1">4.2 التفكير في الدور الذي تلعبه AI <a class="header-anchor" href="#_4-2-التفكير-في-الدور-الذي-تلعبه-ai" aria-label="Permalink to “4.2 التفكير في الدور الذي تلعبه AI”">​</a></h2><p>عندما تتأكد من أن هذا التطبيق قائم حتى بدون AI، وقد وجدت بالفعل نقطة تحسين واضحة، فإن الشيء الذي يجب فعله في الخطوة التالية هو التفكير بشكل أكثر تحديدًا: <strong>في تطبيقك، ماذا يفعل AI بالضبط.</strong> العديد من المنتجات تخطئ في هذه الخطوة، لأنها تعامل AI كنوع من الطاقة المجردة، وليس كدور له تقسيم عمل محدد. النتيجة هي أن الوظائف مكدسة بكثرة، لكن دور كل قطعة غامض وغير واضح، وعندما يستخدمها المستخدمون يشعرون فقط أن هناك لمسة ذكية في كل مكان، لكنهم لا يستطيعون قول أي مكان لا يمكنهم الاستغناء عنه حقًا.</p><p>فكرة أوضح هي التعامل مع AI كعدة أجزاء مختلفة: <strong>يمكن أن يكون الدماغ، أو العين، أو اليد</strong>. تحتاج إلى تحديد الجزء الذي يكون مسؤولاً عنه بناءً على هدف منتجك، وإذا أمكن، من الأفضل اختيار دور واحد أو اثنين فقط في البداية والقيام بهما بشكل جيد، بدلاً من حشر كل شيء دفعة واحدة.</p><p><img src="'+L+'" alt=""></p><p><strong>عندما يلعب دور الدماغ، يكون مسؤولاً بشكل أساسي عن فهم وإنشاء المحتوى النصي، أو إجراء الاستدلال بين المعلومات المعقدة.</strong> على سبيل المثال، إذا كنت تصنع مساعدًا لمحاضر الاجتماعات، فيجب أن يكون قادرًا على التقاط نقاط النقاش الأساسية الحقيقية من تسجيل صوتي طويل، بدلاً من مجرد سردها بترتيب زمني. إذا كنت تصنع تطبيقًا تعليميًا، فيجب أن يكون قادرًا على الحكم بناءً على إجابة المستخدم، ما إذا كان لم يفهم المفهوم، أو كان مجرد إهمال في كتابة الخطوات، وإعطاء ملاحظات مختلفة. في مثل هذه السيناريوهات، تكمن قيمة AI في قدرته على قراءة ما يقوله المستخدم، وفهم المواد التي قدمها المستخدم، ثم إنشاء مخرجات منظمة ومنطقية. ما عليك فعله هو مساعدة المستخدم على توضيح سؤاله، وتقديم السياق بدقة كافية، لكي يكون لهذا الدماغ معلومات كافية لاتخاذ القرار.</p><p><strong>عندما يلعب دور العين، تتركز النقطة في معالجة المحتوى غير النصي مثل الصور ومقاطع الفيديو،</strong> وتحويل هذه الأشياء إلى أوصاف يمكن للآلة فهمها، ثم اتخاذ إجراءات إضافية بناءً على هذه الأوصاف. على سبيل المثال، إذا كنت تصنع أداة لتنظيم المستندات الورقية، فيمكنها من خلال التعرف على الصور، تحويل مجموعة من الفواتير والعقود وأدلة التغليف إلى نصوص قابلة للبحث. إذا كنت تصنع تطبيقًا لتعلم الرسم، فيمكنه فهم الرسومات التخطيطية التي رسمها المستخدم، ثم الإشارة إلى بعض المشاكل في التكوين وخطوط الرسم. إذا كنت تصنع أداة لاقتراحات ترتيب المنزل، فيمكنها من خلال الصور التي يرفعها المستخدم، التعرف على تخطيط الغرفة الحالي وتوزيع العناصر، ثم تقديم بعض خطط التعديل البسيطة والقابلة للتنفيذ. هنا تكمن نقطة AI في: أنه يعمل كعين تحلل، مما يجعل تطبيقك لم يعد قادرًا فقط على معالجة النصوص المدخلة بلوحة المفاتيح، بل يبدأ في الاتصال الفعلي بالعالم المادي في حياة المستخدم.</p><p><strong>عندما يلعب دور اليد، فهذا يعني أنه يبدأ في تنفيذ سلسلة من الإجراءات المحددة</strong>، وليس مجرد إعطاء اقتراح أو نتيجة نصية. على سبيل المثال، بعض منصات الأتمتة تتيح لك ربط خطوات متعددة في سير عمل واحد: قراءة المرفقات من البريد الإلكتروني، تلخيص المحتوى إلى نقاط رئيسية، إرساله إلى مجموعة، ثم حفظ النص الأصلي في السحابة، وأخيرًا إنشاء مهمة متابعة تلقائيًا في أداة إدارة المهام. هنا دور AI هو مساعدتك في العمليات المعقدة، بناءً على السياق لتحديد ديناميكي ما يجب فعله في الخطوة التالية، مثل التعرف على ما إذا كانت رسالة بريد إلكتروني هي شكوى، والحكم على ما إذا كان نموذج معين مكتملًا، ثم تفعيل عمليات لاحقة مختلفة بناءً على ذلك.</p><p>بالإضافة إلى الأوصاف البسيطة المذكورة أعلاه، في التطبيقات الفعلية، غالبًا ما يكون الدور الذي تتحمله AI أكثر تحديدًا وتنوعًا، على سبيل المثال:</p><p>في معالجة النصوص، قد يكون يقوم بالترجمة، أو التلخيص، أو الأسئلة والأجوبة، أو الكتابة التكميلية، أو تحليل المشاعر: مثل التصنيف التلقائي لاستفسارات المستخدمين في نظام خدمة العملاء، واستخراج بنود العقود في مساعد المستندات القانونية، وتصحيح مقالات الكتابة في التطبيقات التعليمية.</p><ul><li>الأساس التقني هو بشكل أساسي <strong>نماذج اللغات الكبيرة (LLM)</strong> في التعلم العميق: تتعلم قواعد اللغة ومعرفة العالم من كميات هائلة من النصوص، ويمكنها ليس فقط &quot;فهم&quot; السياق في النصوص الطويلة والمحادثات متعددة الجولات، ولكن أيضًا &quot;كتابة&quot; محتوى متماسك ومنسق بشكل متسق.</li><li>على جانب &quot;الفهم&quot;، يمكن لـ LLM التعرف على نية المستخدم، واستخراج المعلومات الرئيسية، والحكم على الميل العاطفي؛ وعلى جانب &quot;التوليد&quot;، يُستخدم لكتابة الملخصات تلقائيًا، والإجابة على الأسئلة، وإجراء الكتابة التكميلية وإعادة الكتابة، والترجمة متعددة اللغات، مما يجعل الكثير من العمل الذي يتطلب قراءة بشرية واستنتاجًا وكتابة آليًا أو شبه آلي.</li><li>لنأخذ <strong>روبوت خدمة العملاء عبر الإنترنت</strong> كمثال: يقوم النظام أولاً بالحكم بشكل مبدئي بناءً على جملة واحدة من المستخدم لتحديد ما إذا كانت استفسارًا أو شكوى أو خدمة ما بعد البيع، ويستخرج من الكلام المعلومات الرئيسية مثل رقم الطلب والوقت واسم المنتج، ثم يسلمها إلى LLM لكي يقوم مع السياق وقاعدة المعرفة الخاصة بالمؤسسة بتوليد رد طبيعي ومتكامل، مما يقلل من الضغط على العنصر البشري، ويحافظ على جودة خدمة مستقرة في أوقات الذروة.</li></ul><p>في مجال معالجة الصور، قد يكون الأمر يتعلق بالتعرف أو التصنيف أو التوليد أو الإصلاح أو التحسين: على سبيل المثال، التعليق التوضيحي لمواضع الآفات في الصور الطبية، أو فصل الصور تلقائيًا وتغيير الخلفيات في منصات التجارة الإلكترونية، أو إنشاء صور توضيحية بناءً على الأوصاف النصية في أدوات التصميم.</p><ul><li>يعتمد فهم الصور عادةً على نماذج الرؤية العميقة مثل <strong>الشبكات العصبية التلافيفية (CNN)</strong>، حيث تتعلم من كميات هائلة من الصور سمات مثل الحواف والأنسجة والهياكل، وتُستخدم في اكتشاف الكائنات وتقسيم الصور والتصنيف الدقيق (مثل التمييز بين الآفات المختلفة أو فئات المنتجات المختلفة).</li><li>يعتمد توليد الصور وإصلاحها على <strong>نماذج توليدية مثل نماذج الانتشار وGAN</strong>، حيث يمكن إنشاء صور جديدة تمامًا بناءً على أوصاف نصية أو صور مرجعية، وإصلاح الصور الضبابية أو غير المكتملة أو منخفضة الدقة وتحسينها بدقة فائقة.</li><li>العديد من الأنظمة تجمع أيضًا مع LLM: حيث تفهم أولاً وصف المستخدم النصي باللغة الطبيعية، ثم تولد تلقائيًا &quot;كلمات تحفيزية&quot; مناسبة للنماذج البصرية، وعلامات الأسلوب، وقيود التكوين، مما يحقق الانتقال من &quot;فهم ما تريده&quot; إلى &quot;رسم ما تريده&quot;.</li><li>لنأخذ <strong>&quot;توليد الصورة الرئيسية الذكية&quot;</strong> في منصات التجارة الإلكترونية كمثال: يستخدم النظام أولاً نماذج الكشف والتقسيم لاستخراج المنتج بدقة من الصورة الأصلية، ثم يقوم LLM بتحليل النص الذي أدخله التاجر (مثل &quot;مشهد غرفة معيشة بأسلوب شمال أوروبي بسيط، إضاءة طبيعية ناعمة&quot;)، وتحويله إلى معلمات محددة للمشهد ودرجة اللون والأسلوب، وأخيرًا يسلمها إلى نموذج الانتشار لتوليد الخلفية وتأثيرات الضوء والظل المطابقة، ويقوم تلقائيًا باستبعاد النتائج ذات التكوين السيئ أو غير المتوافقة مع الأسلوب، لإخراج صورة رئيسية للمنتج يمكن استخدامها مباشرة للعرض.</li></ul><p>في مجال معالجة الصوت والفيديو، قد يكون الأمر يتعلق بتوليد الصوت والفيديو، أو نسخه، أو تقليل الضوضاء، أو تحريره، أو إنشاء ترجمات نصية: على سبيل المثال، التوليد التلقائي للتعليق الصوتي في بداية ونهاية البودكاست، أو التوليف التلقائي لفيديوهات الشرح بناءً على النص في منصات الفيديو، أو النسخ والترجمة الفورية للمحادثات في برامج المؤتمرات وإنشاء ترجمات نصية متعددة اللغات وتسجيلات للعرض لاحقًا.</p><ul><li>على جانب &quot;الفهم&quot;، يستخدم النظام <strong>نماذج التعرف على الكلام</strong> لتحويل الكلام إلى نص، وفي الوقت نفسه يحلل المتحدث واللغة وسرعة الكلام والعاطفة العامة؛ ويستخدم نماذج الرؤية لفهم المشاهد والأشخاص والكائنات الرئيسية في إطارات الفيديو.</li><li>على جانب &quot;التوليد&quot;، وباستخدام LLM كنواة، يتم فهم وتقسيم وإعادة كتابة النصوص أو محتوى الاجتماعات أو تعليمات المستخدم، ثم يتم تشغيل <strong>تركيب الكلام (TTS)</strong> لتوليد تعليق صوتي طبيعي، وتشغيل نماذج توليد وتحرير الفيديو **لتوليف أو تحرير الإطارات تلقائيًا، أو استبدال الخلفيات، أو إدراج اللقطات والترجمات النصية؛ ويمكن لنماذج التوليد الصوتي أيضًا إنشاء موسيقى خلفية وأصوات بيئية تلقائيًا، جنبًا إلى جنب مع تقليل الضوضاء العميق وتحسين جودة الصوت لرفع جودة الاستماع بشكل عام.</li><li>لنأخذ منتجات <strong>&quot;توليد فيديو قصير من النص&quot;</strong> كمثال: يحتاج المستخدم فقط إلى إدخال نص، ويقوم النظام أولاً باستخدام LLM لتقسيم المقال إلى عدة فقرات ومشاهد طبيعية، وتوليد نص تعليق صوتي مناسب للإلقاء ووصف بسيط للقصة المصورة؛ ثم يقوم نموذج TTS بتوليف التعليق الصوتي، وتقوم قوالب الفيديو ونماذج التوليد باختيار أو توليد الإطارات بناءً على القصة المصورة، ومحاذاة الترجمات النصية مع الكلام تلقائيًا على الجدول الزمني، وأخيرًا يتم تصدير فيديو قصير بنقرة واحدة يمكن نشره مباشرة.</li></ul><p>في مجال التفاعل الصوتي، قد يكون الأمر يتعلق بالتعرف أو التوليف أو اكتشاف المشاعر أو إدارة الحوار: على سبيل المثال، فهم تعليمات المستخدم في مكبرات الصوت الذكية، أو إعلان الاتجاهات في الملاحة الصوتية، أو تصحيح النطق في تطبيقات تعلم اللغات.</p><ul><li>في الواجهة الأمامية، تقوم <strong>نماذج التعرف على الكلام</strong> القائمة على التعلم العميق بتحويل صوت المستخدم إلى نص، واستخراج سمات مثل نبرة الصوت ومستوى الصوت وسرعة الكلام، لتوفير أدلة للحكم على المشاعر والحالة.</li><li>في الواجهة الخلفية، يتم استخدام <strong>تركيب الكلام (TTS)</strong> لتحويل هذه الردود النصية إلى مخرجات صوتية طبيعية وسلسة، ويقوم نموذج التعرف على المشاعر بتعديل نبرة وسرعة الرد بناءً على طريقة كلام المستخدم الحالية، مما يجعل التفاعل أقرب إلى المحادثة الحقيقية.</li><li>لنأخذ <strong>مكبرات الصوت الذكية</strong> كمثال: عندما يقول المستخدم &quot;أنا متعب قليلاً اليوم، شغل بعض الموسيقى الهادئة&quot;، يقوم النظام أولاً بتحويل الكلام إلى نص عبر التعرف على الكلام، ثم يقوم LLM بفهم أسلوب &quot;الهادئ&quot; المفضل لدى المستخدم بالجمع بين سجل التشغيل السابق، ويختار تلقائيًا قائمة تشغيل أكثر هدوءًا؛ بعد أن يحكم التعرف على المشاعر بأن المستخدم في حالة إرهاق، يقوم TTS عند توليف الرد بخفض سرعة الكلام وتنعيم النبرة، مما يجعل عملية التواصل بأكملها &quot;مفهومة&quot; و&quot;مريحة للاستماع&quot; في نفس الوقت.</li></ul><p>المحتوى أعلاه هو مجرد مقدمة بسيطة لتطبيقات وتقنيات الذكاء الاصطناعي في عدة اتجاهات رئيسية. في سيناريوهات الأعمال الحقيقية، غالبًا ما تحتاج إلى إدخال أحدث واجهات برمجة تطبيقات الذكاء الاصطناعي المتعددة وإجراء اختبارات أكثر شمولاً على مهام مختلفة. كما تحتاج إلى الفهم التدريجي لمدى قوة قدرات الذكاء الاصطناعي الحالية، وما هي المشاكل التي يمكنها حلها، وفي أي الحالات تكون عرضة للأخطاء، وأين تكمن حدودها. فقط من خلال إدراك ذلك، يمكنك تصميم الميزات والعمليات بشكل معقول، دون ترك مخاطر كامنة بسبب الحكم الخاطئ على القدرات.</p><p>بعد ذلك، سنتناول هذه النقطة ونناقش بشكل أكثر منهجية في القسم التالي: كيفية فهم قدرات وحدود الذكاء الاصطناعي، وما الذي يجب مراعاته عند بناء المنتجات فعليًا.</p><h2 id="_4-3-التعرف-على-قدرات-وحدود-الذكاء-الاصطناعي" tabindex="-1">4.3 التعرف على قدرات وحدود الذكاء الاصطناعي <a class="header-anchor" href="#_4-3-التعرف-على-قدرات-وحدود-الذكاء-الاصطناعي" aria-label="Permalink to “4.3 التعرف على قدرات وحدود الذكاء الاصطناعي”">​</a></h2><p>عندما تبدأ فعليًا في دمج الذكاء الاصطناعي في التطبيقات، ستكتشف بسرعة حقيقة واحدة: ما يُقال عن القدرات الشاملة في الدعاية يختلف أحيانًا كثيرًا عن القيود المفروضة على ميزة محددة. لتجنب الإفراط في الوعود والفشل في تحقيق النتائج، <strong>تحتاج إلى أن يكون لديك فهم أساسي للاتجاهات الرئيسية لقدرات الذكاء الاصطناعي الحالية، مع تحديد واضح لحدود كل منها. تحتاج إلى إجراء عدد كبير من الاختبارات للحصول على حالات فاشلة (Bad Cases) للتأمل، وتجنب الحالات التي من المرجح جدًا أن يخطئ فيها الذكاء الاصطناعي أثناء الاستخدام. أو قد تحتاج إلى إضافة تحذيرات بشأن الأخطاء.</strong></p><p>لا تزال النماذج الحالية تعاني من مشكلة اختلاق المعلومات في العديد من السيناريوهات، خاصة عندما تتركها حرة التفكير أو لا تزودها بمراجع موثوقة بما فيه الكفاية. في بعض الأحيان تعطي إجابات تبدو واثقة تمامًا لكنها خاطئة تمامًا، بل وقد تختلق من العدم ملفات أو بيانات أو تجارب غير موجودة. لذلك، في أي سيناريو تكون فيه النتائج مرتبطة بعواقب خطيرة، مثل التقارير المالية، أو المستندات القانونية، أو النصائح الطبية، يجب عليك تصميم نظام يضيف بوضوح طبقة من المراجعة البشرية أو الفحوصات المتعددة، ولا تتخذ مخرجات النموذج كتعليمات يمكن تنفيذها تلقائيًا بشكل مباشر.</p><p>في الوقت نفسه، تعد الخصوصية وأمن البيانات أيضًا جزءًا يجب عليك مواجهته بجدية. يجب أن تعرف بوضوح تام البيانات التي يمكن إرسالها مباشرة إلى النموذج، والبيانات التي تحتاج إلى إخفاء هويتها، والبيانات التي يجب ألا تظهر ببساطة في أنظمة الطرف الثالث. بالنسبة للمحتوى الحساس الذي يرفعه المستخدمون، مثل العقود، والسجلات الطبية، ومعلومات الهوية الشخصية، يجب توضيح طريقة معالجتك بوضوح في الواجهة والاتفاقيات، وحتى اختيار طرق نشر نماذج أكثر أمانًا وقابلية للتحكم لهذه السيناريوهات بشكل منفصل عندما يكون ذلك ممكنًا.</p><p>بشكل أكثر تحديدًا، دعنا نستعير مثالًا متعلقًا بالوكيل (Agent) لتوضيح ما يعنيه فهم حدود قدرات الذكاء الاصطناعي حقًا. ملاحظة: الهدف هنا ليس تعليمك كيفية بناء وكيل من الصفر، ولا مطالبتك بالبحث عن بنية معينة الآن، بل استخدام هذا المثال لتوضيح طريقة تفكير: عند الحديث عن Agent، يعتبره البعض مجرد مصطلح جديد، بينما يستطيع آخرون استغلال الموضوع لتقسيم المهام بوضوح ورسم الحدود بدقة.</p><p>قدم Barret Li Jing، وهو كاتب يعمل في تطبيقات الذكاء الاصطناعي على الخطوط الأمامية لفترة طويلة، ملخصًا أوافق عليه تمامًا، لشرح كيفية بناء Agent بشكل جيد وما إذا كان يجب استخدام الذكاء الاصطناعي. إنه يعكس بوضوح طريقة فهم ناضجة: قسّم المشكلة أولاً، ثم تحدث عن المجال الذي يمكن للذكاء الاصطناعي أن يبرز فيه.</p><blockquote><p>يحتوي Agent على متغيرين: أحدهما هو سير العمل (workflow) الذي يتحكم في اتجاه المهمة، والآخر هو السياق (context) الذي يتحكم في توليد المحتوى.</p><ol><li><p>إذا كانت درجة اليقين لكل من سير العمل والسياق عالية، فمن السهل أتمتة هذه المهام، على غرار RPA التقليدية. على سبيل المثال، في معالجة الفواتير ومهام تعبئة النماذج، يكون الذكاء الاصطناعي بمثابة مادة لاصقة، والمجال المتاح له محدود نسبيًا.</p></li><li><p>إذا كان سير العمل مؤكدًا ولكن السياق غير مؤكد، أي أن العملية ثابتة ولكن المدخلات متغيرة، فسيحتاج Agent إلى سد الفجوات في الدلالات والفهم، مثل أسئلة وأجوبة خدمة العملاء وتحليل العقود، مما يتطلب أدوات مثل الاسترجاع الخارجي ورسم المعرفة لسد الفجوات المعلوماتية، وجعل نتائج الاستدلال أكثر توافقًا مع التوقعات.</p></li><li><p>إذا كان سير العمل غير مؤكد ولكن السياق مؤكد، أي أن المدخلات واضحة ولكن المسارات متنوعة، فسيحتاج Agent إلى تخطيط المسار بشكل مستقل، مثل توليد تقارير تحليل السوق والتوصيات المخصصة. معظم وكلاء RL من النهاية إلى النهاية (End-to-End RL Agent) جيدون في أداء هذه المهام لأنهم اكتسبوا خلال مرحلة التدريب قدرًا كبيرًا من تخطيط المسارات وأفكار حل المشكلات.</p></li><li><p>وعندما يكون كل من سير العمل والسياق غير مؤكد، فهذا هو السيناريو الأكثر تعقيدًا، والذي يتطلب الاستدلال والاستكشاف في نفس الوقت، مثل تصميم الحلول المبتكرة وجمع المعلومات عبر الأقسام. هذا النوع يميل أكثر إلى كونها وكلاء (Agents) للأغراض العامة، وتعتمد جودة تنفيذها على ثراء الأدوات المزودة لها، خاصة ضرورة تعظيم الانفتاح أمام قدرات البرمجة، مثل تعليمها الذهاب إلى Github للعثور على المستودعات واستنساخها وتعديل التعليمات البرمجية لحل المشكلات، وجعلها تعمل مثل البشر.</p></li></ol><p>لذلك، لبناء Agent بشكل جيد، يجب أولاً توضيح السيناريو. في جوهرها، تحل الأتمتة مشاكل &quot;اليقين&quot;، بينما يحل الذكاء مشاكل &quot;عدم اليقين&quot;.</p></blockquote><p>تكمن قيمة طريقة التفكيك هذه في تحويل المفهوم الغامض المتمثل في &quot;بناء Agent&quot; إلى مشاكل يمكن الحكم عليها بشكل ملموس: أين يكمن اليقين وعدم اليقين في المهمة التي تواجهها؟ عندما تكون العملية والمعلومات مؤكدتين، فإن البرامج التقليدية تكفي؛ فقط عندما يظهر عدم اليقين، تصبح قدرات الذكاء الاصطناعي في الفهم الدلالي، والتعرف على الأنماط، وتخطيط الاستدلال ذات فائقة. ولكن في الوقت نفسه، كلما زاد عدم اليقين، زادت المخاطر الجديدة التي يقدمها الذكاء الاصطناعي. في السيناريوهات التي يكون فيها الجانبان غير مؤكدين، قد ينحرف الذكاء الاصطناعي في كل خطوة، ومن الصعب جدًا معرفة الخيارات التي سيتخذها مسبقًا. هذا هو السبب في أن العديد من الفرق تبدأ من الربع الثاني (سير العمل مؤكد، السياق غير مؤكد)، مما يمكنهم من استغلال قدرات الفهم لدى الذكاء الاصطناعي، وفي الوقت نفسه إبقاء المخاطر ضمن نطاق يمكن التحكم فيه من خلال العمليات الثابتة.</p><p>دعنا نعود إلى المشكلة التي أردنا حلها في بداية هذا القسم الفرعي: ما الذي يعنيه فهم حدود قدرات الذكاء الاصطناعي حقًا؟ أولاً، فهم أن الاحتياجات من الذكاء الاصطناعي تختلف باختلاف السيناريوهات. كما أوضح المثال السابق الخاص بـ workflow و context: عندما يكون كل من التدفق والمعلومات مؤكدين، لا توجد مساحة كبيرة لعمل الذكاء الاصطناعي، والأتمتة التقليدية تكفي؛ وعندما يكون التدفق مؤكدًا ولكن المعلومات غير مؤكدة، تكمن قيمة الذكاء الاصطناعي في الفهم والإكمال؛ وعندما يكون التدفق غير مؤكد، يحتاج الذكاء الاصطناعي إلى القيام بالتخطيط والاستكشاف. جوهر طريقة التحليل هذه هو تحديد مصدر ودرجة عدم اليقين. القدرة الأساسية للذكاء الاصطناعي هي إيجاد الأنماط والارتباطات وسط عدم اليقين. هذه الفكرة لا تنطبق فقط على الوكلاء (Agent)، بل هي مهمة بنفس القدر في مجالات مثل التعرف على الصور، وتوليد المحتوى، وأنظمة التوصية وغيرها. على سبيل المثال، عند إنشاء أداة لقص الصور بالذكاء الاصطناعي، يكون المدخل مؤكدًا (صورة واحدة)، لكن دقة التعرف على الحواف والقدرة على التعامل مع الخلفيات المعقدة هي نقاط عدم اليقين.</p><p><img src="'+N+'" alt=""></p><p>ومع ذلك، بينما يحل الذكاء الاصطناعي مشكلة عدم اليقين، فإنه يقدم في الوقت نفسه عدم يقين جديد. مخرجاته احتمالية، وقد يسيء الفهم، أو ينحرف في الاستدلال، أو ينتج هلوسات. وتختلف tolerability (تقبل) هذا عدم اليقين تمامًا باختلاف السيناريوهات والمستخدمين. لذلك يجب أن تسأل أيضًا:</p><p><strong>هل يمكن للمستخدمين والنظام تحمل عدم اليقين الجديد الذي أدخله الذكاء الاصطناعي؟</strong> على سبيل المثال، في سيناريو خدمة العملاء، إذا أساء الذكاء الاصطناعي فهم نية المستخدم، يمكن للمستخدم تصحيح ذلك على الفور، وهذا عدم يقين يمكن السيطرة عليه. ولكن إذا كان الأمر يتعلق بالتنفيذ التلقائي للموافقات المالية، فإن خطأ واحد في الحكم من قبل الذكاء الاصطناعي قد يؤدي إلى عواقب وخيمة، وهذا عدم يقين غير مقبول. ومثال آخر على توليد الصور، إذا كان الأمر يتعلق بتجميل صورة الملف الشخصي للمستخدم، يمكنه إعادة التوليد إذا لم يكن راضيًا عن النتيجة، وتكلفة التجربة والخطأ منخفضة؛ ولكن إذا كان الأمر يتعلق بتوليد مخططات بناءة لمهندس معماري، فإن خطأً تفصيليًا واحدًا قد يؤدي إلى حادث هندسي.</p><p><strong>هل يمكن لمعدل دقة الذكاء الاصطناعي الوصول إلى خط النجاح في هذا السيناريو؟ يعتمد هذا الخط على ما يستخدمه المستخدم الذكاء الاصطناعي لفعله.</strong> في التعرف على الصور، إذا كان الهدف هو مساعدة المستخدمين في تنظيم ألبومات الصور وتصنيفها حسب الوجوه، يمكن للمستخدمين قبول معدل دقة يبلغ 80٪، وفي أسوأ الحالات يمكنهم التعديل اليدوي لبعض الصور. ولكن إذا تم استخدامه في سيناريو مراقبة الأمن، فإن تفويت 20٪ من المشتبه بهم يمثل خطرًا أمنيًا جسيمًا. وبالمثل في توليد النصوص، إذا كان الهدف هو مساعدة المستخدمين في كتابة منشورات وسائل التواصل الاجتماعي، فإن مستوى إبداع 60 درجة يكفي، وسوف يقوم المستخدمون بصقلها بأنفسهم؛ ولكن إذا كان الأمر يتعلق بتوليد بنود العقود القانونية، فإن 95 درجة ليست كافية، لأن اختيار كلمة غير لائقة قد يؤدي إلى نزاعات قانونية. تختلف حساسية المستخدمين المختلفين والاستخدامات المختلفة لمعدلات الخطأ تمامًا، ويجب أن تكون واضحًا بشأن السيناريو الذي تخدمه ومقدار مساحة السماح بالخطأ التي تمتلكها.</p><p><strong>عندما يخطئ الذكاء الاصطناعي، هل توجد طريقة للعلاج؟</strong> في السيناريوهات التي يكون فيها workflow مؤكدًا، يمكنك إعداد مراجعة بشرية في العقد الرئيسية للسيطرة على عدم اليقين في الذكاء الاصطناعي محليًا. ولكن في السيناريوهات التي يكون فيها workflow غير مؤكد أيضًا، قد تنحرف كل خطوة من خطوات الذكاء الاصطناعي، ويصعب عليك الحكم على متى يحتاج الأمر إلى تدخل، وعندها سترتفع التكلفة والمخاطر بشكل حاد. على سبيل المثال، في سيناريو استعادة الصور، إذا لم تكن استعادة الذكاء الاصطناعي للصور القديمة واقعية بما فيه الكفاية، يمكن للمستخدم أن يلاحظ ذلك بنظرة واحدة ويمكنه اختيار عدم استخدامها؛ ولكن في سيناريو التشخيص المساعد للتصوير الطبي، إذا قام الذكاء الاصطناعي بوضع علامة على الشذوذ في المكان الخطأ، قد يكون من الصعب جدًا على الطبيب اكتشاف ذلك، وتكون العواقب أكثر خطورة بكثير.</p><p><strong>هل لديك طريقة لقياس وتحسين أداء الذكاء الاصطناعي؟</strong> إذا لم تكن هناك معايير واضحة للصواب والخطأ في المهمة نفسها، فكيف تعرف ما إذا كان الذكاء الاصطناعي يؤدي بشكل جيد؟ إذا كانت ملاحظات المستخدمين متأخرة جدًا، فكيف يمكنك التكرار بسرعة؟ عندما لا تتمكن حتى من القياس، سيصبح عدم اليقين في الذكاء الاصطناعي صندوقًا أسود. على سبيل المثال، في نظام التوصية، يمكنك تقييم التأثير بسرعة من خلال مؤشرات مثل نسبة النقر ومعدل البقاء؛ ولكن إذا كان الأمر يتعلق بتوليد نصوص إعلانية إبداعية، فإن تعريف ما هو &quot;جيد&quot;ذاتي للغاية في حد ذاته، وقد تضطر إلى الانتظار حتى الترويج لمعرفة معدل التحويل، وستكون دورة التكرار طويلة جدًا.</p><p>الحكم الناضج حقًا ليس &quot;يوجد عدم يقين هنا، لذا يمكن استخدام الذكاء الاصطناعي&quot;، بل &quot;عدم اليقين الموجود هنا يمكن للذكاء الاصطناعي التعامل معه، وعدم اليقين الجديد الذي يجلبه الذكاء الاصطناعي يمكنني إدارته أيضًا&quot;. &quot;في هذه النقطة الوظيفية، إلى أي مدى يمكن للذكاء الاصطناعي المساعدة، وهل يستحق الاستثمار، وكيف تكون أعلى عائد على الاستثمار.&quot; نحتاج إلى تطوير هذه القدرة على الحكم، والتي يمكن أن تساعدنا في توفير الكثير من الجهد غير المجدي في كل مرة نصمم فيها ميزة أو نقيم فيها حلًا مستقبلاً.</p><h1 id="_5-بعد-بناء-التطبيق،-كيف-تجد-أول-مستخدمين-حقيقيين-من-الصفر" tabindex="-1">5. بعد بناء التطبيق، كيف تجد أول مستخدمين حقيقيين من الصفر <a class="header-anchor" href="#_5-بعد-بناء-التطبيق،-كيف-تجد-أول-مستخدمين-حقيقيين-من-الصفر" aria-label="Permalink to “5. بعد بناء التطبيق، كيف تجد أول مستخدمين حقيقيين من الصفر”">​</a></h1><p>عندما تنجح أخيرًا في بناء تطبيق، ستتحول المشكلة التالية إلى: كيف تجعل أول مستخدمين حقيقيين يظهرون.</p><p>ستتوهم العديد من الفرق في هذه المرحلة أنه بمجرد بناء المنتج، فإن الخطوة التالية هي مجرد التفكير في كيفية الترويج له - القيام بالدعاية، وشراء الإعلانات، والبحث عن الوصول، ويبدو أنه طالما جعل المزيد من الناس يرونه، فإنه سيعمل بشكل طبيعي. ولكن إذا سارعت إلى السعي وراء التعرض الواسع النطاق من البداية، فمن السهل أن تقع في فخ نموذجي: حرق الوقت والميزانية الثمينين، وتبدو البيانات وكأن هناك أشخاصًا قد زاروا، لكنك غير قادر على التحقق مما إذا كان أي شخص على استعداد لاستخدام هذا التطبيق باستمرار.</p><p>في الواقع، أهم شيء في هذه المرحلة هو شيء واحد فقط: <strong>بأقل تكلفة ممكنة، أثبت أن هناك أشخاصًا على استعداد لاستخدام هذا التطبيق بالفعل، وبعد استخدامه هم على استعداد للعودة</strong>. في سياق النمو والمنتجات، تُعرف هذه الخطوة عادة باسم &quot;البدء البارد&quot; (Cold Start).</p><p>يشير البدء البارد إلى: في ظل وجود كل شيء تقريبًا عند الصفر، دفع منتج جديد تمامًا إلى خطوة العمل الفعلي. في هذا الوقت، ليس لديك قاعدة مستخدمين، ولا ترويج شفهي، ولا حجم بحث ووعي بالعلامة التجارية، وجميع المؤشرات تقريبًا متوقفة عند 0. يجب عليك في هذه البيئة الباردة الهادئة جعل أول مجموعة من الأشخاص المستعدين حقًا للاستخدام يظهرون، وبناء حلقة استخدام أولية حولهم.</p><p>هذا يختلف تمامًا عن العمل اللاحق المتعلق بتحسين منتج يمتلك بالفعل مستخدمين وبيانات. وبشكل مبسط، يمكننا المضي قدمًا في الخطوات الأربع التالية:</p><ol><li>أولاً، إدراك أن النمو يمكن تقسيمه إلى 0–1 و 1–N، ومعرفة ما تحتاج فقط إلى فهمه في الوقت الحالي</li><li>توضيح من هم الأشخاص الذين تبحث عنهم حقًا، ولا تركز فقط على المستخدمين النهائيين</li><li>بشرط معرفة من تبحث عنه، اختر مسارًا أو مسارين للبدء البارد يناسبانك</li><li>في واقع الموارد المحدودة، تعلم كيف تحدد الأولويات، وتضييق جهودك إلى المنطقة الأكثر أهمية</li></ol><h2 id="_5-1-أولاً،-نميز-بين-المرحلتين-0–1-و-1–n" tabindex="-1">5.1 أولاً، نميز بين المرحلتين: 0–1 و 1–N <a class="header-anchor" href="#_5-1-أولاً،-نميز-بين-المرحلتين-0–1-و-1–n" aria-label="Permalink to “5.1 أولاً، نميز بين المرحلتين: 0–1 و 1–N”">​</a></h2><p>قبل مناقشة كيفية العثور على المستخدمين رسميًا، تحتاج إلى توضيح شيء واحد: <strong>النمو مقسم إلى مراحل</strong>. النظر إلى جميع الأعمال المتعلقة بالنمو ممزوجة معًا سيجعلك فقط لا تعرف أين تضع طاقتك في الوقت الحالي. أبسط وأكثر الطرق عملية للقسمة هي تفكيك النمو إلى مرحلتين: 0–1 و 1–N.</p><h3 id="_0–1-في-غياب-المستخدمين،-كيف-تبدأ-باردًا" tabindex="-1">0–1: في غياب المستخدمين، كيف تبدأ باردًا <a class="header-anchor" href="#_0–1-في-غياب-المستخدمين،-كيف-تبدأ-باردًا" aria-label="Permalink to “0–1: في غياب المستخدمين، كيف تبدأ باردًا”">​</a></h3><p>يشير ما يسمى بـ 0–1 إلى العملية من عدم وجود مستخدمين على الإطلاق، إلى ظهور مجموعة صغيرة من المستخدمين المستعدين للاستخدام الحقيقي. &quot;برودة&quot; البدء البارد تكمن في أن جميع المؤشرات تقريبًا تكون صفرًا في البداية: لا تنزيلات، لا حجم بحث، لا ترويج شفهي، يمكن القول إن تطبيقك غير موجود في هذا العالم.</p><p>في هذا الوقت، لا يمكنك الاعتماد على حركة المرور العضوية والحظ، بل يجب أن تتخذ خطوة استباقية لبناء الأساس الأولي له. تحديدًا، هناك بعض الأشياء التي يجب إنجازها:</p><p><strong>العثور على مجموعة صغيرة من المستخدمين الأوائل المستعدين للاستخدام الحقيقي</strong>، بدلاً من تجميع الأشخاص عشوائيًا من دائرة المعارف. يجب أن يكون لدى هؤلاء الأشخاص احتياج حقيقي للمشكلة التي تريد حلها، بدلاً من فتح التطبيق بنظرة واحدة بدافع المجاملة أو الفضول ثم المغادرة.</p><p><strong>إعداد تجربة الاستخدام الأولية والعرض</strong>، للتأكد من أن المستخدمين لن يروا صفحة فارغة فقط عند الدخول. حتى لو لم تكن الميزات كاملة بعد، يجب على الأقل السماح لهم بإكمال عملية أساسية كاملة والشعور بقيمة هذا التطبيق.</p><p><strong>شرح ما يفعله المنتج والمشكلة التي يحلها بكلمات بسيطة</strong>. في غياب تأييد العلامة التجارية، فإن صبر المستخدم معك هو بضع ثوانٍ فقط، ويجب عليك جعلهم يفهمون &quot;ما الفائدة من هذا الشيء بالنسبة لي&quot; في أقصر وقت ممكن.</p><p><strong>إيجاد طريقة للحصول على قناة الوصول الأولى</strong>، لتوصيل هذه المعلومات إلى المستخدمين المحتملين. قد يكون مجتمعًا صغيرًا، أو منتدى، أو لحظات WeChat. المفتاح ليس حجم القناة، بل ما إذا كان يمكنك الوصول بدقة إلى الأشخاص الذين يحتاجون إليها حقًا.</p><p>في مرحلة 0–1، ما يجب أن تفكر فيه حقًا هو: جلب أول مجموعة من الأشخاص ذوي الاحتياجات الحقيقية، والسماح لهم بإكمال حلقة مغلقة من الدخول إلى الاستخدام ثم تقديم الملاحظات. طالما يمكن تشغيل هذه الحلقة المغلقة بنجاح، فقد أثبتّ أن هذا التطبيق ليس مجرد قصر في الهواء، بل هو شيء يحتاجه الناس حقًا ومستعدون لاستخدامه.</p><h3 id="_1–n-على-أساس-أن-هناك-أشخاصًا-مستعدين-للاستخدام،-كيف-تقوم-بالتوسع" tabindex="-1">1–N: على أساس أن هناك أشخاصًا مستعدين للاستخدام، كيف تقوم بالتوسع <a class="header-anchor" href="#_1–n-على-أساس-أن-هناك-أشخاصًا-مستعدين-للاستخدام،-كيف-تقوم-بالتوسع" aria-label="Permalink to “1–N: على أساس أن هناك أشخاصًا مستعدين للاستخدام، كيف تقوم بالتوسع”">​</a></h3><p>عندما تقوم بتراكم مجموعة من المستخدمين المستعدين للاستخدام المتكرر ببطء، ستصبح المشكلة: كيف تتوسع ببطء من عشرات أو مئات الأشخاص إلى آلاف أو عشرات الآلاف، أو حتى أكثر. هذه المرحلة هي ما يسمى تقليديًا بالنمو، والتوسع، وتحقيق الحجم (الاستثمار).</p><p>في مرحلة 1–N، ستبدأ في الاهتمام بمجموعة أكثر تعقيدًا من المشكلات مثل الآليات، والتنظيم، والتحويل التجاري، والعلامة التجارية، والفريق. على سبيل المثال:</p><p><strong>هل وجدت قنوات اكتساب عملاء مستقرة نسبيًا</strong>، وتعرف مقدار الميزانية أو الوقت الذي يجب استثماره لجلب مستخدمين جدد تقريبًا. ما تحتاجه في هذا الوقت لم يعد يعتمد على الحظ، بل مسارات نمو قابلة للتكرار والتنبؤ بها.</p><p><strong>هل بدأت في بناء آلية خدمة</strong>، مثل خدمة العملاء، والعمليات التشغيلية، وتثقيف المستخدمين. بعد زيادة عدد المستخدمين، لن تتمكن من تعليم كل شخص كيفية الاستخدام يدويًا واحدًا تلو الآخر كما في الأيام الأولى، ويجب إنشاء نظام خدمة موحد.</p><p><strong>كيف تخطط لجعل هذا المنتج يكسب المال</strong>، هل هو عبر الاشتراك، أو الدفع لمرة واحدة، أو الخدمات المضافة، أو غير ذلك. لا يجب أن يكون نموذج العمل واضحًا من البداية، ولكن عند دخولك مرحلة 1–N، يجب التفكير بجدية في كيفية جعل هذا المنتج يعمل بشكل مستدام.</p><p><strong>ما هي الانطباع عن العلامة التجارية الذي تريد تركه لدى المستخدمين</strong>. في الأيام الأولى، قد تنتشر فقط في دائرة صغيرة، ولكن عندما يتوسع حجم المستخدمين، تحتاج إلى التفكير في كيفية جعل المزيد من الناس يتذكرونك، ويثقون بك، ومستعدين للتوصية بك للآخرين بنشاط.</p><p><strong>ما هي القدرات التي ينقص الفريق، وأي الروابط يجب أن يراقبها شخص ما على المدى الطويل</strong>، ولا يمكن الاستعانة بمصادر خارجية بالكامل. يمكن لشخص واحد أو فريق صغير تحمل مرحلة 0–1، ولكن 1–N غالبًا ما تتطلب تعاونًا بين المزيد من الأدوار.</p><p>كل هذه الأسئلة مهمة، ولكن إذا سارعت إلى التفكير فيها أثناء مرحلة 0–1، فغالبًا ما يجعلك ذلك تدور في حلقة مفرغة. لأنه عندما لا تعرف حتى ما إذا كان هذا المنتج يحتاجه الناس حقًا ومستعدون للبقاء، فإن التحدث عن نماذج العمل واستراتيجيات العلامة التجارية سيصرف الانتباه فقط عن الأمور الحقيقية العاجلة.</p><h3 id="لماذا-يجب-التركيز-على-0–1-أولاً؟" tabindex="-1">لماذا يجب التركيز على 0–1 أولاً؟ <a class="header-anchor" href="#لماذا-يجب-التركيز-على-0–1-أولاً؟" aria-label="Permalink to “لماذا يجب التركيز على 0–1 أولاً؟”">​</a></h3><p>بالنسبة للمطورين المستقلين والفرق الصغيرة، مقارنة بمرحلة 1–N، <strong>يجب أن يكون التركيز الحقيقي على مرحلة 0–1</strong>. السبب بسيط: إذا لم تتمكن حتى من العثور على أول مجموعة من المستخدمين الحقيقيين، فإن جميع المناقشات اللاحقة حول التوسع، والتسويق التجاري، وبناء العلامة التجارية ستكون مجرد كلام فارغ.</p><p>مرحلة 0–1 هي اللحظة الأكثر هشاشة والأكثر أهمية في دورة حياة المنتج بالكامل. فهي تحدد ما إذا كنت قادرًا على إثبات قيمة هذا المنتج، وما إذا كان بإمكانك بناء الثقة الأولية، وما إذا كان يمكنك وضع أساس متين للنمو اللاحق. فقط عندما تنجح حقًا في اجتياز مرحلة 0–1، يحق لك عندئذ التفكير في مسائل مرحلة 1–N.</p><p>بعد ذلك، سنركز بشكل أعمق على مرحلة 0–1، لتوضيح سؤال &quot;من يجب أن نبحث عنه بالضبط&quot;، ثم ننتقل لمناقشة مسارات الإطلاق البارد المحددة.</p><h2 id="_5-2-هدف-الإطلاق-البارد-المستخدمون-الأوائل،-ومقدمو-العروض،-ومصادر-الزيارات،-والقنوات" tabindex="-1">5.2 هدف الإطلاق البارد: المستخدمون الأوائل، ومقدمو العروض، ومصادر الزيارات، والقنوات <a class="header-anchor" href="#_5-2-هدف-الإطلاق-البارد-المستخدمون-الأوائل،-ومقدمو-العروض،-ومصادر-الزيارات،-والقنوات" aria-label="Permalink to “5.2 هدف الإطلاق البارد: المستخدمون الأوائل، ومقدمو العروض، ومصادر الزيارات، والقنوات”">​</a></h2><p>بالنسبة لأنواع مختلفة من التطبيقات، غالبًا ما لا يمكن تجاوز العديد من الأطراف الرئيسية: المستخدمون الأوائل، ومقدمو العروض، ومصادر الزيارات، والقنوات.</p><h3 id="الفئة-الأولى-المستخدمون-الأوائل-seed-users" tabindex="-1">الفئة الأولى: المستخدمون الأوائل (Seed Users) <a class="header-anchor" href="#الفئة-الأولى-المستخدمون-الأوائل-seed-users" aria-label="Permalink to “الفئة الأولى: المستخدمون الأوائل (Seed Users)”">​</a></h3><p><strong>المستخدمون الأوائل هم أو مجموعة من المستخدمين الذين تصل إليهم.</strong> من خصائصهم النموذجية أن عددهم قليل، لكنهم يتطابقون بشكل كبير مع الشخصية المستهدفة. ما تحتاج إلى الحصول عليه منهم ليس مجرد بيانات التسجيل والاستخدام، بل هو ردود فعل مباشرة حول الاتجاه وتجربة الاستخدام.</p><ul><li>بالنسبة للمنتجات الموجهة للأدوات الشخصية، قد يكون المستخدمون الأوائل هم أولئك الذين يعانون من مشكلة معينة لفترة طويلة، مثل منشئي المحتوى الذين يكتبون مقالات طويلة بشكل متكرر ويحتاجون إلى تنظيمها، أوالمهنيين الذين يعدون مواد عروض تقديمية باستمرار، أو الطلاب الذين يتعاملون مع كميات كبيرة من المواد يوميًا</li><li>بالنسبة لتطبيقات التعليم، قد يكون المستخدمون الأوائل مجموعة صغيرة من الطلاب الذين يستعدون لنفس الامتحان، أو أولياء أمور لطلاب في مرحلة دراسية معينة</li></ul><p>عند الإطلاق البارد، يمكنك البدء بتحديد هدف واضح للمستخدمين الأوائل، مثل العثور على 20 إلى 50 مستخدمًا مستعدًا للتعاون، وقضاء أسبوع أو أسبوعين في استخدام المنتج والتحدث معهم في نفس الوقت. التركيز ليس على الكمية، بل على توضيح منطق المنتج من خلال التواصل المكثف.</p><h3 id="الفئة-الثانية-مقدمو-العروض-supply-side" tabindex="-1">الفئة الثانية: مقدمو العروض (Supply Side) <a class="header-anchor" href="#الفئة-الثانية-مقدمو-العروض-supply-side" aria-label="Permalink to “الفئة الثانية: مقدمو العروض (Supply Side)”">​</a></h3><p><strong>في بعض المنتجات ذات المنصات ثنائية أو متعددة الأطراف</strong>، لا يكفي وجود جانب المستخدمين فقط. إذا لم يكن هناك عدد كافٍ من مقدمي العروض، فحتى لو تم جذب المستخدمين، فسيغادرون بسرعة لأنهم لا يجدون ما يمكنهم استخدامه.</p><p><strong>قد يكون مقدمو العروض منشئي محتوى، أو معلمي دورات، أو مقدمي خدمات، أو تجار، أو سائقين، أو ملاك عقارات</strong>، وهم من يحددون تنوع المنصة وجاذبيتها.</p><ul><li>إذا كنت تبني منصة مواد مصممة للمصممين، فعليك أولاً إقناع مجموعة من المصممين بالاستعداد لتحميل أعمالهم، حتى لو كان ذلك مجرد فتح جزء صغير من المواد المجانية. بخلاف ذلك، عندما يدخل المستخدمون ويرون مجرد بضع صور أمثلة، سيكون من الصعب جدًا تكوين ولاء للمنتج</li><li>إذا كنت تبني أداة حجز عبر الإنترنت، ولم تقم مسبقًا بالتنسيق مع بعض التجار أو المؤسسات المستعدة للاستخدام، فلن يتمكن المستخدمون العاديون بعد دخولهم من العثور على كائنات يمكنهم حجزها فعليًا</li></ul><p>عند الإطلاق البارد، يجب أن تعرف بوضوح شديد ما إذا كنت تحل مشكلة جانب المستخدم أولاً، أو جانب العرض أولاً، أو التقدم في كلا الجانبين في نفس الوقت. مرت العديد من المنصات بهذه المفاضلات والقرارات في المراحل المبكرة. طالما أنك تدرك أن هذه مشكلة هيكلية يجب مواجهتها، فقد تقدمت خطوة إلى الأمام بالفعل مقارنة بأولئك الذين يفكرون فقط في جذب المزيد من المستخدمين النهائيين.</p><h3 id="الفئة-الثالثة-مصادر-الزيارات-traffic-sources" tabindex="-1">الفئة الثالثة: مصادر الزيارات (Traffic Sources) <a class="header-anchor" href="#الفئة-الثالثة-مصادر-الزيارات-traffic-sources" aria-label="Permalink to “الفئة الثالثة: مصادر الزيارات (Traffic Sources)”">​</a></h3><p>مصادر الزيارات هم هؤلاء الذين يمكنهم <strong>في وقت قصير نسبيًا، توجيه انتباه عدد معين من المستخدمين إليك. قد يكونوا مدونين مؤثرين، أو حسابات متخصصة، أو وسائل إعلام، أو مشغلي مجتمعات، أو قد يكونوا منصة أدوات تمتلك قاعدة مستخدمين كبيرة.</strong></p><ul><li>منتج فئة أدوات مهنية، إذا تمكن من إقناع عدد قليل من مدوني التطوير المهني بتقديم تطبيقك بشكل طبيعي في محتواهم، فستكون لديك فرصة للحصول على مجموعة من الأشخاص الحساسين لأدوات الكفاءة المهنية في وقت قصير</li><li>مساعد اختيار مواضيع لمنشئي المحتوى على منصة Xiaohongshu، إذا تمكن من التعاون مع عدة مدونين من المستوى المتوسط، والسماح لهم بعرض عملية الاستخدام في حالات عملية حقيقية، فإن هؤلاء المنشئين هم بطبيعة الحال مستخدموك الأوائل المحتملون</li></ul><p>في مرحلة الإطلاق البارد، لا تحتاج إلى التسرع في البحث عن أكبر مصادر الزيارات، ولا حتى التفاوض على التعاون مع كبار المؤثرين فورًا. في كثير من الأحيان، تكون مصادر الزيارات الصغيرة ذات الحجم المعتدل والتي تتطابق بشكل كبير مع الجمهور المستهدف أكثر استعدادًا للقيام ببعض المحاولات المخصصة معك. ما عليك فعله هو العثور على هؤلاء الأشخاص أو المؤسسات، ثم تقديم عرض تعاون واضح، بحيث يفهمون ما تريد القيام به وما هي الفوائد التي ستعود عليهم.</p><h3 id="الفئة-الرابعة-القنوات-channels" tabindex="-1">الفئة الرابعة: القنوات (Channels) <a class="header-anchor" href="#الفئة-الرابعة-القنوات-channels" aria-label="Permalink to “الفئة الرابعة: القنوات (Channels)”">​</a></h3><p>القنوات هي تلك المنظمات أو نقاط الدخول التي يمكنها مساعدتك في <strong>الوصول إلى المستخدمين المستهدفين بشكل ثابت في سيناريوهات محددة</strong>. الفرق بينهم وبين مصادر الزيارات هو أن مصادر الزيارات تميل أكثر إلى كونها استيرادًا لمرة واحدة للانتباه، بينما القنوات هي أشبه باتصال طويل الأمد ومنظم.</p><ul><li>المدارس، ومعاهد التدريب، والشركات، وجمعيات الصناعة، ومقدمي الخدمات البرمجية، كلها قنوات نموذجية إذا كان تطبيقك يمكنه بالفعل مساعدة نوع معين من المؤسسات على تحسين الكفاءة، أو توفير التكاليف، أو تحسين جودة الخدمة، فسيكون لديهم حافز لتقديم منتجك لعدد كبير من المستخدمين داخل نظامهم</li></ul><p>في مرحلة الإطلاق البارد، لا تحتاج إلى الوهم بالاستحواذ على قنوات كبيرة دفعة واحدة، بل يمكنك البدء بتجربة صغيرة النطاق. على سبيل المثال، التعاون مع فصل أو فصلين دراسيين، أو شركة صغيرة، أو مجتمع محلي، للسماح لهم باستخدامه داخليًا لفترة من الوقت، ثم بناءً على ردود الفعل، تقرر ما إذا كنت تريد توسيع النطاق.</p><p>يتمثل الفرض المباشر لتفكيك أهداف الإطلاق البارد في أنه يمنعك من استنزاف كل طاقتك في جذب مستخدمين نهائيين جدد، مع تجاهل حلقات رئيسية أخرى في هيكل المنتج. يمكنك رسم مخطط بسيط للأدوار بناءً على شكل منتجك، وتدوين من هم كل فئة من الأهداف، وكم عددهم الآن، وما هي أهدافك قصيرة المدى لكل منهم. بعد توضيح مخطط الأهداف هذا، يمكننا التحدث عن مسارات الإطلاق البارد المحددة.</p><h2 id="_5-3-طرق-الإطلاق-البارد-ثلاثة-مسارات-رئيسية-لأهداف-مختلفة" tabindex="-1">5.3 طرق الإطلاق البارد: ثلاثة مسارات رئيسية لأهداف مختلفة <a class="header-anchor" href="#_5-3-طرق-الإطلاق-البارد-ثلاثة-مسارات-رئيسية-لأهداف-مختلفة" aria-label="Permalink to “5.3 طرق الإطلاق البارد: ثلاثة مسارات رئيسية لأهداف مختلفة”">​</a></h2><p>عندما تعرف من هم الأشخاص الذين يجب أن تبحث عنهم، فإن الخطوة التالية هي: من خلال أي مسار يمكنك العثور عليهم وخدمتهم.</p><p>في الممارسة العملية، لا يتعين عليك التقيد بمسار واحد، بل تقم بالاختيار بناءً على مواردك وخصائص منتجك. في معظم الأحيان، ستجعل مسارًا واحدًا هو المسار الرئيسي، ومسارًا أو مسارين آخرين كدعم.</p><h3 id="المسار-الأول-الاختراق-بالمستخدمين-الأوائل،-وإعطاء-الأولوية-للاستخدام-الجيد-للجمهور-الخاص" tabindex="-1">المسار الأول: الاختراق بالمستخدمين الأوائل، وإعطاء الأولوية للاستخدام الجيد للجمهور الخاص <a class="header-anchor" href="#المسار-الأول-الاختراق-بالمستخدمين-الأوائل،-وإعطاء-الأولوية-للاستخدام-الجيد-للجمهور-الخاص" aria-label="Permalink to “المسار الأول: الاختراق بالمستخدمين الأوائل، وإعطاء الأولوية للاستخدام الجيد للجمهور الخاص”">​</a></h3><p>هذا المسار يهدف بشكل أساسي إلى المستخدمين الأوائل وبعض مقدمي العروض.</p><p>بالنسبة لمعظم المطورين المستقلين، والفرق الصغيرة، وحتى الشركات الناشئة التي بدأت للتو، فإن الطريقة الأكثر واقعية والأقل تكلفة والأسهل للتحكم في وتيرتها عادةً ما تبدأ من جمهورك الخاص الحالي.</p><p>ما يسمى بالجمهور الخاص (المناطق الخاصة) ليس مفهومًا تشغيليًا معقدًا، بل هو مجموعة من الأشخاص يمكنك الوصول إليهم بشكل استباقي، مثل دائرة أصدقائك، والمجتمعات الصناعية التي تشارك فيها، ومجموعات الاهتمامات التي يكون لك فيها صوت، وقراء حسابك الرسمي الذين حافظت عليهم لفترة من الوقت، وما إلى ذلك.</p><p>في هذا المسار، هناك ثلاثة إجراءات رئيسية تقريبًا:</p><ol><li><strong>دعوة عدد قليل من المستخدمين المستهدفين بدقة لتجربة المنتج</strong> المفتاح ليس في الكمية، بل في مدى التطابق مع الشخصية المستهدفة. إذا كانت الأداة التي طورتها موجهة للمبتدئين في مكان العمل لكتابة السير الذاتية، فابحث أولاً عن الزملاء الذين تخرجوا للتو منذ عام أو عامين، أو الطلاب الذين يستعدون للتدريب، وليس المعارف الذين عملوا لمدة عشر سنوات. عند الدعوة، حاول توضيح ثلاثة أشياء: <ol><li>هذا تطبيق لأي فئة من الأشخاص لحل أي مشكلة</li><li>كم من الوقت تأمل أن يقضيه الطرف الآخر في تجربته</li><li>كيف ستعامل الملاحظات التي يقدمونها</li></ol></li><li><strong>جمع الملاحظات بوعي والتحسين السريع</strong> قيمة المستخدمين الأوائل لا تكمن في مساعدتك في زيادة الأرقام، بل في مساعدتك في رؤية النقاط العمياء في منتجك بوضوح. يمكنك من خلال محادثات فردية، أو استبيانات صغيرة، وغيرها من الطرق، أن تسأل بوضوح: في أي سيناريو سيتذكرون استخدامه، وأين يتوقفون عند استخدامه، وأي جزء هو الأكثر فائدة أو غير مفيد تمامًا.</li><li><strong>جعل المستخدمين الأوائل ينتجون المحتوى أو الحالات الأولى</strong> آثار الاستخدام الحقيقية هي محتوى. التقييمات، ولقطات الشاشة المقارنة، وقصص الاستخدام، كلها يمكن أن تكون مواد عند تقديم نفسك للعالم الخارجي لاحقًا.</li></ol><p>في هذه العملية، يجب عليك كبح رغبتك في السعي وراء الانتشار واسع النطاق منذ البداية. إذا لم تتمكن حتى من خدمة هؤلاء العشرات من الأشخاص بشكل جيد، فإن الاعتماد فقط على تعريض أكبر لدفع المزيد من الأشخاص إلى نفس المشاكل هو في جوهره تضخيم للمشكلة، وليس حلها.</p><h3 id="المسار-الثاني-القيادة-بالمحتوى-أو-المزايا،-وتقديم-سبب-أول-واضح-بما-فيه-الكفاية" tabindex="-1">المسار الثاني: القيادة بالمحتوى أو المزايا، وتقديم سبب أول واضح بما فيه الكفاية <a class="header-anchor" href="#المسار-الثاني-القيادة-بالمحتوى-أو-المزايا،-وتقديم-سبب-أول-واضح-بما-فيه-الكفاية" aria-label="Permalink to “المسار الثاني: القيادة بالمحتوى أو المزايا، وتقديم سبب أول واضح بما فيه الكفاية”">​</a></h3><p>هذا المسار يركز أكثر على المستخدمين الأوائل ومصادر الزيارات، وهو شائع بشكل خاص في المسارات التنافسية الشرسة.</p><p>عندما يكون لدى المستخدمين العديد من الخيارات البديلة، فإن مجرد عبارة مثل &quot;تعال أيها المستخدم الجديد وجرب&quot; لن تكون كافية لإقناعهم، بل تحتاج إلى تقديم سبب أكثر وضوحًا وجاذبية، لجعل الطرف الآخر مستعدًا لقضاء الوقت في اتخاذ الخطوة الأولى.</p><p>طريقتان شائعتان للبدء:</p><ol><li>استخدام <strong>المزايا الحقيقية الملموسة كطعم مباشر</strong><ol><li>منصة دورات جديدة، يمكنها في المراحل المبكرة إطلاق بعض الدورات المجانية عالية الجودة، أو توفير أماكن بخصومات لفترة محدودة</li><li>تستخدم تطبيقات التجارة الإلكترونية غالبًا طرقًا مثل مظاريف الخصومات، والشراء الجماعي بأسعار منخفضة، وكوبونات تخفيض السعر للطلبات فوق حد معين، لجعل المستخدمين الجدد يشعرون بأنهم لن يخسروا إذا زاروا أولاً</li></ol></li><li><strong>الجذب المستمر بالمحتوى المتخصص</strong> على منصات مثل Douyin، وXiaohongshu، والحسابات الرسمية، والبودكاست، وغيرها، قم بالإخراج المستقر للمحتوى القيم حول موضوع متخصص يهتم به المستخدمون المستهدفون، مثل النصائح المهنية، أو مهارات البرمجة، أو إدارة المشاعر، أو دروس الطبخ، أو أساليب التعلم، وما إلى ذلك. الموجة الأولى من الأشخاص الذين يتم جذبهم من خلال المحتوى قد لا يتحولون على الفور إلى مستخدمي تطبيقك، ولكن على الأقل لديهم ثقة أساسية بك بالفعل، وعندما تقدم لهم الأداة أو التطبيق في الوقت المناسب، فمن المرجح أنهم سيعطونك نظرة جادة.</li></ol><p>إذا كنت تتبنى نهج القيادة بالمحتوى، فيجب أن تتقبل أن هذه طريقة بطيئة في البداية ولكنها ذات عائد طويل الأمد. تحتاج إلى الاستثمار المستمر للطاقة لجعل المحتوى متينًا، وتجنب أن تقودك مشاهدات التشغيل أو أرقام القراءة منذ البداية. <strong>ما يمكنه حقًا مساعدتك في الإطلاق البارد هو تلك الدفعة الصغيرة من الأشخاص الذين يجدون صدى في المحتوى، وليس الزيارات التي تتدفق في وقت قصير وتتبدد بسرعة.</strong> سواء كانت مزايا أو استيرادًا للمحتوى، في النهاية يجب أن ينتهي الأمر بنفس الجملة: يجب توجيه الأشخاص بسلاسة إلى تطبيقك، والسماح لهم بإكمال تجربة كاملة.</p><h3 id="المسار-الثالث-الاستفادة-من-المنصات-الكبيرة،-والبحث-عن-نقطة-اختراق-في-النظام-البيئي-الحالي" tabindex="-1">المسار الثالث: الاستفادة من المنصات الكبيرة، والبحث عن نقطة اختراق في النظام البيئي الحالي <a class="header-anchor" href="#المسار-الثالث-الاستفادة-من-المنصات-الكبيرة،-والبحث-عن-نقطة-اختراق-في-النظام-البيئي-الحالي" aria-label="Permalink to “المسار الثالث: الاستفادة من المنصات الكبيرة، والبحث عن نقطة اختراق في النظام البيئي الحالي”">​</a></h3><p>هذا المسار يهدف بشكل أساسي إلى مقدمي العروض، ومصادر الزيارات، والقنوات.</p><p>في العديد من المجالات، إذا أراد تطبيق جديد بناء نظام بيئي خاص به بالكامل، فستكون التكلفة عالية جدًا. ولكن إذا كنت مستعدًا لاعتبار نفسك أولاً متجرًا جديدًا، أو حسابًا جديدًا، أو مكونًا إضافيًا جديدًا على منصة كبيرة، فستنخفض صعوبة الإطلاق البارد كثيرًا.</p><ul><li>في مجال التجارة الإلكترونية، المتاجر الجديدة التي تستقر في منصات مثل Taobao، وPinduoduo، وJD، لا تحتاج على الأقل إلى بناء أنظمة الدفع، والخدمات اللوجستية، والتقييمات من الصفر. تتضمن الطرق الشائعة الاستخدام أثناء الإطلاق البارد المبيعات عبر المؤثرين، والترويج داخل المنصة وأماكن الأنشطة، والبث المباشر، وما إلى ذلك</li><li>بالنسبة لتطبيقات الأدوات والمحتوى، يمكنك من خلال تطوير مكونات إضافية وأدوات صغيرة للمنصات الناضجة، ووضع الخدمات عبر الإنترنت في سوق القدرات للمنصات المفتوحة، جعل المستخدمين الذين لديهم بالفعل احتياجات واضحة يجدونك بسهولة أكبر المنطق الكامن وراء هذا الطريق هو <strong>الاعتراف بأن المنصات الكبرى قد جمعت المستخدمين بالفعل في سيناريوهات محددة، وأن ما عليك فعله هو العثور على الزاوية الصغيرة التي تتطابق مع منتجك داخل هذه السيناريوهات</strong>. الاستعانة بالقوة لا تعني التخلي عن الاستقلالية، بل هي استخدام طريقة أكثر واقعية لفتح الوضع خلال مرحلة الإطلاق البارد.</li></ul><h2 id="_5-4-المفاضلة-عندما-تكون-الموارد-محدودة-التركيز-فقط-على-الجزء-الأكثر-أهمية-في-مرحلة-0–1" tabindex="-1">5.4 المفاضلة عندما تكون الموارد محدودة: التركيز فقط على الجزء الأكثر أهمية في مرحلة 0–1 <a class="header-anchor" href="#_5-4-المفاضلة-عندما-تكون-الموارد-محدودة-التركيز-فقط-على-الجزء-الأكثر-أهمية-في-مرحلة-0–1" aria-label="Permalink to “5.4 المفاضلة عندما تكون الموارد محدودة: التركيز فقط على الجزء الأكثر أهمية في مرحلة 0–1”">​</a></h2><p>عندما تتأكد من أنك لا تزال في مرحلة 0–1، وتفهم بوضوح من تخدم، وتختار تقريبًا مسار الإطلاق البارد، لتكتشف أن الموارد لا تكفي على الإطلاق.</p><p>الموارد هنا ليست فقط المال، بل تشمل أيضًا الوقت والطاقة والأيدي العاملة والانتباه والعلاقات والقنوات. في مرحلة الإطلاق البارد، إذا بدأت بالتفكير في &quot;تجربة مسارات متعددة معًا&quot;، فغالبًا ما تكون النتيجة: أنك مشغول جدًا كل يوم، وتنجز الكثير من الأشياء، لكن دون التعمق في أي مسار، وفي النهاية لا تحصل على نتائج مقنعة ولا تفهم المستخدمين حقًا.</p><p>في هذه المرحلة، تحتاج إلى التقليص بشكل متعمد. الهدف ليس &quot;القيام بالكثير&quot;، بل &quot;إتقان الجزء الأكثر أهمية فقط&quot;. يمكنك إعادة بناء طريقة عملك من ثلاث زوايا.</p><h3 id="من-الهدف-إلى-المهمة-المحددة" tabindex="-1">من الهدف إلى المهمة المحددة <a class="header-anchor" href="#من-الهدف-إلى-المهمة-المحددة" aria-label="Permalink to “من الهدف إلى المهمة المحددة”">​</a></h3><p>كثير من الناس يضعون لأنفسهم أهدافًا خلال الإطلاق البارد مثل &quot;لنرى أولاً رد فعل السوق&quot;، أو &quot;لنبدأ بجمع المستخدمين أولاً&quot;، أو &quot;لنجذب مجموعة من الأشخاص للتجربة&quot;. هذه الأقوال عامة جدًا، ومن الصعب عليك الحكم على ما إذا كانت الأشياء التي تقوم بها كل يوم تقربك حقًا من هذا الهدف.</p><p>الطريقة الأكثر عملية هي تقليص الهدف إلى أمر صغير ومحدد، على سبيل المثال: خلال الأسابيع الأربعة القادمة، دع عشرين مستخدمًا حقيقيًا يتطابقون مع الملف المستهدف، يستخدمون تطبيقك بشكل متكرر وكامل في سيناريوهاتهم الحقيقية، والحصول على تعليقات محددة بما فيه الكفاية منهم.</p><p><strong>ما يسمى بـ &quot;الجمهور المتخصص&quot; ليس &quot;أي شخص قد يستخدم هذا النوع من الأدوات&quot;، بل هو مجموعة من الأشخاص يمكنك وصفهم بدقة بناءً على سمة محددة.</strong> على سبيل المثال، إذا كنت تصنع أداة تساعد الأشخاص على إنشاء تقارير العمل، فيمكن أن يكون الهدف &quot;الموظفين في مجال العمليات التشغيلية للإنترنت بخبرة تتراوح بين سنة وثلاث سنوات&quot;، بدلاً من &quot;المحترفين&quot; بشكل عام. لدى هذه المجموعة عدة نقاط مشتركة: هم بالفعل بحاجة إلى إعداد تقارير كل شهر، ووقتهم محدود، ويريدون أن يبدو المحتوى احترافيًا بعض الشيء، ومشاكلهم محددة ومستمرة.</p><p><strong>&quot;مهمة الاستخدام الكامل&quot; لا يمكن أن تكون غامضة أيضًا</strong>. بأخذ أداة إعداد التقارير هذه كمثال، قد تكون المهمة الكاملة هي: يقوم المستخدم بتنظيم بيانات ومواد العمليات التشغيلية للأسبوع الماضي، واستيرادها إلى الأداة، وإنشاء مسودة أولى، ثم تعديلها لجلستين أو ثلاث بناءً على الهيكل والنقاط الموصى بها، وأخيرًا تصديرها كعرض تقديمي (PPT) أو مستند، واستخدامها فعليًا في اجتماع القسم. إذا قام المستخدم بالنقر بضع نقرات عشوائية فقط، ليرى الشكل العام، ثم أغلقها ولم يعد لفتحها، فهذا لا يُحتسب استخدامًا كاملاً.</p><p>يجب أن تكون التعليقات المحددة مفصلة بما فيه الكفاية. على سبيل المثال:</p><ul><li>عند استيراد البيانات، هل هناك أي خطوة لم يفهموها، أو لم يجدوا مدخلها، أو ينقرون فيها بالخطأ دائمًا؛</li><li>هل الهيكل المُنشأ قريب من عادات إعداد التقارير في شركتهم، على سبيل المثال، هل يحتوي على تنسيق &quot;الخلفية - الهدف - العملية - النتيجة&quot; الذي يحتاجونه؛</li><li>أي الصفحات يستخدمونها فعليًا، وأي الصفحات يحذفونها في كل مرة؛</li><li>بعد الاستخدام، هل يمكنهم الشعور بوضوح بأن وقت التحضير لتقرير واحد قد انخفض من ثلاث ساعات إلى ساعة واحدة، أم أنهم يشعرون فقط بأنه &quot;يبدو أكثر راحة بعض الشيء، لكن لا يمكنهم تحديد ذلك&quot;.</li></ul><h3 id="لا-تحاول-تجربة-كل-شيء" tabindex="-1">لا تحاول تجربة كل شيء <a class="header-anchor" href="#لا-تحاول-تجربة-كل-شيء" aria-label="Permalink to “لا تحاول تجربة كل شيء”">​</a></h3><p>بعد تحديد &quot;الهدف الصغير&quot;، تكون المشكلة التالية هي: ما هي الطريقة التي ستستخدمها للعثور على هؤلاء المستخدمين العشرين، ومرافقتهم لتجربة السيناريو الحقيقي.</p><p>هناك العديد من طرق الإطلاق البارد: كتابة المحتوى، بناء المجتمعات، الإعلانات، إيجاد المؤثرين، البحث عن المؤسسات، الصعود إلى المنصات. ولكن في ظل الموارد المحدودة، ما تحتاجه ليس معرفة عدد الطرق المتاحة، بل <strong>أي طريقة هي الأكثر طبيعية بالنسبة لك الآن، وأسهل طريقة يمكنك الاستمرار فيها.</strong></p><p>إذا كنت معتادًا على كتابة المقالات الطويلة، ولديك مجموعة من الأشخاص سيقرأون مقالاتك بعناية، فيمكنك البدء بالمحتوى أولاً. على سبيل المثال، اكتب سجلًا عمليًا محددًا جدًا، يتحدث عن كيفية استخدامك لهذه الأداة للتحضير لتقرير شهري حقيقي: بدءًا من الحصول على البيانات الخام، إلى بناء الهيكل، إلى إنشاء المسودة، إلى تعديل التفاصيل، ثم تشغيلها فعليًا في غرفة الاجتماعات. يمكنك إدراج بعض لقطات الشاشة المقارنة في المنتصف، لإظهار الفروق في الوقت والتأثير والتنظيم قبل وبعد استخدام الأداة. لا تضع رابط تحميل باردًا فقط في نهاية المقال، بل قل بوضوح: إذا كنت تقوم أيضًا بإعداد تقارير العمليات التشغيلية، ومستعد للعمل معي على تحسين هذه الأداة، يمكنك إضافتي أو ملء نموذج بسيط، وسأختار عشرين شخصًا للمتابعة معهم بشكل فردي.</p><p>إذا كنت تتحكم في العديد من المجتمعات المستقرة، مثل مجموعة تبادل العمليات التشغيلية، أو مجموعة خريجين مهنيين، فمن الأنسب لك البدء من هذه &quot;المناطق الخاصة&quot;. يمكنك أن تقول بصراحة في المجموعة: أنا أقوم بصنع أداة تساعد الأشخاص على إنشاء التقارير، وقد بدأت للتو في العمل، لكنها لا تزال بدائية جدًا، والآن أريد أن أجد مجموعة من الأشخاص الذين لديهم بالفعل حاجة إلى إعداد التقارير، لمرافقتي لاستخدامها بسلاسة. من بين المتطوعين، يمكنك بعد ذلك اختيار المجموعة الأكثر تطابقًا بناءً على المنصب وطبيعة العمل، وإنشاء مجموعة صغيرة منفصلة، ودعوتهم لتجربتها، وإرسال لقطات الشاشة، والتعبير عن استيائهم، وتقديم الاقتراحات، وقضاء الوقت كل يوم في متابعة ذلك.</p><p>إذا كان لديك connections في صناعة عمودية معينة، على سبيل المثال، إذا كانت لديك علاقة جيدة مع بعض معلمي مؤسسات التدريب، أو تعرف مدير أعمال في شركة صغيرة ومتوسطة، فيمكنك إجراء تجربة пилوتية في فصل دراسي أو فريق صغير. يمكن أن تكون الممارسة المحددة: اقتراح خطة تجربة واضحة، على سبيل المثال، في الشهر القادم، سيحاول هذا الفريق استخدام أداتك لإنشاء جميع التقارير الأسبوعية، وتوفر أنت الدعم والتعديلات في الوقت الفعلي، وفي المقابل، يعقدون معك اجتماعًا صغيرًا مدته عشر دقائق كل أسبوع ليخبروك بأكثر الأجزاء سهولة وأكثرها صعوبة في الاستخدام.</p><h3 id="قم-بصقل-الجزء-الأهم-فقط" tabindex="-1">قم بصقل الجزء الأهم فقط <a class="header-anchor" href="#قم-بصقل-الجزء-الأهم-فقط" aria-label="Permalink to “قم بصقل الجزء الأهم فقط”">​</a></h3><p>عندما يكون لديك هدف صغير، وتكون قد اخترت المسار الرئيسي، فإن الشيء التالي الذي يجب عليك فعله هو فرض قيد على نفسك بألا تفعل إلا هذا الجزء الصغير فقط.</p><p>السمة المشتركة للعديد من الفرق في مرحلة الإطلاق البارد هي: القلق. بمجرد أن يبدأ القلق، من السهل جدًا البحث عن أفعال جديدة: هل يجب علينا أيضًا إنشاء حساب فيديو قصير وتصوير بعض دروس الاستخدام؛ هل يجب علينا إنفاق جزء صغير من الميزانية على إعلان تجريبي صغير؛ هل يجب علينا التواصل مع وسائل إعلام لمعرفة ما إذا كان بإمكانهم كتابة مقال إخباري. <strong>كل شيء يبدو لا غبار عليه، ولكن النتيجة المجتمعة هي أنك تغير الاتجاه كل يوم، ولم تغص في أي مسار أبدًا.</strong></p><p><strong>يمكنك وضع قيد مرحلي محدد جدًا لنفسك، على سبيل المثال في الأسابيع الأربعة القادمة، سأركز فقط على القيام بأمرين</strong>: أولاً، التحسين المتكرر لتجربة الاستخدام في السيناريوهات الحقيقية حول هؤلاء المستخدمين العشرين، لتحويلها من &quot;بالكاد تعمل&quot; إلى &quot;سهلة الاستخدام بشكل أساسي&quot;؛ ثانيًا، على طول المسار الرئيسي الذي اخترته، استمر في العثور على عدد صغير من المستخدمين الجدد، وتسجيل سلوكهم وتعليقاتهم، لمعرفة أوجه التشابه والاختلاف بينهم وبين الدفعة السابقة.</p><p>خلال هذه الأسابيع الأربعة، عندما تواجه أي فكرة جديدة أو فرصة جديدة، اسأل نفسك أولاً: هل هذا الشيء، هل يمكنه أن يدفع بشكل كبير هؤلاء المستخدمين العشرين لاستخدام المنتج بشكل أفضل خلال هذه الفترة، أو أن يساعدني بوضوح في العثور على الدفعة التالية من المستخدمين المماثلين؟</p><p>وراء هذه الممارسة، يكمن اعتراف بطبيعة الإطلاق البارد: المعلومات التي تمتلكها في يدك محدودة جدًا، ولا يمكنك اتخاذ قرارات جيدة في العديد من الاتجاهات في نفس الوقت. بدلاً من القيام بقليل من كل شيء في عشرة أماكن، من الأفضل القيام بتحسينات قابلة للتحقق المتكرر في سيناريو محدد ومجموعة محددة. على سبيل المثال، يمكنك أن ترى بوضوح: أنه بالنسبة لهذه المجموعة من الموظفين الجدد في العمليات التشغيلية، قامت الأداة بالفعل بتقليل وقت التحضير للتقرير، وجعلتهم بالفعل أكثر قدرة على توضيح النقاط الرئيسية.</p><p>تحتاج إلى إتمام حلقة مفرغة من &quot;<strong>إيجاد المستخدمين → توجيه الاستخدام → جمع التعليقات → تحسين التجربة → المستخدمون على استمرار للاستخدام</strong>&quot;. بعد ذلك ستعرف فقط أي نوع من المستخدمين يجب أن تبحث عنه، وما هي اللغة التي تستخدمها للتواصل معهم، في أي مرحلة تحدث أكثر المشاكل، وما هي التعديلات التي يمكنك إجراؤها لإعادتهم. عندما يصبح هذا المسار سلسًا بالنسبة لك، عندها فقط يكون من المناسب التفكير في إضافة قناة جديدة أو تجربة نوع جديد من التعاون.</p><h1 id="ملخص" tabindex="-1">ملخص <a class="header-anchor" href="#ملخص" aria-label="Permalink to “ملخص”">​</a></h1><p>بالعودة إلى السؤال الأصلي: أريد إنشاء تطبيق، من أين أبدأ هذا الأمر بالضبط، ليكون بداية موثوقة.</p><p>كل محتوى هذه المقالة يدور في الواقع حول خط رئيسي واحد: <strong>اكتشف أولاً ما هي الفكرة، ثم انظر في علاقتها باحتياجات المستخدم، ثم قم بتفكيكها خطوة بخطوة إلى مسار استخدام كامل يمكن بناؤه، واستخدامه، وصقله، وتضخيمه بالذكاء الاصطناعي، وإيجاد المستخدمين له.</strong></p><p>في الفصل الأول، بدأنا من الفكرة نفسها، الفكرة لم تعد مجرد تلك الجملة التي تبدو رائعة في رأسك، بل يجب أن تكون موجهة نوع محدد وواضح من المستخدمين، <strong>متأصلة في سيناريو محدد، لمساعدتهم في إنجاز مهمة محددة، وتقديم نهج أفضل من الوضع الراهن</strong>. تعلمت أن تفحص أفكارك من أربعة أبعاد: <strong>طريقة اللعب، رحلة المستخدم، ماذا تفعل، وما هي المشكلة التي تحلها</strong>، وبدأت أيضًا تدرك أن هناك فجوة يسهل تجاهلها بين الفكرة واحتياجات المستخدم. لقد قمعت دافع الإعجاب بنفسك، وبدأت في التمييز بين الاحتياجات الحقيقية والاحتياجات المزيفة، واعترفت بأن الأفكار الجيدة والسيئة لديها اختلافات في المصير منذ البداية. بعد ذلك، لم تعد تنتظر الإلهام بشكل سلبي، بل تعلمت استخراج القرائح بنشاط من حياتك التي تحبها، وأصول الأشخاص من حولك، والفضاءات العامة، والمنتجات الموجودة؛ وعلاوة على ذلك، تدربت على تلخيص جوهر الفكرة في جملة واحدة، واستخدام الذكاء الاصطناعي لجلسات العصف الذهني، للعثور على التمايز الخاص بك في الجمهور والسيناريو ضمن الاتجاهات الشائعة.</p><p>ثم في الفصل الثاني، لم تعد تتوقف عند التفكير، بل <strong>بدأت في تعلم كيف تبدأ العمل عمليًا</strong>. تعلمت التبديل ذهابًا وإيابًا بين **التباعد و**<strong>التقارب</strong>، واستخدام نهج الماس المزدوج لنشر الأفكار أولاً، ثم <strong>تضييقها إلى مسار عملي حقيقي</strong> بناءً على قيمة المستخدم والجدوى وتكلفة الوقت. تدربت على <strong>الانتقال من التجريد إلى الواقع</strong>، وتفكيك الرغبات الغامضة مثل &quot;أريد إنشاء تطبيق لتحسين الكفاءة&quot; خطوة بخطوة إلى عناصر قابلة للتنفيذ بحد أدنى، حتى يصبح كل إجراء مهمة يمكنك البدء بها اليوم. أخذت السبورة أو الورقة والقلم، رسمت أولاً ثم بنيت، وقسمت التطبيق إلى صفحة رئيسية، صفحة عمليات، وصفحة نتائج، ورسمت الرحلة الكاملة للمستخدم من الدخول إلى الحصول على النتيجة. ولن تعتبر مراجعة الآخرين بعد الآن مجرد نسخ للواجب المنزلي، بل ستبدأ **بوعي في تحليل التنقل، والنماذج، وعرض النتائج، وعمليات التوجيه الخاصة بالآخرين، والاستفادة من الخبرات الجاهزة**. في نفس الوقت، لن تنتظر حتى يكتمل المنتج بالكامل لتسأل المستخدمين، بل في مرحلة النموذج الأولي والمنتج النصف نهائي، ستسأل وأنت ترسم، وتسأل وأنت تبني بوعي، مما يسمح للمستخدمين الحقيقيين بالتدخل في تصميمك في أقرب وقت ممكن. في الفصل الثالث، بدأت ببطء في بناء مجموعة من المعايير الخاصة بك للتمييز بين ما هو صالح للاستخدام فقط وما يمكن اعتباره جيدًا حقًا. أنت <strong>لم تعد تقول بشكل غامض أن هذا التطبيق ليس سيئًا، بل تنظر تحديدًا فيما إذا كان قد ساعد المستخدمين على توفير الوقت، أم خفض معدل الخطأ، أم قلل تكلفة التواصل، أم خفف العبء الذهني</strong>. أنت تعلم أن <strong>التطبيق الجيد يجب أن يمكّن المستخدمين من استخدامه تقريبًا دون الحاجة إلى دليل استخدام</strong>، وفي السيناريوهات الرئيسية سيتذكرك المستخدم بشكل طبيعي، كما تفهم النية الحقيقية لفعل الخير الكامنة وراء التطبيق الجيد. بدأت في تفكيك المشاكل الفعلية ونقاط ألم المستخدم إلى مستوى التكلفة الحدية، لتمييز ما إذا كان الاستهلاك وراء ذلك يتمثل في الوقت، أم المال، أم الجهد الذهني، أم المخاطر. في الوقت نفسه، اكتسبت فهمًا أوليًا لـ <strong>الاختلافات بين C-end و B-end</strong>، وأدركت أن الأول يهتم أكثر بالقيمة العاطفية والانتشار، بينما الثاني يركز أكثر على الكفاءة والتكلفة والمخاطر والامتثال. لم تعد تعتمد فقط على إعجابك الشخصي، بل قمت ببناء آلية بسيطة للحصول على ملاحظات، واستخدام ثلاثة أنواع من المؤشرات: الاحتفاظ، وإعادة الزيارة، والتوصية، للحكم على ما إذا كان هذا الشيء يستحق الاستمرار في الاستثمار فيه، ومن خلال ملاحظات المستخدمين المتكررة، تقوم بصقل التطبيق من &quot;أعتقد أنه جيد&quot; إلى &quot;المستخدم يعتقد أنه جيد&quot;.</p><p>عند الوصول إلى الفصل الرابع، قمت بتوسيع منظورك من المنتج البحت إلى إمكانيات الذكاء الاصطناعي. <strong>قمعت أولاً تلك الرغبة الملحة في استخدام الذكاء الاصطناعي لمجرد استخدام الذكاء الاصطناعي</strong>، وسألت نفسك بجدية عن أمرين: بدون الذكاء الاصطناعي، هل لا يزال هذا التطبيق قابلاً للتطبيق؛ ومع استخدام الذكاء الاصطناعي، ما الذي تم تحسينه تحديدًا. أنت على دراية بالقدرات والحدود الأساسية للذكاء الاصطناعي في النصوص والصور ومقاطع الفيديو والأتمتة، وتعرف الأماكن التي يمكن فيها ترك الأمر للنموذج، والأماكن التي يجب أن يكون فيها تدقيق بشري. لن تكتفي فقط بمستوى تنفيذ الوظائف، بل ستركز على بعض المؤشرات الجوهرية: هل تم تقصير وقت إنجاز المهمة، هل تحسنت جودة النتائج، هل زادت وتيرة الاستخدام، وهل المستخدمون على استعداد لدفع رسوم منفصلة مقابل ميزات الذكاء الاصطناعي.</p><p>أخيرًا، في الفصل الخامس، يتم ربط كل هذا مرة أخرى بمشكلة واقعية: حتى لو كان لديك بالفعل تطبيق جيد جدًا، أو حتى تطبيق يستخدم الذكاء الاصطناعي، فبدون مستخدمين، ستظل قيمته صفرًا. <strong>تعلمت أولاً التمييز بين المرحلتين 0–1 و 1–N، والتخلي مؤقتًا عن جميع الأسئلة الضخمة المتعلقة بالتوسع والعلامة التجارية والمؤسسة، والتركيز على أمر واحد: إيجاد طريقة لجعل عشرين مستخدمًا حقيقيًا يستخدمونه أولاً</strong>، وعلى استعداد للعودة بعد الانتهاء. لم تعد تلقي الشبكة بشكل أعمى، بل تبدأ الانطلاق البارد على طول ثلاثة خطوط رئيسية: استخدام المجتمعات المحيطة بك، والأقران، والأصدقاء، لجمع المستخدمين الأوائل ببطء؛ استخدام المحتوى والمزايا المحدودة لجذب أول دفعة من الأشخاص المستعدين لتجربة أشياء جديدة؛ والاستفادة من المنصات والقنوات الحالية لبناء مدخل لنفسك في الأماكن التي يمتلك فيها الآخرون بالفعل حركة مرور. كما تبدأ في تفكيك استراتيجيات الانطلاق البارد بناءً على الكائن المستهدف، والتمييز بين المستخدمين الأوائل، ومقدمي العرض، ومصادر حركة المرور، وأصحاب القنوات، واستخدام طرق مختلفة لكل منهم. عندما تكون الموارد محدودة، لم تعد ترغب في تجربة كل شيء دفعة واحدة، بل ترى بوضوح المسار الأكثر كفاءة والأسهل في البدء بين يديك، وتسلك هذا المسار أولاً بعمق وشمولية، بدلاً من فتح عشر قنوات غير مكتملة بنفس واحد.</p><p>إذا جمعت كل هذا المحتوى معًا، فستجد أن المنهجية بأكملها ليست غامضة: **الانطلاق من فكرة موثوقة، والتأكد من تجذرها في احتياجات حقيقية؛ استخدام طرق الرسم، والكتابة، والتفكيك، لـ****تقليص** <strong>إلى تطبيق أصغر قابل للتطبيق؛ استخدام المستخدمين الحقيقيين والمؤشرات الواضحة، لصقله ببطء إلى تطبيق جيد؛ إدخال الذكاء الاصطناعي بشكل معقول في النقاط الرئيسية لتضخيم القيمة؛ أخيرًا، في ظل الموارد المحدودة، استخدام طريقة انطلاق باردة مناسبة للعثور على أول دفعة من الأشخاص المستعدين للدفع مقابلها</strong>.</p><p>في الخطوة التالية، تحتاج فقط إلى التخلي عن الأوهام المفرطة، واختيار أحدها بشكل واقعي لبنائه وإطلاقه، والسماح له بالدخول إلى العالم الحقيقي للاختبار. <strong>جميع المناقشات حول الأفكار، والمنهجيات، والذكاء الاصطناعي، والنمو، يجب أن تترسخ في النهاية على شخص محدد، وفي سيناريو محدد، وعلى مهمة محددة.</strong></p><p>لهذا السبب، لا بأس إذا كان ما قمت به في البداية خشنًا، ولا بأس إذا كانت الوظائف غير مكتملة، أو العملية متصلبة، أو الواجهة بسيطة؛ ولا بأس أيضًا إذا قمت بالترويج لفترة طويلة ولم يهتم بك أحد، ناهيك عن استعداد أي شخص للتسجيل والدفع. كل هذه مجرد حالات في العملية، وليست استنتاجات نهائية؛ إنها تخبرك فقط بكيفية التعديل في الخطوة التالية، وما هو مهم حقًا هو أن تحرز تقدمًا، فأثناء العملية تحتاج إلى المراجعة المستمرة، والتلخيص، ورفع الحد الأقصى، والتعرف على المزيد من الأشخاص المستعدين لتقديم النصائح لك.</p><p>في هذه المرحلة، في رأي الكاتب، فقط استمتع بالعملية. كما تقول لعبة قصة إلكترونية شهيرة &quot;To the Moon&quot;:</p><p><strong><em>&quot;The ending isn&#39;t any more important than any of the moments leading to it.&quot;</em></strong></p><p><strong><em>النهاية لن تكون أهم من العملية أبدًا.</em></strong></p><p><img src="'+F+'" alt=""></p>',474))])}}});export{V as __pageData,v as default};
